globalThis.OOIRulebookData={"schema":1,"version":"0.28.34","source":"Of Oil and Iron Rulebook V1 (user supplied)","sourceSHA256":"e80b13288a4b48cf7fa7396879d1351f402b6192b1d6f7d998a2566fe526066e","pageCount":121,"numberedPageMax":115,"toc":[{"title":"Cover","index":1},{"title":"Introduction","index":8},{"title":"Timeline of the Smoglands","index":10},{"title":"Getting Started","index":18},{"title":"Core Rules","index":26},{"title":"Rig Control Terminal","index":27},{"title":"Weapons and Equipment","index":28},{"title":"Engine and Heat","index":29},{"title":"Playing the Game","index":30},{"title":"Activation and Action Points","index":31},{"title":"Attacking and Damage","index":33},{"title":"Catastrophic Damage","index":34},{"title":"Rig Destruction","index":36},{"title":"Maintenance Phase","index":37},{"title":"Conditions","index":38},{"title":"Example Turn","index":40},{"title":"Rig Operating Manual","index":44},{"title":"Ironclads","index":48},{"title":"Weapon Perks","index":49},{"title":"Common Weapons","index":51},{"title":"Krim Corporation","index":52},{"title":"Nox Industries","index":58},{"title":"Triton Engineering","index":64},{"title":"Arcus Technologies","index":70},{"title":"Freegear Coalition","index":76},{"title":"Mercenary Nomads","index":82},{"title":"Equipment List","index":88},{"title":"Deploying to War and Formations","index":92},{"title":"Deployments","index":96},{"title":"Engagements","index":98},{"title":"Campaign","index":104},{"title":"Quick Reference","index":114},{"title":"Rules Glossary","index":116}],"pages":[{"index":1,"number":null,"label":"Front cover","title":"Cover","width":2000,"height":2829,"blocks":[{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":2,"number":null,"label":"Inside cover","title":"Illustration","width":2000,"height":2829,"blocks":[{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":3,"number":null,"label":"Title page","title":"A DIESELPUNK MECHA SKIRMISH WARGAME","width":2000,"height":2829,"blocks":[{"text":"A DIESELPUNK MECHA SKIRMISH WARGAME","box":[0.26818,0.79783,0.7318,0.81922]},{"text":"By Scott Hadley","box":[0.41984,0.83714,0.58015,0.85496]},{"text":"Version 1.O","box":[0.43683,0.40709,0.56316,0.42848]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":4,"number":1,"label":"1","title":"OF OIL & IRON","width":2000,"height":2829,"blocks":[{"text":"OF OIL & IRON","box":[0.43235,0.09629,0.56764,0.11055]},{"text":"First Edition, 2026","box":[0.4253,0.12765,0.57469,0.14191]},{"text":"World and model design by Scott Hadley\nWritten, illustrated and designed by Scott Hadley","box":[0.30267,0.19037,0.69732,0.22173]},{"text":"Rules revision and editing by Ian Hawkins","box":[0.33047,0.22458,0.66952,0.23883]},{"text":"Published by Scoutsifer Studio","box":[0.37767,0.25879,0.62232,0.27304]},{"text":"© Scott Hadley, 2026","box":[0.41607,0.29014,0.58393,0.3044]},{"text":"All rights reserved. No part of this publication may be reproduced, stored, or transmitted in any","box":[0.11589,0.3215,0.88867,0.33576]},{"text":"form or by any means, electronic, mechanical, photocopying, recording, or otherwise, without","box":[0.12253,0.33861,0.88204,0.35286]},{"text":"the prior written permission of the publisher, except as permitted under fair-use provisions.","box":[0.13269,0.35571,0.86731,0.36996]},{"text":"WWW.OFOILANDIRON.COM","box":[0.36545,0.41843,0.63455,0.43268]},{"text":"ABOUT THE AUTHOR","box":[0.11905,0.48119,0.30186,0.49425]},{"text":"Scott Hadley is the creator of Of Oil and Iron and founder of Scoutsifer Studio. With a background in \nmarine biology and a lifelong passion for the miniatures hobby, he began developing Of Oil and Iron as \na way to explore themes of industrial collapse, corporate power and resource scarcity through a unique \ndieselpunk setting shaped by exaggerated reflections of real-world history and modern global tensions \nbased on his life experiences.","box":[0.11905,0.51112,0.88515,0.5869]},{"text":"Scott handles the miniature sculpting, visual design, lore development, game design, and overall creative \ndirection of the project. His work is heavily inspired by industrial science fiction and retro-futurism.","box":[0.11905,0.60377,0.88514,0.63251]},{"text":"SPECIAL THANKS","box":[0.11905,0.66565,0.26577,0.67871]},{"text":"Thank you to everyone who supported Of Oil and Iron through Patreon, MyMiniFactory Tribes, \nKickstarter, and the wider community. Your support, feedback, enthusiasm, and creativity helped turn \nthis project from an idea into a living world.","box":[0.11905,0.69558,0.88514,0.74]},{"text":"Special thanks to Millie Proud, Daniel Martin, Thomas Cain, John Johansson and Eric Trein for their \nincredible support during conventions and events, helping bring Of Oil and Iron to life beyond the hobby \ndesk.","box":[0.11905,0.75687,0.88514,0.80129]},{"text":"Special thanks to Ian Hawkins for his invaluable support with rules revision and gameplay refinement \nthroughout development.","box":[0.11905,0.81816,0.88514,0.84691]},{"text":"And finally, thank you to everyone building Rigs, painting miniatures, and fighting battles across the \nSmoglands. This world exists because of you.","box":[0.11905,0.86377,0.88515,0.89252]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":5,"number":2,"label":"2","title":"Introduction……………………………..………………………","width":2000,"height":2829,"blocks":[{"text":"Introduction……………………………..………………………","box":[0.22344,0.14817,0.72732,0.16243]},{"text":"Timeline of the Smoglands……………………………………...","box":[0.22344,0.17953,0.72716,0.19378]},{"text":"Getting Started…………………………………………….…….","box":[0.22344,0.21089,0.72688,0.22514]},{"text":"Core Rules………………………………………………..……...","box":[0.22344,0.24225,0.72557,0.2565]},{"text":"Rig Control Terminal…………………………….……….……..","box":[0.22344,0.2736,0.72781,0.28786]},{"text":"Weapons and Equipment…………….…………,,……………..","box":[0.22344,0.30496,0.72303,0.31922]},{"text":"Engine and Heat…...……………………………….……………","box":[0.22344,0.33632,0.72821,0.35057]},{"text":"Playing the Game.………………………………………...……..","box":[0.22344,0.36768,0.72597,0.38193]},{"text":"Activation and Action Points..……………………………..……","box":[0.22344,0.39904,0.72924,0.41329]},{"text":"Attacking and Damage…………………………………..………","box":[0.22344,0.43039,0.72978,0.44465]},{"text":"Catastrophic Damage……………………………………………","box":[0.22344,0.46175,0.73,0.47601]},{"text":"Rig Destruction…………………………………………….……","box":[0.22344,0.49311,0.72839,0.50736]},{"text":"Conditions……………………………………………………….","box":[0.22344,0.52447,0.72912,0.53872]},{"text":"Example Turn……………………………………………………","box":[0.22344,0.55583,0.72886,0.57008]},{"text":"Rig Operating Manual…..………………………………………","box":[0.22344,0.58718,0.72607,0.60144]},{"text":"Equipment List…………………………………………………..","box":[0.22344,0.61854,0.72811,0.6328]},{"text":"Deploying to War………………………………………………..","box":[0.22344,0.6499,0.72652,0.66415]},{"text":"Deployments…………………………………………………….","box":[0.22344,0.68126,0.7266,0.69551]},{"text":"Engagements…………………………………………………….","box":[0.22344,0.71262,0.72664,0.72687]},{"text":"Campaign……………………………….……………………….","box":[0.22344,0.74397,0.72694,0.75823]},{"text":"Quick Reference.. ………..……………………………...………","box":[0.22344,0.77533,0.72601,0.78959]},{"text":"Rules Glossary…………………………………………………..","box":[0.22344,0.80669,0.72176,0.82094]},{"text":"CONTENTS","box":[0.45497,0.10093,0.54503,0.11993]},{"text":"5","box":[0.74074,0.14668,0.75041,0.16093]},{"text":"7","box":[0.74074,0.17804,0.75041,0.19229]},{"text":"15","box":[0.7359,0.20939,0.75525,0.22365]},{"text":"23","box":[0.7359,0.24075,0.75525,0.255]},{"text":"24","box":[0.7359,0.27211,0.75525,0.28636]},{"text":"25","box":[0.7359,0.30347,0.75525,0.31772]},{"text":"26","box":[0.7359,0.33483,0.75525,0.34908]},{"text":"27","box":[0.7359,0.36618,0.75525,0.38044]},{"text":"28","box":[0.7359,0.39754,0.75525,0.41179]},{"text":"30","box":[0.7359,0.4289,0.75525,0.44315]},{"text":"31","box":[0.7359,0.46026,0.75525,0.47451]},{"text":"33","box":[0.7359,0.49162,0.75525,0.50587]},{"text":"35","box":[0.7359,0.52297,0.75525,0.53723]},{"text":"37","box":[0.7359,0.55433,0.75525,0.56858]},{"text":"41","box":[0.7359,0.58569,0.75525,0.59994]},{"text":"85","box":[0.7359,0.61705,0.75525,0.6313]},{"text":"89","box":[0.7359,0.64841,0.75525,0.66266]},{"text":"93","box":[0.7359,0.67976,0.75525,0.69402]},{"text":"95","box":[0.7359,0.71112,0.75525,0.72538]},{"text":"101","box":[0.73106,0.74248,0.76009,0.75673]},{"text":"111","box":[0.73106,0.77384,0.76009,0.78809]},{"text":"113","box":[0.73106,0.8052,0.76009,0.81945]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":6,"number":3,"label":"3","title":"Illustration","width":2000,"height":2829,"blocks":[{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":7,"number":4,"label":"4","title":"Illustration","width":2000,"height":2829,"blocks":[{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":8,"number":5,"label":"5","title":"Introduction","width":2000,"height":2829,"blocks":[{"text":"The world is broken. Once-prosperous nations have crumbled beneath the weight of resource \nscarcity, unchecked industry, and resulting conflict. In their place rose the corporations: vast, \nruthless powers that carved the Smoglands into section of corporate rule. Oil fields, shattered \ncities, and desecrated frontiers are now the battlegrounds where dominion is won not by kings \nor nations, but by those who can field the most formidable machines of war.","box":[0.11905,0.71111,0.88553,0.79378]},{"text":"At the heart of this conflict stand the Rigs: colossal, diesel-fuelled war machines forged from the \nremnants of industry. Each is piloted by an Ironclad, a rare breed of operator whose skill and \nnerve decide whether their Rig becomes a weapon of victory or a tomb of twisted iron.","box":[0.11905,0.81088,0.88554,0.85935]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":9,"number":6,"label":"6","title":"No faction is virtuous, and none are without ambition. The oppressive Krim Corporation, the","width":2000,"height":2829,"blocks":[{"text":"No faction is virtuous, and none are without ambition. The oppressive Krim Corporation, the \nindustrious Nox Industries, the rebellious Freegear Coalition, the enigmatic Arcus \nTechnologies, the steadfast Triton Engineering - all march to claim their place in the Smoglands. \nAlliances are fleeting. Wars are endless. The Smoglands endure.","box":[0.11905,0.71111,0.88552,0.77667]},{"text":"Of Oil and Iron is a cinematic skirmish wargame that places you in command of a squadron of \nRigs on behalf of one of the great corporations or rebel factions. Each battle tells a story: \ndesperate duels across blasted lands, ambushes in ruined streets, and clashes of diesel-fuelled \nwar machines. Customise your Rigs, outthink your opponent, and make your name in the \nSmoglands.","box":[0.11905,0.79378,0.88553,0.87645]},{"text":"Welcome to the age Of Oil and Iron.","box":[0.11905,0.89355,0.40711,0.90781]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":10,"number":7,"label":"7","title":"Timeline of the Smoglands","width":2000,"height":2829,"blocks":[{"text":"Before the Smogfall (BSF)","box":[0.11905,0.15833,0.45633,0.18208]},{"text":"–200 to –150 BSF: The Expansion Age","box":[0.11905,0.1978,0.43542,0.21205]},{"text":"The world entered a golden age of extraction and invention. Newly discovered oil fields, oil wells \nin the ocean, and coal mines fed an industrial appetite that seemed insatiable. Entire landscapes \nwere gutted to fuel corporate furnaces. Small family-run workshops gave way to massive \ncorporate foundries, each larger and more ruthless than the last.","box":[0.11905,0.22916,0.88554,0.29472]},{"text":"The first mechanised frames, precursors to the modern Rig, were developed not for war, but for \nmining, salvage, and underwater construction. These cumbersome suits were designed to keep \nworkers alive in hostile work sites, a grim foreshadowing of their eventual role in the battlefield.","box":[0.11905,0.31183,0.88552,0.36029]},{"text":"–149 to –50 BSF: The Rivalry Era","box":[0.11905,0.40875,0.39506,0.42301]},{"text":"Corporations grew too powerful for governments to contain. National armies were quietly \nreplaced by corporate security divisions, each fielding armoured vehicles and prototype exo-\nframes.","box":[0.11905,0.44011,0.88553,0.48857]},{"text":"Competition for resources turned violent. Oilfields were poisoned with sabotage, rail lines cut \nby mercenary bands, and whole towns enslaved into industrial labour. Rivalries between \ncorporations became entrenched; names like The Krim Corporation, Nox Industries, and Triton \nEngineering began appearing in ledgers of war rather than commerce.","box":[0.11905,0.50568,0.88553,0.57124]},{"text":"Civilians adapted to worsening air quality with crude respirators and filtration systems, but the \npoor suffocated in growing slums. For the wealthy elite, the choking haze was dismissed as the \n“price of progress.”","box":[0.11905,0.58835,0.88553,0.63681]},{"text":"–49 to 0 BSF: The Descent","box":[0.11905,0.68527,0.33615,0.69953]},{"text":"Warnings came from engineers, scientists, and a small consortium of researchers who would \nlater become known as Arcus Technologies. They published studies showing that unchecked \nindustry was poisoning the skies beyond repair. Their prototypes for advanced filtration towers \nand experimental arc-reactors were dismissed as impractical, too costly, or simply a threat to \ncorporate profits.","box":[0.11905,0.71663,0.88553,0.7993]},{"text":"While the great powers doubled down on extraction, those who founded Arcus retreated into \nisolated laboratories, continuing their work in secret. Cities by now were already cloaked in \npermanent dusk. Farmers abandoned dying fields, joining mass migrations toward corporate \nhubs in hopes of filtered shelter. Riots, food shortages, and industrial disasters spread \nunchecked.","box":[0.11905,0.81641,0.88553,0.89908]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":11,"number":8,"label":"8","title":"As the world teetered on the edge, only a handful of Arcus’ crude filtration prototypes were","width":2000,"height":2829,"blocks":[{"text":"As the world teetered on the edge, only a handful of Arcus’ crude filtration prototypes were \nquietly installed on the fringes of the industrial belts, faint glimmers of foresight in an age of \ndenial.","box":[0.11905,0.08396,0.88553,0.13242]},{"text":"Year 0: The Smogfall","box":[0.11905,0.18089,0.29116,0.19514]},{"text":"The great industrial expansion reached its breaking point. Factories and refineries belched out \nsuch vast quantities of soot and chemical fumes that the skies blackened for months on end. \nDaylight dimmed to a perpetual dusk; the sun became little more than a dull ember behind the \nhaze.","box":[0.11905,0.21224,0.88553,0.27781]},{"text":"Crops withered in the poisoned fields. Populations suffocated in their homes. Entire regions \nbecame uninhabitable without respirators or advanced filtration systems. Governments faltered, \npowerless to shield their people from the creeping death that spread through the air.","box":[0.11905,0.29492,0.88552,0.34338]},{"text":"Those who survived did so only behind walls of industry, under the rule of corporations who \nalone had the means to filter the choking sky. From this moment on, history was no longer \nmeasured by kings, parliaments, or nations, but by the smog. The old world as it was ended here.","box":[0.11905,0.36048,0.88552,0.40894]},{"text":"From then on, all time was reckoned as “After the Smogfall” (ASF).","box":[0.11905,0.45741,0.65508,0.47166]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":12,"number":9,"label":"9","title":"AFTER the Smogfall (ASF)","width":2000,"height":2829,"blocks":[{"text":"AFTER the Smogfall (ASF)","box":[0.11905,0.08233,0.43946,0.10609]},{"text":"0–50 ASF: The Survival Era","box":[0.11905,0.1218,0.34775,0.13606]},{"text":"Civilisation contracted into islands of life amid a sea of poison. Cities that could not filter the air \nwere abandoned or left to rot. Corporations seized control of the remaining habitable zones, \nruling through strict rationing of air, water, food and fuel.","box":[0.11905,0.15316,0.88552,0.20162]},{"text":"The first militarised Rigs were deployed, modified industrial suits refitted with armour plates \nand salvaged weaponry. They defended settlements from raiders, scoured wastelands for \nresources, and enforced corporate law.","box":[0.11905,0.21873,0.88553,0.26719]},{"text":"It was during this period that the nomads emerged: mercenary Rig pilots who refused corporate \nallegiance. Some fought for coin, others simply to survive outside the walls of industry.","box":[0.11905,0.2843,0.88552,0.31565]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":13,"number":10,"label":"10","title":"51–120 ASF: The Corporate Ascendancy","width":2000,"height":2829,"blocks":[{"text":"51–120 ASF: The Corporate Ascendancy","box":[0.11905,0.08383,0.45646,0.09809]},{"text":"With governments gone, the great corporations rose as the unquestioned rulers of the \nSmoglands. The great corporations expanded their fortified enclaves into sprawling fortress-\ncities, sealing their citizens behind walls of iron and filtered air. Economies were rebuilt around \nsalvage, oil drilling, and the mass production of war machines. For most, survival meant \nobedience.","box":[0.11905,0.11519,0.88553,0.19786]},{"text":"But not all bent the knee. Outcasts, deserters, and entire communities who opposed these ideals \nbegan to gather in the wastes. Salvagers, mechanics, and disillusioned Ironclads pooled their \nknowledge, building independent organisations powered by scrap and ingenuity. These groups \nrejected the corporate monopoly on life itself.","box":[0.11905,0.21497,0.88553,0.28053]},{"text":"From this growing defiance emerged the Freegear Coalition: a loose but determined federation \nbound together not by profit, but by survival and choice. While the corporations hardened their \nborders, Freegear’s rebels roamed the Smoglands, striking corporate supply lines, salvaging the \nruins, and offering refuge to those who refused to live under corporate law.","box":[0.11905,0.29764,0.88552,0.3632]},{"text":"121–200 ASF: The Age of Endless War","box":[0.11905,0.41167,0.43665,0.42592]},{"text":"By now, war was no longer an occasional necessity but the driving force of society. Factions bled \nresources into building colossal Rigs, some the size of towers, armed with weapons capable of \nlevelling city blocks.","box":[0.11905,0.44302,0.88554,0.49149]},{"text":"Territory changed hands constantly, though rarely rebuilt; burned-out cities became battlefields \nfought over again and again. Salvage became more valuable than raw ore, as it was easier to strip \nparts from wrecked Rigs than manufacture them anew.","box":[0.11905,0.50859,0.88552,0.55705]},{"text":"Citizens adapted to living in near-constant siege. Entire generations grew up in bunkers, never \nknowing clear skies or peace. To live in the Smoglands was to know conflict.","box":[0.11905,0.57416,0.88551,0.60552]},{"text":"201 ASF – Present: The Age of Oil and Iron","box":[0.11905,0.65398,0.47932,0.66823]},{"text":"The Smoglands now stand on a knife’s edge. The great corporations continue to fight, their wars \nfuelled more by ideology and pride than by strategy. Mercenary Nomads thrive, playing one side \nagainst another, while scavenger bands pick over battlefields like carrion crows.","box":[0.11905,0.68534,0.88554,0.7338]},{"text":"Innovation continues, but so does desperation. Experimental engines push Rigs beyond safe \nlimits, leading to catastrophic failures. Cities cling to dwindling resources, while the wastelands \ngrow ever larger.","box":[0.11905,0.7509,0.88552,0.79937]},{"text":"The future remains uncertain: will the corporations bleed themselves dry, leaving only ruins? Or \nwill a new order rise from the smoke to claim dominion over the Smoglands?","box":[0.11905,0.81647,0.88552,0.84783]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":14,"number":11,"label":"11","title":"Ruthless aristocrats wielding power through fear, dominance, and","width":2000,"height":2829,"blocks":[{"text":"Ruthless aristocrats wielding power through fear, dominance, and \nheavily militarised expansion, The Krim Corporation seeks to \nconquer. Their Rigs are efficient war machines, engineered for \ndurability and mass deployment. For The Krim, survival is measured in \norder, obedience, and the strength of the ability to conquer.","box":[0.3154,0.21773,0.88553,0.3004]},{"text":"An industrial giant, Nox Industries expands relentlessly, choking the \nworld with smoke from relentless production. Their Rigs are heavy, \nbrutal, and adaptable, armed with high power weaponry and \nimpenetrable armour. They see themselves as humanity’s saviours \nthrough ever-growing industry.","box":[0.3154,0.36153,0.88552,0.4442]},{"text":"Ocean-born survivors clinging to crumbling oil platforms, desperate to \nreclaim lost influence and resources, Triton Engineering defends the \nlast great oil wells with machines forged from repurposed diving suits. \nTheir society is insular and pragmatic, bound by tradition. Every Rig \nthey field is a piece of industrial heritage turned weapon.","box":[0.3154,0.5056,0.88552,0.58828]},{"text":"Born from visionaries ignored before the Smogfall, Arcus \nTechnologies are isolated technological pioneers safeguarding arc-\ntech, advancing science in a world bent on stealing it. Their enclaves are \npowered by arc-reactors and advanced filtration towers, their Rigs \nprecise instruments of innovation. Where others see ruin, they see \nproof that only knowledge can shape the future.","box":[0.3154,0.64253,0.88552,0.74231]},{"text":"Rebels and deserters building hope from scrap, driven by grit, defiance \nand the passion for freedom, the Freegear Coalition refuse to bow to \ncorporate rule. They fight with salvaged parts, ingenuity, and sheer \ndetermination, fielding mismatched Rigs that strike supply lines and \nfree the oppressed. For many in the Smoglands, Freegear represents \nhope, and a chance to breathe free air again.","box":[0.3154,0.78731,0.88553,0.88709]},{"text":"THE GREAT POWERS","box":[0.11905,0.08233,0.34739,0.10609]},{"text":"Five great forces now dominate the Smoglands, each with their own vision for survival. Some \nseek control through industry, others through innovation, rebellion, or brute force. Their battles \nshape the Smoglands, and you must choose where your loyalties lie.","box":[0.11905,0.1218,0.88552,0.17027]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":15,"number":12,"label":"12","title":"THE RIGS","width":2000,"height":2829,"blocks":[{"text":"THE RIGS","box":[0.11905,0.08233,0.22516,0.10609]},{"text":"Born from the ashes of collapsing industries, the Rigs are the iron beasts that define the age Of \nOil and Iron. Once, they were little more than machines of burden: oil-rig lifters, mining frames, \nand construction engines, pressed into service when the first resource wars erupted. But \nnecessity breeds innovation, and under the hands of the great corporations, these crude giants \nwere reforged into weapons of war.","box":[0.11905,0.1218,0.88553,0.20448]},{"text":"A Rig is a walking war machine, powered by brutal combustion engines and clad in armour \nplate thick enough to shrug off conventional fire. From nimble light frames darting through \nshattered streets, to colossal class Rigs that grind cities beneath their feet, every Rig is a modular \nchassis, built to accept an arsenal of weapons and equipment tailored to its Ironclad’s need.","box":[0.11905,0.22158,0.88553,0.28715]},{"text":"At their heart stands a single Ironclad: the pilot who breathes life into the Rigs. Without one, a \nRig is a cold husk; with one, it becomes a weapon of terrifying precision. Ironclads endure \ncrushing heat, punishing feedback, and the mental strain of commanding a walking war engine. \nMany are revered, others feared, yet all are bound to their Rigs.","box":[0.11905,0.30425,0.88554,0.36982]},{"text":"To the common folk, Rigs are paradox made manifest: protectors and oppressors, saviours and \nexecutioners. Their looming silhouettes dominate skylines and battlefields alike, reminders of \nthe corporations’ stranglehold over every drop of oil and bolt of steel. Old wrecks litter the \nwastelands, memories of forgotten battles. Some scavenged for parts, others worshipped like \nfallen titans. A Rig may outlast its Ironclad, or even generations of them, reborn again and again \nthrough salvage and re-arming.","box":[0.11905,0.38692,0.88553,0.4867]},{"text":"They are not just machines of war, they are the very embodiment of industry’s promise and its \ncurse.","box":[0.11905,0.5038,0.88554,0.53516]},{"text":"Where the Rigs walk, history is written.","box":[0.11905,0.55226,0.4361,0.56652]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":16,"number":13,"label":"13","title":"Illustration","width":2000,"height":2829,"blocks":[{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":17,"number":14,"label":"14","title":"Illustration","width":2000,"height":2829,"blocks":[{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":18,"number":15,"label":"15","title":"Getting Started","width":2000,"height":2829,"blocks":[{"text":"GETTING STARTED","box":[0.11905,0.08141,0.42593,0.11704]},{"text":"Of Oil and Iron is a strategic tabletop skirmish wargame set in the desolate, diesel-fuelled \nSmoglands, where two or more players command powerful war machines. Each player takes \ncontrol of a squadron of Rigs,  piloted by skilled Ironclads, with custom loadouts to suit their \nengagement. These mechanical behemoths are more than just weapons; they are the lifeblood of \nevery squadron, and the stories told on the tabletop revolve around their triumphs and failures.","box":[0.11905,0.13012,0.88554,0.21279]},{"text":"When building a squadron, you may field Rigs from a single corporation to reflect their \nindustrial might and ideology, or mix different designs together. In the Smoglands, borders blur: \nmachines are stolen, salvaged, or re-purposed, and mercenary Rigs march under no banner but \ntheir own. This flexibility allows you to craft forces that match your playstyle and narrative, from \na lone experimental prototype to a ragtag band of mismatched war machines.","box":[0.11905,0.2299,0.88554,0.31257]},{"text":"Official Of Oil and Iron miniatures are available at www.ofoilandiron.com, including Rig \nControl Terminals, designed to keep your games interesting and engaging.","box":[0.11905,0.32967,0.88552,0.36103]},{"text":"Many players enjoy a narrative campaign, where each battle is a chapter in a larger story. Others \nprefer matched play, where carefully balanced squadrons clash in contests of pure tactical skill. \nBoth styles are supported, and both bring the cinematic weight of Rigs to the forefront.","box":[0.11905,0.37813,0.88552,0.4266]},{"text":"Unlike games of massed armies, Of Oil and Iron focuses on small-scale skirmishes, usually 3–8 \nRigs per side.","box":[0.11905,0.4437,0.88552,0.47506]},{"text":"Rigs painted at 15mm scale","box":[0.37986,0.80443,0.59302,0.81868]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":19,"number":16,"label":"16","title":"Scale","width":2000,"height":2829,"blocks":[{"text":"Scale","box":[0.11905,0.46241,0.16229,0.47667]},{"text":"Of Oil and Iron is designed for 15mm scale, \nmaking it accessible; models are smaller, \nmeaning they are quicker to print and paint! \nThe board size is smaller, meaning it can \nconveniently fit on most tables - and terrain is \nmore easily built and stored.","box":[0.11905,0.49377,0.49102,0.59355]},{"text":"However, if you wish you play at 28mm / \n32mm scale, simply double the distances \nwithin these rules.","box":[0.11905,0.61065,0.49102,0.65911]},{"text":"What you need to play","box":[0.11905,0.67622,0.30694,0.69047]},{"text":"In order to play a game of Of Oil and Iron, you \nwill need a collection of Rigs (usually 3-5 each \nside), a tape measure in inches, a playing \nsurface, terrain, and some six-sided (D6) and \ntwelve-sided (D12) dice. If players choose, \nthey can field as many Rigs as they like in a \ncustom game, if they would prefer a longer \nbattle. Various tokens are provided as 3D \nprintable assets.","box":[0.11905,0.70757,0.49102,0.85866]},{"text":"To command your Rigs, you may print the \nprovided assets:","box":[0.51355,0.46254,0.88551,0.4939]},{"text":"• \nRig Command Terminals","box":[0.51355,0.50221,0.75281,0.51647]},{"text":"• \nWeapon, Equipment and Ironclad cards","box":[0.51355,0.53357,0.86342,0.54782]},{"text":"Alternatively, you may use the Rig Squadron \nRoster, a more printer-friendly way to \ncommand your forces.","box":[0.51355,0.56493,0.88553,0.61339]},{"text":"Distances in Of Oil and Iron are measured in \ninches (“) between the closest points of the \nbases between the models.","box":[0.51355,0.6305,0.88553,0.67896]},{"text":"Game board size","box":[0.51355,0.69606,0.65387,0.71032]},{"text":"Designed to fit on a kitchen table for \naccessible gaming, there are a choice of \neffective game board sizes:","box":[0.51355,0.72742,0.88552,0.77588]},{"text":"• \n22 x 30 inches - preferred!","box":[0.51355,0.7842,0.7494,0.79845]},{"text":"• \n2 x 2 feet","box":[0.51355,0.80677,0.61555,0.82102]},{"text":"• \n3 x 3 feet","box":[0.51355,0.82933,0.61555,0.84359]},{"text":"• \n4 x 4 feet - for bigger games!","box":[0.51355,0.8519,0.7643,0.86616]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":20,"number":17,"label":"17","title":"Key Concepts","width":2000,"height":2829,"blocks":[{"text":"Key Concepts","box":[0.11905,0.08141,0.36693,0.11704]},{"text":"Before entering the Smoglands, all Ironclads \nshould \nunderstand \nthe \nfollowing \ncore \nprinciples. These rules underpin every \nengagement and ensure clarity during play.","box":[0.11905,0.13012,0.49102,0.19569]},{"text":"Activations","box":[0.11905,0.21279,0.21484,0.22705]},{"text":"Models (Rigs) are activated one at a time. \nModels can only be activated once per round. \nPlayers take turns activating one model each, \nuntil all models are activated, at which point a \nround will end and all models are available to \nactivate again.","box":[0.11905,0.24415,0.49102,0.34393]},{"text":"Dice Types","box":[0.11905,0.36103,0.21111,0.37528]},{"text":"Of Oil and Iron uses D6 (six-sided dice), D12 \n(12-sided dice) and D3 (six sided dice, where \na roll of 1-2 results in a 1, a roll of 3-4 results \nin a 2, and a roll of 5-6 results in a 3).","box":[0.11905,0.39239,0.49102,0.45796]},{"text":"Re-rolls","box":[0.11905,0.47506,0.18555,0.48931]},{"text":"A dice can never be re-rolled more than once. \nIf a rule allows a re-roll, the second result \nmust always be accepted, even if it is worse. \nRe-rolls cannot be re-rolled by any means.","box":[0.11905,0.50642,0.49102,0.57198]},{"text":"Natural Rolls","box":[0.11905,0.58909,0.23091,0.60334]},{"text":"Certain dice results apply regardless of \nmodifiers:","box":[0.11905,0.62045,0.49102,0.6518]},{"text":"A natural roll of 1 always misses or fails.","box":[0.11905,0.66891,0.44076,0.68316]},{"text":"A natural roll of 6 normally succeeds, but does \nnot automatically succeed when the required \nresult is 7 or higher. Rolls requiring a 7 or \nhigher are resolved as Improbable Results (see \nbelow).","box":[0.11905,0.70027,0.49103,0.78294]},{"text":"Improbable Results","box":[0.11905,0.80004,0.28332,0.8143]},{"text":"Some attacks or armour rolls may require a \nroll of 7 or higher on a D6. These are \nconsidered Improbable Results.","box":[0.11905,0.8314,0.49102,0.87986]},{"text":"To resolve an Improbable Result:","box":[0.51355,0.08396,0.77652,0.09821]},{"text":"• \nRoll the dice as normal.","box":[0.51355,0.11532,0.73352,0.12957]},{"text":"• \nDiscard all dice that did not result in a 6.","box":[0.51355,0.14668,0.87007,0.16093]},{"text":"• \nRe-roll each remaining dice.","box":[0.51355,0.17804,0.77085,0.19229]},{"text":"• \nIf any of these dice score a 4 or higher \n(4+), the test is successful.","box":[0.51355,0.20939,0.88551,0.24075]},{"text":"Measuring","box":[0.51355,0.25786,0.60352,0.27211]},{"text":"All distances are measured in inches (“”).","box":[0.51355,0.28921,0.84433,0.30347]},{"text":"Distances can be measured at any time.","box":[0.51355,0.32057,0.82877,0.33483]},{"text":"Distances are measured from the closest point \nof one model’s base to the closest point of the \ntarget’s base. Measurements must be taken in \na straight line unless a rule states otherwise.","box":[0.51355,0.35193,0.88553,0.4175]},{"text":"Line of Sight (LOS)","box":[0.51355,0.4346,0.67607,0.44885]},{"text":"A target must be visible to be attacked.","box":[0.51355,0.46596,0.82302,0.48021]},{"text":"Each model occupies a volume of space from \nthe bottom of its base determined by its base \nsize. \nA \nmodel’s \nvolume \nis \nused \nfor \ndetermining if terrain blocks LOS to a model.","box":[0.51355,0.49732,0.88552,0.56288]},{"text":"A model on a 40mm base has a volume \nextending up from the base of 40mm. A \n50mm base has a volume extending up to \n50mm, and so on.","box":[0.51355,0.57999,0.88553,0.64555]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":21,"number":18,"label":"18","title":"Steps to determine line of sight (LOS):","width":2000,"height":2829,"blocks":[{"text":"Steps to determine line of sight (LOS):","box":[0.11905,0.08383,0.43961,0.09809]},{"text":"A target must be visible to be attacked. To \ndetermine line of sight and cover, work \nthrough the following steps in order and stop \nat the first that applies:","box":[0.11905,0.11519,0.49023,0.18076]},{"text":"1. Can an unobstructed line be drawn to every \npart of the target's base and volume?","box":[0.11905,0.19786,0.49024,0.22922]},{"text":"Yes → Full line of sight, no cover.","box":[0.11905,0.24632,0.37966,0.26058]},{"text":"2. If not, can an unobstructed line be drawn to \nthe centre of the target's base?","box":[0.11905,0.27768,0.49024,0.30904]},{"text":"Yes → Light Cover.","box":[0.11905,0.32614,0.26689,0.3404]},{"text":"3. If not, can an unobstructed line be drawn to \nany other part of the target's base?","box":[0.11905,0.3575,0.49024,0.38886]},{"text":"Yes → Heavy Cover.","box":[0.11905,0.40597,0.27536,0.42022]},{"text":"4. If not, the target is not in line of sight and \ncannot be attacked.","box":[0.11905,0.43732,0.49023,0.46868]},{"text":"A model's volume rises from its base equal to \nits base size (a 40mm base has a 40mm \nvolume, a 50mm base a 50mm volume, and so \non). Use this volume when checking whether \nterrain blocks line of sight.","box":[0.51433,0.08396,0.88552,0.16663]},{"text":"Cover Effects","box":[0.51433,0.18374,0.62553,0.19799]},{"text":"Light Cover applies -1 ACC to attacks against \nthe target.","box":[0.51433,0.21509,0.88552,0.24645]},{"text":"Heavy Cover applies -2 ACC to attacks against \nthe target.","box":[0.51433,0.26356,0.88552,0.29492]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":22,"number":19,"label":"19","title":"If a Rig's base and its vertical volume would","width":2000,"height":2829,"blocks":[{"text":"If a Rig's base and its vertical volume would \ngrant different cover, apply the more \nobscuring result. As an alternative to the \nbase-line method above, players may judge \ncover by how much of the Rig is obscured: if \n50% or less is hidden, the Rig is in Light \nCover; if more than 50% is hidden but the Rig \nis still partly visible, it is in Heavy Cover. Both \nmethods produce the same two cover tiers. As \nterrain collections vary, players may agree a \nsocial contract for which pieces count as Light \nor Heavy cover.","box":[0.11905,0.08396,0.48837,0.28636]},{"text":"Shooting from behind cover: An active Rig \nfiring from behind cover suffers no line-of-\nsight penalty for that cover if it is within 2\" of \nthe cover between itself and its target.","box":[0.11905,0.4289,0.48836,0.49447]},{"text":"Firing Arcs","box":[0.11905,0.51157,0.21288,0.52582]},{"text":"Each Rig has three arcs: Front, Side and Rear.","box":[0.11905,0.54293,0.48164,0.55718]},{"text":"A target is within an arc if any part of its base \nlies within that arc when viewed from the \nattacking Rig. Firing arcs determine line of \nsight, weapon eligibility, and potential \nbonuses.","box":[0.11905,0.57429,0.48836,0.65696]},{"text":"If a target lies exactly on the boundary \nbetween arcs, the attacking player chooses \nwhich arc applies.","box":[0.11905,0.67406,0.48836,0.72252]},{"text":"A rig can only shoot from its front firing arc, \nwith \nsome \nexceptions \nincluding \nfrom \nequipment or weapon perks.","box":[0.11905,0.73963,0.4884,0.78809]},{"text":"Attacks made into a target’s side or rear arc \nwill have damage bonuses as described in the \nattacking section.","box":[0.11905,0.8052,0.48836,0.85366]},{"text":"Firing arcs are usually painted onto the base \nof the model.","box":[0.11905,0.87076,0.48836,0.90212]},{"text":"Rough Terrain","box":[0.51621,0.4289,0.63924,0.44315]},{"text":"Battlefields and terrain come in all shapes and \nsizes! Rigs can walk over terrain that is 25% of \ntheir height. Otherwise, they cannot pass over \nthat terrain and must move around it.","box":[0.51621,0.46026,0.88553,0.52582]},{"text":"Rounding Numbers","box":[0.51621,0.54293,0.68288,0.55718]},{"text":"Whenever a number is rounded, round up to \nthe nearest whole number.","box":[0.51621,0.57429,0.88553,0.60564]},{"text":"Simultaneous Effects","box":[0.51621,0.62275,0.69231,0.637]},{"text":"If multiple effects occur at the same time, the \nactive player resolves them in the order of \ntheir choosing.","box":[0.51621,0.65411,0.88553,0.70257]},{"text":"Rule Priority","box":[0.51621,0.71967,0.62585,0.73393]},{"text":"If two rules directly conflict, the more specific \nrule takes precedence.","box":[0.51621,0.75103,0.88552,0.78239]},{"text":"For example, a weapon rule that modifies how \ndamage is applied will override a general \ndamage rule. If two rules are equally specific, \nthe active player decides the order in which \nthey are resolved.","box":[0.51621,0.79949,0.88553,0.88217]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":23,"number":20,"label":"20","title":"Rig Control Terminals and other game assets","width":2000,"height":2829,"blocks":[{"text":"Rig Control Terminals and other game assets","box":[0.11905,0.08383,0.49648,0.09809]},{"text":"Of Oil and Iron uses Rig Control Terminals to control each Rig on the tabletop. Rig Control \nTerminals are provided in two formats. Players have the choice of a printer-friendly terminal \nwhere the player fills in all of the attributes for each Rig; or immersive, coloured cards, \nassembling their Rig with weapons, equipment and pilot cards (known as Ironclads).","box":[0.11905,0.11519,0.8655,0.18076]},{"text":"A Rig assembly using Rig Control Terminal. Weapon Cards,","box":[0.25912,0.89071,0.74545,0.90496]},{"text":"Equipment Cards and Ironclad Cards and dice.","box":[0.31103,0.90781,0.68896,0.92207]},{"text":"A Rig assembly using the printer-friendly Rig Control Terminal","box":[0.24473,0.48122,0.75526,0.49547]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":24,"number":21,"label":"21","title":"SET UP","width":2000,"height":2829,"blocks":[{"text":"SET UP","box":[0.11905,0.08289,0.17479,0.09951]},{"text":"Before playing a game of Of Oil and Iron, it \nmay be useful to see how a game is set up.","box":[0.11905,0.11681,0.47224,0.14817]},{"text":"1. This Rulebook! You can print off or \nphotocopy the Quick Reference sheet at the \nback of this book to refer to.","box":[0.11905,0.63302,0.49102,0.68148]},{"text":"2. Rig control terminal, weapon cards, \nequipment cards and engine cards for each \nRig. Alternatively, you can record all Rig \ninformation on printer-friendly Rig Control \nTerminals.","box":[0.11905,0.69858,0.49102,0.78125]},{"text":"These cards are provided in sizes that are able \nto be sleeved. The Rig Control Terminal is \ntarot card sized (70x120mm) and the \nremaining cards are mini-European card \nsized (44x67mm).","box":[0.11905,0.79836,0.49102,0.88103]},{"text":"3. A squadron of Rigs - 3D printable models, \nin 15mm or 32mm scale. For 15mm scale, \nchoose from a selection of Light (40mm base), \nMedium (50mm base), Heavy (60mm base) or \nColossal (80mm base) weight classes.","box":[0.51355,0.63302,0.88553,0.71569]},{"text":"4. A collection of dice: six-sided (D6) and \ntwelve-sided (D12). 12mm D6 are best to \ntrack health of the Rigs on the Rig Control \nTerminals. With the printer-friendly version, \nyou can track Rig health with just paper and \npen, if that’s your preference.","box":[0.51355,0.73279,0.88552,0.83257]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":25,"number":22,"label":"22","title":"5. Tokens: paper or 3D-printable tokens to","width":2000,"height":2829,"blocks":[{"text":"5. Tokens: paper or 3D-printable tokens to \ntrack critical damage and “Prepare” actions. 2 \ncritical damage tokens per Rig and a handful \nof the others are recommended.","box":[0.11905,0.63302,0.49102,0.69858]},{"text":"6. A battlefield and terrain. Of Oil and Iron is \nprovided in 15mm AND 32mm scales for \naccessibility - you can use anything, but \nreadily available game mats are recommended \nfor the best experience! The board pictured is \na 56x76cm (22x30”) board with 15mm scale \nRigs. Feel free to use any board size you wish, \nto scale up your games!","box":[0.11905,0.71569,0.49102,0.84967]},{"text":"You can use 3D-printable dieselpunk terrain \nprovided at www.ofoilandiron.com, or you \ncan use any terrain you see fit - it’s your \nbattlefield!","box":[0.11905,0.86677,0.49102,0.93234]},{"text":"7. A friend (or… enemy!) to play against. Use \nthe squadron formation recommendations on \npage 89 and start building your squadron - or \nbring whatever you wish for a more narrative \nexperience.","box":[0.51355,0.63302,0.89286,0.71569]},{"text":"Play stand-alone matches or start a campaign!","box":[0.51355,0.73279,0.88243,0.74704]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[{"page":89,"end":null,"label":"page 89","box":[0.51355,0.66722,0.57589,0.68148]}]},{"index":26,"number":23,"label":"23","title":"Core Rules","width":2000,"height":2829,"blocks":[{"text":"Core Rules","box":[0.11905,0.08141,0.32389,0.11704]},{"text":"The Rigs","box":[0.11905,0.12888,0.19332,0.14551]},{"text":"During the game, each player will control a \ncollection of models, referred to as Rigs, \ncollectively referred to as their “Squadron”. \nEach Rig is operated through a Rig Control \nTerminal.","box":[0.11905,0.16281,0.49102,0.24548]},{"text":"Class: Every Rig begins with a base model \ndetermined by its weight class. The weight \nclass determines its core attributes and base \nsize.","box":[0.11905,0.26258,0.49102,0.32815]},{"text":"Light:          40mm base \nMedium:    50mm base\nHeavy:        60mm base\nColossal:    80mm base","box":[0.11905,0.34525,0.3044,0.41082]},{"text":"Speed: The maximum distance the Rig can \nmove in inches.","box":[0.11905,0.42793,0.49102,0.45928]},{"text":"Aim: The base accuracy of the Rig when \nmaking attacks, often modified by weapon \ntraits.","box":[0.11905,0.47639,0.49102,0.52485]},{"text":"Iron: The weight limit available to outfit the \nRig before becoming overweight. Weapons \nand equipment have various weight, usually \nthe more powerful, the more Iron required to \nequip.","box":[0.11905,0.54195,0.49102,0.62463]},{"text":"Weapon Slots: Rigs can be equipped with \nranged and melee weapons up to the number \nof slots on their Rig Control Terminal. Light, \nMedium and Heavy Rigs have 2 weapon slots. \nColossal Rigs have 2 standard weapon slots \nplus 1 additional Hull slot, which may only be \nfilled by a weapon with the Hull perk. Every \nRig must equip at least 2 weapons.","box":[0.11905,0.64173,0.49102,0.77571]},{"text":"Structure Points: These points represent the \noverall durability and structural integrity of a \nRig's various components: its Hull, Arms, \nLegs, or the Engine itself. Once a component’s \nStructure \nPoints \nreach \n0, \nit \nsustains \ncatastrophic damage. Any further damage","box":[0.11905,0.79282,0.49102,0.89259]},{"text":"disables the component. This is covered in \ngreater detail in “Catastrophic Damage” on \npage 31.","box":[0.5138,0.08396,0.88553,0.13242]},{"text":"Impact Location: When a Rig is attacked, a \nD12 is rolled to determine where the attack \nlands. The result is compared to each \ncomponent, where impact locations are \nrepresented as ranges in red.","box":[0.5138,0.14953,0.88553,0.2322]},{"text":"Armour: Representing the ability to be able to \nwithstand or deflect incoming fire. This is \nlisted on the bottom of each component [X].","box":[0.5138,0.2493,0.88552,0.29777]},{"text":"Equipment: Equipment are non-weapon \ncomponents that enhance a Rig's capabilities, \nand cost Iron to equip.","box":[0.5138,0.31487,0.88552,0.36333]},{"text":"Engine: The engine status is represented by \nthe heat tracker at the top of the control \nterminal. Each Rig is unique and so are their \nengines, which perform differently, reacting \nto heat generation at different increments \nalong the heat tracker.","box":[0.5138,0.38044,0.88552,0.48021]},{"text":"Exhaust: In the Maintenance Phase, after \nrolling on the Heat Threshold table if \nnecessary, the engine reduces heat by its \nExhaust value.","box":[0.5138,0.49732,0.88553,0.56288]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[{"page":31,"end":null,"label":"page 31","box":[0.5138,0.11817,0.57498,0.13242]}]},{"index":27,"number":24,"label":"24","title":"Rig Control Terminal","width":2000,"height":2829,"blocks":[{"text":"Rig Control Terminal","box":[0.11905,0.08289,0.31121,0.09951]},{"text":"Below is an example of a fully loaded out Rig using the printed Rig Command Terminal, Engine \nCard, Equipment Card and Weapon Cards.","box":[0.11905,0.11681,0.88553,0.14817]},{"text":"1. Rig Control Terminal, with 12mm D6 dice tracking the structure points","box":[0.11905,0.71226,0.72538,0.72651]},{"text":"2. Weapon cards, for the corresponding weight class of the Rig","box":[0.11905,0.74362,0.62999,0.75787]},{"text":"3. Equipment card(s)","box":[0.11905,0.77498,0.29995,0.78923]},{"text":"4. Ironclad card","box":[0.11905,0.80633,0.25679,0.82059]},{"text":"5. Engine tracker integrated into the Rig Control Terminal with Heat Tracker token.","box":[0.11905,0.83769,0.8025,0.85195]},{"text":"1","box":[0.25026,0.23715,0.25856,0.26091]},{"text":"2","box":[0.27248,0.54091,0.28766,0.56467]},{"text":"3","box":[0.92735,0.3805,0.94284,0.40426]},{"text":"4","box":[0.16957,0.48299,0.18368,0.50675]},{"text":"5","box":[0.36158,0.23715,0.37707,0.26091]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":28,"number":25,"label":"25","title":"Weapons and Equipment","width":2000,"height":2829,"blocks":[{"text":"Weapons","box":[0.11905,0.08289,0.19825,0.09951]},{"text":"Rigs have several options of weapons it can \nequip. Each Rig has 2 weapon slots, with the \nexception of the Colossal class which has an \nadditional “hull” weapon slot. Each Rig must \nequip at least 2 weapons. Here's a breakdown \nof what each term in a weapon's profile \nmeans:","box":[0.11905,0.11681,0.49102,0.23369]},{"text":"Rate of Fire (ROF): The number of dice rolled \nwhen attacking with this weapon. Each dice \nrepresents a single shot or strike the weapon \nmakes in a single attack action.","box":[0.11905,0.2508,0.49102,0.31637]},{"text":"Strength (STR): Represents the power of each \nindividual hit.","box":[0.11905,0.33347,0.49102,0.36483]},{"text":"Range (RNG): Defined in inches, this \nindicates the effective ranges of the weapon. A \nweapon may have a range profile X/Y, where X \nis the short range (SR) and Y the long range \n(LR). A weapon may have an accuracy \nmodifier based on the weapon’s effective \nrange. For example, a weapon with a range of \n8/16 and LR +1 has a +1 ACC bonus to \nweapons fired in the long effective range up to \n8”-16”.","box":[0.11905,0.38193,0.49102,0.55013]},{"text":"Accuracy (ACC): A positive ACC modifier \nreduces the to-hit number required (making \nan attack easier); a negative ACC modifier \nincreases it (making an attack harder). For \nexample, a Rig with an AIM of 4+ firing with \n-1 ACC must roll 5 or higher to hit, while the \nsame Rig with +1 ACC hits on a 3 or higher.","box":[0.51408,0.08396,0.88606,0.20084]},{"text":"Perks: Some weapons have special abilities or \ncharacteristics that can affect the outcome of \nan attack, noted on the bottom of the card.","box":[0.51408,0.21795,0.88606,0.26641]},{"text":"Equipment","box":[0.51408,0.28227,0.61021,0.2989]},{"text":"A Rig's efficiency is not determined solely by \nits weapons. Equipment adds a layer of \nversatility, catering to the strategic needs of \ntheir Ironclad.","box":[0.51408,0.3162,0.88606,0.38176]},{"text":"Equipment have an associated Iron cost, and \nsometimes a Heat cost, which generates an \namount of heat when activated as an action.","box":[0.51408,0.39887,0.88606,0.44733]},{"text":"Unique benefits, enhancements, or abilities \nthe equipment provides to the Rig during \noperation are listed on the card.","box":[0.51408,0.46444,0.88606,0.5129]},{"text":"A full list of equipment can be found in the Rig \nOperating Manual section.","box":[0.51408,0.53,0.8861,0.56136]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":29,"number":26,"label":"26","title":"Engine and Heat","width":2000,"height":2829,"blocks":[{"text":"Engine and heat","box":[0.11905,0.08289,0.26387,0.09951]},{"text":"Rigs are powerful machines that require \nmassive engines to operate. Each Rig's unique \nEngine dictates how it can handle and \nrespond to heat.","box":[0.11905,0.11681,0.49102,0.18238]},{"text":"Each engine has a unique Heat Threshold, \nwhich determines how capable the engine is \nwhile running hot. The various actions and \nweapons each have a Heat value, indicating \nhow much heat is generated when activating \nthat action - represented by sliding the Heat \nvalue up the heat track on the Rig Control \nTerminal.","box":[0.11905,0.19949,0.49102,0.33347]},{"text":"Engine heat starts on the first space on the \nHeat Track.","box":[0.11905,0.35057,0.49101,0.38193]},{"text":"Heat Threshold:","box":[0.51355,0.08383,0.64839,0.09809]},{"text":"In the Maintenance Phase, consult the status \nof the Engine. If the Engine Heat location is \non a numbered space (+0 to +8) known as the \nHeat Threshold, roll on the Heat Threshold \ntable below by rolling a D12 and adding the \nnumbered modifier on the location of the heat \ntrack.","box":[0.51355,0.11519,0.88553,0.23207]},{"text":"A Rig may function at maximum heat, but it \ncan be dangerous! For any actions made when \nthe heat tracker is at its maximum, make a \nHeat Threshold roll for each action.","box":[0.51355,0.24918,0.88552,0.31474]},{"text":"Using all 5 actions is rarely optimal. Managing \nheat is more important than action efficiency.","box":[0.51355,0.33185,0.88556,0.3632]},{"text":"Engine Heat Track with Heat Tracker token. The Engine Exhaust value shows","box":[0.19328,0.48986,0.80104,0.50412]},{"text":"how much heat is reduced each turn in the Maintenance Phase.","box":[0.2478,0.50697,0.7419,0.52122]},{"text":"Heat Threshold Table","box":[0.41191,0.91238,0.57779,0.92664]},{"text":"Result\nDescription\nEffect","box":[0.13116,0.54352,0.64562,0.55658]},{"text":"1-5\nNothing Happens\nThe engine performs as intended.","box":[0.14321,0.57,0.61375,0.58312]},{"text":"6-7\nSystem Stall\nSuffer 2 damage to the Hull. The Rig is Stalled.","box":[0.14321,0.60411,0.70709,0.61724]},{"text":"8-9\nHydraulic Blowout\nSuffer 2 damage to the Legs. The Rig is Slowed.","box":[0.14321,0.63823,0.70967,0.65135]},{"text":"10-11\nAmmunition Detonation Suffer 2 damage to the Arms. The Rig is Shocked.","box":[0.13397,0.67198,0.7259,0.68546]},{"text":"12-13\nFuel Line Rupture\nRoll for an impact location. That component becomes Ruptured.","box":[0.13397,0.70645,0.83938,0.71958]},{"text":"14-15\nStructural Buckling\nEach component suffers 1 damage (Hull, Engine, Arms, Legs).","box":[0.13397,0.74057,0.82493,0.75369]},{"text":"16-17\nEmergency Shutdown The Rig powers down automatically. It cools to safe levels, reduce the","box":[0.13397,0.7669,0.87726,0.78781]},{"text":"heat to the start of the Heat Track, but must skip its next activation.","box":[0.36758,0.78258,0.86186,0.79565]},{"text":"18\nChain Reaction\nEach component suffers 1 damage (Hull, Engine, Arms, Legs) \nRoll again!","box":[0.14637,0.80102,0.88346,0.82976]},{"text":"19\nEngine Failure\nThe Engine’s structure points are reduced to 0 and suffers Catastrophic \nDamage. If it is already Catastrophically Damaged, it becomes Disabled.","box":[0.14637,0.83582,0.86335,0.863]},{"text":"20+\nCatastrophic Failure\nThe Rig suffers Catastrophic Damage to all components.\nHeat can no longer be decreased.","box":[0.14103,0.86925,0.77721,0.89799]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":30,"number":27,"label":"27","title":"Playing the Game","width":2000,"height":2829,"blocks":[{"text":"Playing the Game","box":[0.11905,0.41041,0.46057,0.44604]},{"text":"The game is structured into a series of rounds, \neach representing a specific duration of \ncombat and manoeuvring between Rigs on \nthe battlefield. Each round is divided into \nphases.","box":[0.11905,0.45912,0.49102,0.54179]},{"text":"Phases of a Round:","box":[0.11905,0.55889,0.28217,0.57315]},{"text":"Initiative Phase: Determine which player \nactivates first. Roll a D12, the player with the \nhighest roll activates first. In the event of a tie, \nre-roll. Roll for initiative at the start of each \nround.","box":[0.11905,0.59025,0.49102,0.67292]},{"text":"Players have +1 to their initiative roll for each \nLight Rig in their Squadron still on the \nbattlefield.","box":[0.11905,0.69003,0.49101,0.73849]},{"text":"Activation \nPhase: \nPlayers \ntake \nturns \nactivating a single Rig sequentially based on \nthe initiative order for up to 5 actions each. \nEach Rig completes its actions before moving \non to the next activated Rig. If a player does \nnot have any Rigs left to activate, the player \nwith more Rigs continues to activate the rest \nof their Rigs until the end of the round.","box":[0.11905,0.75559,0.49102,0.88958]},{"text":"Maintenance Phase: Handle any end-of-\nround effects, maintenance and engine heat \nmanagement.","box":[0.51355,0.41296,0.88552,0.46142]},{"text":"Round Duration: A round ends once all \nplayers have activated all their Rigs and \nresolved any end-of-round events or effects.","box":[0.51355,0.47852,0.88552,0.52699]},{"text":"Reset and Repeat: Once a round is concluded, \nthe game resets to the Initiative Phase of the \nnext round unless victory conditions are met.","box":[0.51355,0.54409,0.88552,0.59255]},{"text":"An Ironclad must be considerate when \nmanaging the heat generated by their Rig – or \npush it to its limits when the battle demands. \nIt’s not always wise to use up all of the available \nactions a Rig may take!","box":[0.51355,0.61115,0.88428,0.69382]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":31,"number":28,"label":"28","title":"Activation and Action Points","width":2000,"height":2829,"blocks":[{"text":"Activation, Engines and Action Points","box":[0.11905,0.08289,0.46139,0.09951]},{"text":"Actions:","box":[0.11905,0.11681,0.18882,0.13107]},{"text":"Each Rig may take up to 5 actions when \nactivated. Actions may generate heat, denoted \nin square brackets [X], which increases its \nengine heat by moving the heat tracker on the \nRig Control Terminal. When making an \naction, heat is generated first, then the action \nis performed.","box":[0.11905,0.14817,0.49102,0.26505]},{"text":"Move [1] - When a Rig moves, it may move up \nto its Speed value in inches, incorporating \ndifferent types of movement.","box":[0.11905,0.53302,0.49102,0.58148]},{"text":"Forward Movement: A Rig may move  \ndirectly forward up to its full Speed value.","box":[0.11905,0.59859,0.49438,0.62995]},{"text":"Backpedal: \nRigs \ncan \nreverse \ndirectly \nbackward, \nconsuming \n2” \nof \navailable \nmovement for every 1” moved.","box":[0.11905,0.64705,0.49102,0.69551]},{"text":"Side-Stepping: Rigs can move in their front \nor side arc in directions other than straight \nforward without changing their facing, \nconsuming 2” of available movement for each \n1” moved.","box":[0.11905,0.71262,0.49102,0.79529]},{"text":"Pivot: A Rig may pivot up to 90 degrees in a \nsingle move action, at the start or end of its \nmovement.","box":[0.11905,0.81239,0.49102,0.86085]},{"text":"A Scraphound medium Rig takes a move \naction. It has a speed value of 4. In a single \nmove action, it moves forward 4 inches then \npivots up to 90 degrees at the end of its \nmovement. It uses a second move action to \nmove forward another 4 inches.","box":[0.51483,0.35296,0.88556,0.45274]},{"text":"In this example, the Scraphound takes two \nmovement actions. For its first action, it side-\nsteps in its right side arc. It has a  Speed value \nof 4, but it can only move 2 inches, because \nwhen sidestepping, each 1” of movement \nconsumes 2” of available movement.","box":[0.51483,0.72245,0.88556,0.82222]},{"text":"For its’ second action, it moves directly forward \n4 inches, up to its’ full speed value.","box":[0.51483,0.83933,0.88556,0.87069]},{"text":"Rig actions summary","box":[0.2202,0.50393,0.38529,0.51818]},{"text":"Action\nHeat\nMove\n1\nFire Weapon\n1\nMelee Attack\n1\nCalled Shot\n1\nRam\n1\nReload\n1\nRepair\n1\nShut Down\n0\nPrepare\n1\nUse Equipment\nX","box":[0.18141,0.28445,0.41701,0.49557]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":32,"number":29,"label":"29","title":"Fire Weapon [1] – Choose an equipped","width":2000,"height":2829,"blocks":[{"text":"Fire Weapon [1] – Choose an equipped \nranged weapon and make an attack based on \nits profile. Weapons must be re-loaded after \nevery Fire Weapon action if used again in the \nsame activation.  If a Rig chooses “Fire \nWeapon”, for the same weapon during the \nsame activation, it must be Reloaded first. All \nweapons are reloaded at the end of the Rig’s \nactivation.","box":[0.11905,0.08396,0.49102,0.23505]},{"text":"Melee Attack [1] - Choose an equipped melee \nweapon and make an attack based on its \nprofile. Melee weapons do not need to be \nreloaded.","box":[0.11905,0.25215,0.49102,0.31772]},{"text":"Called Shot [1] - Make a Fire Weapon action, \nchoosing the Hit Location instead of rolling \non the Hit Location table, with -2 ACC. The \nEngine cannot be the target of a Called Shot \nwhen firing into the front arc of an enemy Rig. \nThe target Rig must be within line of sight.","box":[0.11905,0.33483,0.49102,0.4346]},{"text":"Ram [1] – A Rig can ram itself into an enemy. \nThis action can only be used after a movement \nof at least 2”, moving within 1” of an enemy \nRig. When a Rig rams another, both Rigs' \nhulls crash together: each Rig's hull suffers a \nsingle hit with a Strength of D6 + a modifier \nbased on the ramming Rig's weight class (see \ntable). For each hit, create a damage pool \nequal to its Strength and make an armour roll \nagainst it as normal. The target Rig is then \npushed directly back a distance based on the \nramming Rig's weight class.","box":[0.11905,0.45171,0.49102,0.65411]},{"text":"Reload [1] – Ranged weapons require \nreloading in-between firing during the same \nactivation. The Reload action reloads all \nweapons. Weapons are automatically reloaded \nat the end of the Rig’s activation without \ngenerating heat.","box":[0.11905,0.79664,0.49102,0.89642]},{"text":"Repair [1] – An Ironclad may attempt minor \nrepairs during the heat of battle. The repair \naction can either remove a Condition from the \nRig OR repair Structure Points to one \ncomponent, but not both. Roll a D3 and repair \nthat many structure points to one component. \nCatastrophically \nDamaged \nor \nDisabled \ncomponents cannot be repaired.","box":[0.51355,0.08396,0.88553,0.21795]},{"text":"Shut Down [0] - When activating a Rig, \nbefore any other actions, you may choose to \nforfeit all actions to set the Engine Heat to 0.","box":[0.51355,0.23505,0.88552,0.28351]},{"text":"Use Equipment [X]: Some Equipment must \nuse an action to be used, and some Equipment \ngenerate Heat when used. Consult the specific \nEquipment specifications.","box":[0.51355,0.30062,0.88552,0.36618]},{"text":"Preparations:","box":[0.51355,0.38329,0.62757,0.39754]},{"text":"Prepare [1] - Preparations represent an \nIronclad’s ability to anticipate enemy actions \nand prepare to respond dynamically during \nthe opponent's turn. By spending an action \nand generating 1 Heat, a Rig can \"Prepare\" a \nspecific reaction to be triggered by an enemy's \nactions (usually when being the target of an \nattack). This state lasts until the Rig's next \nactivation, at which point the token is \nremoved.","box":[0.51355,0.41465,0.88553,0.58284]},{"text":"To activate a Preparation, declare you are \nmaking a Prepare Action, and place the \nrelevant Preparation token face down next to \nthe chosen Rig. When the corresponding \nenemy action triggers the Preparation, reveal \nit to the opponent and activate its effects. No \nadditional heat is generated if the Preparation \nis triggered.","box":[0.51355,0.59994,0.88553,0.73393]},{"text":"Only one Preparation can be made per \nactivation.","box":[0.51355,0.75103,0.88552,0.78239]},{"text":"Weight Class\nHit STR\nPush Back","box":[0.12569,0.67778,0.46895,0.69203]},{"text":"Light\nD6 + 1\n2”\nMedium\nD6 + 2\n2”\nHeavy\nD6 + 3\n3”\nColossal\nD6 + 4\n3”","box":[0.14572,0.69922,0.43409,0.7776]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":33,"number":30,"label":"30","title":"Attacking and Damage","width":2000,"height":2829,"blocks":[{"text":"Prepare Evasive Manoeuvre","box":[0.11905,0.08383,0.35137,0.09809]},{"text":"When targeted by an attack on \nan \nopponent’s \nactivation, \nbefore the attack is made, \nmove up to half of the Rig’s \nSpeed value in any direction. If \nthe Rig is out of range or line of \nsight, the attack fails.","box":[0.11905,0.11519,0.36997,0.23207]},{"text":"Prepare Return Fire","box":[0.11905,0.24918,0.28681,0.26343]},{"text":"When targeted by an attack on \nan opponent’s activation, after \nthe attack is made,  choose 1 \nweapon to make an attack at \nthe enemy Rig.","box":[0.11905,0.28053,0.36997,0.3632]},{"text":"Prepare Brace for Incoming \nFire","box":[0.11905,0.38031,0.36977,0.41167]},{"text":"When targeted by an attack \ninto the front or side arc on an \nopponent’s activation, Armour \nrolls have +2 to the result for \nthat attack.","box":[0.11905,0.42877,0.36997,0.51144]},{"text":"Attacking and Damage","box":[0.11905,0.53767,0.32183,0.5543]},{"text":"1. Declare the Attacker and Target:","box":[0.11905,0.5716,0.41064,0.58586]},{"text":"Begin by announcing which of your Rigs is \nattacking and specify its target, it must be \nwithin the Rig’s front 90 degree arc.","box":[0.11905,0.60296,0.49102,0.65142]},{"text":"2. Check Range:","box":[0.11905,0.66853,0.25389,0.68278]},{"text":"Using a ruler or measuring tape, measure the \ndistance between the bases of the attacking \nRig and the target. Ensure the distance is \nwithin the effective range of the chosen \nweapon. If not, the attack fails.","box":[0.11905,0.69989,0.49102,0.78256]},{"text":"3. Verify Line of Sight:","box":[0.11905,0.79966,0.30703,0.81392]},{"text":"The attacking Rig must have a clear line of \nsight to its target, even if the target is partially \nobscured by cover. Line of Sight is covered in \ndetail on page 18.","box":[0.11905,0.83102,0.49102,0.89659]},{"text":"Light Cover: If a Rig is in light cover, the \nattack has a modifier of -1 ACC.","box":[0.51355,0.08396,0.88552,0.11532]},{"text":"Heavy Cover: If a Rig is in heavy cover, the \nattack has a modifier of -2 ACC.","box":[0.51355,0.13242,0.88553,0.16378]},{"text":"4. Roll to Hit:","box":[0.51355,0.18089,0.62742,0.19514]},{"text":"Roll as many D6 as the Rate of Fire (ROF) \nvalue of the weapon. To see if the hit is \nsuccessful, add or subtract any relevant ACC \nmodifiers and see if the roll is equal to or \nabove the firing Ironclad’s AIM value.","box":[0.51355,0.21224,0.88553,0.29492]},{"text":"If any enemy Rig has a face-down Prepare \ntoken, remain alert, reactions may trigger here!","box":[0.51355,0.31202,0.88556,0.34338]},{"text":"5. Apply Weapon Effects:","box":[0.51355,0.36048,0.72249,0.37474]},{"text":"Some weapons have special effects when they \nhit or under certain conditions. Check the \nweapon's \"Perks” description and apply them \naccordingly. Perks are listed on page 46.","box":[0.51355,0.39184,0.88553,0.45741]},{"text":"Critical Hit: some weapon perks have \nbonuses that trigger on a Critical Hit. A \nCritical Hit is triggered when rolling a 6 to hit.","box":[0.51355,0.47451,0.88552,0.52297]},{"text":"6. Determine Impact Location:","box":[0.51355,0.54008,0.77301,0.55433]},{"text":"The controller of the targeted Rig rolls a D12 \nto determine the impact location:","box":[0.51355,0.57144,0.88553,0.60279]},{"text":"Called Shot: A Rig firing its weapons may try \nto target a specific location on an enemy Rig \nby declaring the attack as a Called Shot. A \nCalled Shot that successfully hits does not \nneed to roll on the Impact Location table. A \nCalled Shot has -2 ACC.","box":[0.51355,0.74533,0.88553,0.84511]},{"text":"The Engine cannot be targeted this way when \nfiring into a Rig’s front arc.","box":[0.51355,0.86221,0.88557,0.89357]},{"text":"Roll\nImpact Location\n1-4\nHull\n5-7\nArms\n8-10\nLegs\n11-12\nEngine","box":[0.55308,0.62249,0.82776,0.72162]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[{"page":18,"end":null,"label":"page 18","box":[0.19402,0.88233,0.2552,0.89659]},{"page":46,"end":null,"label":"page 46","box":[0.76607,0.44315,0.82726,0.45741]}]},{"index":34,"number":31,"label":"31","title":"Catastrophic Damage","width":2000,"height":2829,"blocks":[{"text":"7. Calculate Damage","box":[0.11905,0.08383,0.29211,0.09809]},{"text":"Step 1 - Damage Pool","box":[0.11905,0.11519,0.2981,0.12944]},{"text":"Damage is calculated as the total applied force \nof an attack, used to determine whether it \novercomes a Rig’s armour.","box":[0.11905,0.14655,0.49102,0.19501]},{"text":"After determining the hit location, create a \ndamage pool, which is the total strength of the \nattack.  Add together:","box":[0.11905,0.21212,0.49102,0.26058]},{"text":"+ Total strength from each successful hit","box":[0.11905,0.27768,0.44473,0.29194]},{"text":"+ 2 if attacking the side arc","box":[0.11905,0.30904,0.3349,0.32329]},{"text":"+ 4 if attacking the rear arc","box":[0.11905,0.3404,0.33495,0.35465]},{"text":"+ Perk effects","box":[0.11905,0.37176,0.22714,0.38601]},{"text":"Step 2 - Armour Roll","box":[0.11905,0.40311,0.29406,0.41737]},{"text":"The defending player rolls a number of D6 \nequal to the damage pool.","box":[0.11905,0.43447,0.49102,0.46583]},{"text":"Before making an armour roll, apply any \nmodifiers. Then for each die that rolls equal to \nor above the armour value of the targeted \ncomponent:","box":[0.11905,0.48293,0.49102,0.5485]},{"text":"- Negate 1 damage","box":[0.11905,0.56561,0.26758,0.57986]},{"text":"Step 3 - Apply Damage","box":[0.11905,0.59696,0.31023,0.61122]},{"text":"Consult the Rig’s Control Terminal, and \nreduce the component’s Structure Points by \nthe total amount of damage.","box":[0.11905,0.62832,0.49102,0.67678]},{"text":"Summary:","box":[0.11905,0.69389,0.20319,0.70814]},{"text":"Damage dealt = damage pool – successful \narmour rolls","box":[0.11905,0.72525,0.49107,0.7566]},{"text":"Catastrophic Damage","box":[0.51355,0.08289,0.70757,0.09951]},{"text":"If any component's Structure Points are \nreduced to 0, that component becomes \nCatastrophically \nDamaged. \nAny \nfurther \ndamage Disables it.","box":[0.51355,0.11681,0.88552,0.18238]},{"text":"• \nIn the same attack action that reduces it to \n0, a component cannot be Disabled.","box":[0.51355,0.19949,0.88552,0.23084]},{"text":"• \nIf a Catastrophically Damaged component \ntakes any further damage in a later action, \nit becomes Disabled.","box":[0.51355,0.24795,0.88552,0.29641]},{"text":"Catastrophically \nDamaged \nand \nDisabled \ncomponents cannot be Repaired (except \nbetween battles in a Campaign - see the \nAftermath Phase in the Campaign).","box":[0.51355,0.31351,0.88556,0.37908]},{"text":"If any 2 of a Rig’s components are Disabled, \nthe Rig is Destroyed!","box":[0.51355,0.39619,0.88552,0.42754]},{"text":"Damage Overflow","box":[0.51355,0.44465,0.66581,0.4589]},{"text":"If an attack hits a Rig component with 0 \nStructure Points and that component is \nalready \nDisabled, \nthe \ndefending \nRig’s \ncontroller chooses another location on the Rig \nthat is not disabled to received that damage.","box":[0.51355,0.47601,0.88553,0.55868]},{"text":"When a Rig component’s Structure Points are \nreduced to 0, apply the corresponding \nCatastrophic Damage effects.","box":[0.51355,0.57578,0.88553,0.62424]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":35,"number":32,"label":"32","title":"Hull Catastrophic Damage:","width":2000,"height":2829,"blocks":[{"text":"Hull Catastrophic Damage:","box":[0.11905,0.08383,0.34918,0.09809]},{"text":"• \nDue to internal system malfunctions the \nRig becomes permanently Stalled.","box":[0.11905,0.11519,0.49102,0.14655]},{"text":"• \n[Colossal Rigs]: weapons with the “Hull” \nperk are disabled and cannot be used.","box":[0.11905,0.16365,0.49102,0.19501]},{"text":"• \nWhen additional damage is taken, the \nHull is Disabled. The Rig becomes \npermanently Stalled and Shocked.","box":[0.11905,0.21212,0.49102,0.26058]},{"text":"Legs Catastrophic Damage:","box":[0.11905,0.27768,0.3495,0.29194]},{"text":"• \nThe Rig becomes Slowed.","box":[0.11905,0.30904,0.35025,0.32329]},{"text":"• \nWhen additional damage is taken, the \nLegs are Disabled. The Rig is permanently\nImmobilised. It can still pivot.","box":[0.11905,0.3404,0.49102,0.38886]},{"text":"Arms Catastrophic Damage:","box":[0.11905,0.40597,0.36266,0.42022]},{"text":"• \nRoll a D12 and consult the following table. \nThat weapon can no longer be used to \nmake an attack action.","box":[0.11905,0.43732,0.49102,0.48579]},{"text":"• \nWhen additional damage is taken, the \narms are Disabled. Both weapons can no \nlonger be used to make an attack action.","box":[0.11905,0.50289,0.49102,0.55135]},{"text":"Engine Catastrophic Damage:","box":[0.11905,0.63117,0.37059,0.64543]},{"text":"• \nIf the Engine’s Heat is below the Heat \nThreshold, move it up to the Heat \nThreshold. Heat can no longer be reduced \nunder the Heat Threshold.","box":[0.11905,0.66253,0.49102,0.7281]},{"text":"• \nWhen additional damage is taken, the \nengine is Disabled. Heat cannot be \nreduced or Exhausted.","box":[0.11905,0.7452,0.49102,0.79366]},{"text":"1-6\nLeft Weapon\n7-12\nRight Weapon","box":[0.21308,0.5736,0.43195,0.60923]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":36,"number":33,"label":"33","title":"Rig Destruction","width":2000,"height":2829,"blocks":[{"text":"Rig Destruction","box":[0.11905,0.08289,0.26142,0.09951]},{"text":"Upon destruction, there's a chance the Rig's \nfuel source might erupt. If a Rig’s Engine was \ndestroyed, the Rig automatically explodes. \nOtherwise, roll a D12; on a 6+ the Rig \nexplodes. Effects occur based on the Rig’s \nWeight Class.","box":[0.11905,0.11681,0.49102,0.21659]},{"text":"The destroyed Rig’s controlling player rolls for \ndamage, and any affected Rig’s controller rolls \nfor Impact Location. Players make an Armour \nRoll for each point of damage in the damage \npool as normal. Rig arc facing damage \nbonuses apply.","box":[0.11905,0.23369,0.49102,0.33347]},{"text":"Light Rig: All Rigs within a 3\" radius suffer a \nSTR 2 + D6 hit.","box":[0.51355,0.08396,0.88552,0.11532]},{"text":"Medium Rig: All Rigs within a 4\" radius suffer \na STR 4 + D6 hit.","box":[0.51355,0.13242,0.88552,0.16378]},{"text":"Heavy Rig: All Rigs within a 5” radius suffer  \na STR 6 + D6 hit.","box":[0.51355,0.18089,0.88888,0.21224]},{"text":"Colossal Rig: All Rigs within a 6” radius \nsuffer a STR 8 + D6 hit.","box":[0.51355,0.22935,0.88553,0.26071]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":37,"number":34,"label":"34","title":"Maintenance Phase","width":2000,"height":2829,"blocks":[{"text":"MAINTENANCE Phase","box":[0.11905,0.08289,0.29381,0.09951]},{"text":"After all Rigs have been activated, the \nmaintenance phase starts.","box":[0.11905,0.11681,0.49102,0.14817]},{"text":"1. Each Rig that has their heat tracker on or","box":[0.11905,0.16528,0.49102,0.17953]},{"text":"above the Heat Threshold rolls on the \nHeat Threshold table (page 26). Make \nthese rolls in order of which Rig is \nrunning hottest (has the highest Heat). If \n2 Rigs have the same Heat, the player with \nthe initiative rolls first.","box":[0.14928,0.18238,0.49102,0.28216]},{"text":"2. All Rigs have their Heat decrease by their","box":[0.11905,0.29926,0.49102,0.31351]},{"text":"Engine Exhaust value, unless otherwise \nstated (for example, engine malfunctions).","box":[0.14928,0.31637,0.49102,0.34772]},{"text":"3. Resolve any other effects which trigger in","box":[0.11905,0.36483,0.49102,0.37908]},{"text":"the Maintenance Phase.","box":[0.14928,0.38193,0.3399,0.39619]},{"text":"4. Check objective scoring for certain","box":[0.11905,0.41329,0.49102,0.42754]},{"text":"engagements.","box":[0.14928,0.43039,0.25852,0.44465]},{"text":"If the Heat Threshold rolls a result that can't be \napplied (targets a location that is already \ndisabled or has the status already), re-roll for a \nnew result.","box":[0.11905,0.46175,0.49106,0.52732]},{"text":"Phase Summary","box":[0.51355,0.08289,0.65858,0.09951]},{"text":"Initiative Phase: Players roll for initiative to \ndetermine who activates first.","box":[0.51355,0.11681,0.88552,0.14817]},{"text":"Activation \nPhase: \nPlayers \ntake \nturns \nactivating Rigs until all Rigs are activated.","box":[0.51355,0.16528,0.88552,0.19664]},{"text":"Maintenance Phase: Rigs roll on the Heat \nThreshold table if necessary, then reduce heat \nby their Engine Exhaust value.","box":[0.51355,0.21374,0.88553,0.2622]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[{"page":26,"end":null,"label":"page 26","box":[0.34978,0.19949,0.39161,0.21374]},{"page":26,"end":null,"label":"page 26","box":[0.3988,0.19949,0.41815,0.21374]}]},{"index":38,"number":35,"label":"35","title":"Conditions","width":2000,"height":2829,"blocks":[{"text":"CONDITIONS","box":[0.11905,0.08289,0.21572,0.09951]},{"text":"Rigs operating in the Smoglands are constantly pushed beyond safe limits. System strain can \ninflict conditions that hinder performance and disrupt combat effectiveness.","box":[0.11905,0.11681,0.88553,0.14817]},{"text":"Unless stated otherwise, conditions apply during the Rig’s next activation and then expire once \ntheir activation is over.","box":[0.11905,0.16528,0.88552,0.19664]},{"text":"Stalled","box":[0.11905,0.21598,0.17698,0.23023]},{"text":"The Rig’s engine falters, starving it of power at a critical moment.","box":[0.11905,0.24734,0.6391,0.26159]},{"text":"The Rig has -2 Actions during its next activation.","box":[0.11905,0.27869,0.51137,0.29295]},{"text":"Shocked","box":[0.11905,0.34141,0.18996,0.35566]},{"text":"Electrical surges and system interference disrupt targeting and \nmovement.","box":[0.11905,0.37277,0.62416,0.40413]},{"text":"The Rig has -1 ACC and -1 SPD (to a minimum of 1) during its \nnext activation.","box":[0.11905,0.42123,0.63134,0.45259]},{"text":"Slowed","box":[0.11905,0.50105,0.17914,0.5153]},{"text":"Damaged locomotive components hampers the Rig’s mobility.","box":[0.11905,0.53241,0.61602,0.54666]},{"text":"The Rig has -2 SPD (to a minimum of 1) during its next activation.","box":[0.11905,0.56377,0.65408,0.57802]},{"text":"Immobilised","box":[0.11905,0.62648,0.22706,0.64074]},{"text":"The Rig’s movement systems are locked in place.","box":[0.11905,0.65784,0.50637,0.67209]},{"text":"The Rig cannot Move, but may still Pivot as normal.","box":[0.11905,0.6892,0.53451,0.70345]},{"text":"Ruptured","box":[0.11905,0.75191,0.19958,0.76617]},{"text":"Violent structural breaches, leaking fluids or fired cause damage to \na component over time until Repaired. When a component is \nRuptured, it suffers 2 damage to the Rig’s component during each \nMaintenance Phase.","box":[0.11905,0.78327,0.6577,0.84884]},{"text":"This condition does not expire unless Repaired.","box":[0.11905,0.86594,0.48307,0.8802]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":39,"number":36,"label":"36","title":"Catastrophically Damaged","width":2000,"height":2829,"blocks":[{"text":"Catastrophically Damaged","box":[0.11905,0.08383,0.34369,0.09809]},{"text":"The Rig’s component has suffered critical structural failure, \npushing it to the brink of destruction.","box":[0.11905,0.11519,0.59598,0.14655]},{"text":"Cannot be Repaired or restored","box":[0.11905,0.16365,0.37238,0.17791]},{"text":"May suffer additional effects as defined by the affected component.","box":[0.11905,0.19501,0.65333,0.20926]},{"text":"This condition does not expire.","box":[0.11905,0.22637,0.3569,0.24062]},{"text":"Disabled","box":[0.11905,0.28909,0.19392,0.30334]},{"text":"The component has suffered further damage after becoming \nCatastrophically Damaged.","box":[0.11905,0.32044,0.60471,0.3518]},{"text":"Cannot be Repaired or restored (except between battles in a \nCampaign).","box":[0.11905,0.36891,0.60279,0.40026]},{"text":"Cannot be targeted or affected further unless stated otherwise.","box":[0.11905,0.41737,0.619,0.43162]},{"text":"May suffer additional effects as defined by the affected component.","box":[0.11905,0.44873,0.65333,0.46298]},{"text":"When 2 of a Rig's components are Disabled, the Rig is Destroyed.","box":[0.11905,0.48008,0.64355,0.49434]},{"text":"This condition does not expire.","box":[0.11905,0.51144,0.3569,0.5257]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":40,"number":37,"label":"37","title":"Example Turn","width":2000,"height":2829,"blocks":[{"text":"EXAMPLE TURN","box":[0.11905,0.08289,0.24356,0.09951]},{"text":"In this turn example, a Freegear Coalition “Hijack” light Rig moves to flank the opposing Krim \nCorporation “Stalker” light Rig.","box":[0.11905,0.11681,0.88554,0.14817]},{"text":"Activation starts","box":[0.11905,0.21449,0.2582,0.22875]},{"text":"The Hijack Ironclad knows that if they can get \na hit into the rear of the Stalker, they can hit an \nexposed spot and deal more damage! The \nHijack has to carefully plan its turn consisting \nof 5 actions, ensuring it does not overheat its \nengine.","box":[0.11905,0.24585,0.49102,0.34563]},{"text":"Actions 1 and 2: Move into position","box":[0.11905,0.48722,0.41735,0.50147]},{"text":"The Hijack, being a light Rig, has a SPD value \nof 4”. It moves forward 4” and at the end of its \nmovement, it pivots 90 degrees. For its second \naction, it moves again, forward 2”.","box":[0.11905,0.51858,0.49102,0.58415]},{"text":"The Hijack checks its firing arc, and \ndetermines the Stalker is in line of sight. \nHowever, the building is obscuring the Stalker \npartially - the Stalker is in light cover. The \nHijack will have -1 ACC on its hit rolls.","box":[0.11905,0.68416,0.49102,0.76683]},{"text":"The Hijack’s Ironclad is a Veteran, which has \nan Aim of 4+, so normally has to get a 4 or \nabove to hit. Because of the obstruction, the \nHijack now has to get a 5 or above to hit.","box":[0.11905,0.78393,0.49102,0.8495]},{"text":"Luckily, the Stalker’s side arc is exposed, so if \nthe Hijack hits, it will deal +2 damage!","box":[0.11905,0.86661,0.49102,0.89796]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":41,"number":38,"label":"38","title":"Action 3: Attack roll","width":2000,"height":2829,"blocks":[{"text":"Action 3: Attack roll","box":[0.11905,0.10159,0.28939,0.11584]},{"text":"The Hijack is equipped with a Mech Rifle and \nan Igniter.","box":[0.11905,0.13295,0.49101,0.16431]},{"text":"After declaring that it will fire its Igniter, they \ncheck the range between the bases of the two \nRigs. It’s just under 4”. Checking the Light \nIgniter weapon, there is a +1 ACC bonus for \nfiring at a Rig within 4” (+1 SR).","box":[0.11905,0.18141,0.49102,0.26408]},{"text":"Before firing, the Ironclad checks their Aim of \n4+ and ACC modifiers: -1 for the target being \nin light cover, and +1 for being within 4” of the \ntarget. The Hijack needs 4s to hit.","box":[0.11905,0.28119,0.49102,0.34675]},{"text":"The Igniter has a total ROF of 3, so for the \nattack, 3 D6 are rolled, resulting in a 5 and a 6. \nIt gets 2 hits, and one of them is a crit!","box":[0.11905,0.36386,0.49102,0.41232]},{"text":"Next, the Hijack calculates the damage pool. It \nadds up the STR of each hit. The Igniter has a \nSTR of 1, and with 2 hits, 2 damage are added \nto the damage pool.","box":[0.11905,0.42942,0.49101,0.49499]},{"text":"The Hijack is also firing into the side arc of the \nStalker. For firing into the side arc, the attack \ngains +2 damage, for a total of 4 damage \nadded to the damage pool.","box":[0.11905,0.5121,0.49102,0.57766]},{"text":"Action 3: Impact location roll","box":[0.11905,0.60022,0.3678,0.61447]},{"text":"Since the Stalker was hit, and the Hijack’s \nIronclad chose not to make an “Called Shot” \naction, the Stalker’s Ironclad rolls to \ndetermine the Impact Location of the attack. \nThey roll a D12, resulting in a 4 - the hull was \nhit.","box":[0.11905,0.63158,0.49102,0.73135]},{"text":"Action 3: Armour roll","box":[0.11905,0.74846,0.3032,0.76271]},{"text":"The Stalker’s hull has an armour value of 4+. It \nrolls 4 D6, one D6 for each damage in the \ndamage pool.","box":[0.11905,0.77982,0.49102,0.82828]},{"text":"The Stalker rolls a 2, 3, 5 and a 6 - blocking \ntwo points of damage, while also suffering two \npoint of damage.","box":[0.11905,0.84538,0.49102,0.89385]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":42,"number":39,"label":"39","title":"Action 3: Perk effects and damage","width":2000,"height":2829,"blocks":[{"text":"Action 3: Perk effects and damage","box":[0.11905,0.1235,0.40189,0.13775]},{"text":"Because the Igniter has the “Incendiary” perk, \nand the Hijack rolled a 6, it activated the perk’s \ncritical hit effect. Incendiary weapons increase \nthe target’s engine heat by 1 for each critical \nhit rolled. The Stalker’s engine heat is \nincreased by 1 for this attack!","box":[0.11905,0.15486,0.49102,0.25463]},{"text":"The Hijack’s attack was successful, dealing 2 \ndamage to the Stalker’s hull, and increasing its \nengine heat by 1.","box":[0.11905,0.27174,0.49102,0.3202]},{"text":"Using the card assets for the Rig Control \nTerminal, the dice tracker on the hull is \nreduced from 6 to 4 for the 2 damage dealt. \nThe heat tracker is moved up 1 space.","box":[0.11905,0.3373,0.49102,0.40287]},{"text":"Action 4: Prepare Evasive Manoeuvres","box":[0.11905,0.54406,0.43997,0.55832]},{"text":"Although the Hijack made a successful attack \non the Stalker, the Hijack’s Ironclad decides to \nend its activation - as its engine is getting hot \nand decides to play cautiously, not pushing its \nluck - but not before preparing evasive \nmanoeuvres!","box":[0.11905,0.57542,0.49216,0.6752]},{"text":"As its fourth action, the Hijack Prepares for \nEvasive Manoeuvres, generating 1 heat, by \nsecretly placing the relevant token, face-down, \nnext to the model on the battlefield. Now the \nHijack is ready to take cover if the Stalker \ndecides to turn to face the Hijack and fire on \nits next turn!","box":[0.11905,0.6923,0.49217,0.80918]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":43,"number":40,"label":"40","title":"With its two moves, fire weapon and prepare","width":2000,"height":2829,"blocks":[{"text":"With its two moves, fire weapon and prepare \nactions, the Engine Heat increased by 1 for \neach action.","box":[0.11905,0.12509,0.49216,0.17355]},{"text":"The Hijack already started its activation with \nthe Engine Heat on the third space from a \nprevious turn. During its activation, it moved \nthe tracker up 4 spaces, ending the activation \nin a numbered space, +2. Since the engine heat \nis above the heat threshold, it must roll on the \nHeat Threshold table in the Maintenance \nPhase.","box":[0.11905,0.19066,0.49217,0.32464]},{"text":"Maintenance Phase:","box":[0.11905,0.50081,0.28669,0.51507]},{"text":"The Hijack rolls a D12 - an 8 is rolled. It adds \nthe +2 modifier from the heat track, resulting \nin a 10.","box":[0.11905,0.53217,0.49217,0.58064]},{"text":"Consulting the Heat Threshold table, the \nHijack suffers Ammunition Detonation. It \nsuffers 2 damage to its arms, and suffers from \nthe condition shocked. It takes the shocked\ntoken and places it next to the model. The \nHijack will have -1 ACC and -1 SPD for its \nnext activation.","box":[0.11905,0.59774,0.49217,0.71462]},{"text":"At the end of the maintenance phase, the \nengine is cooled down by its Engine Exhaust \nvalue of 2, reducing Engine Heat by 2.","box":[0.11905,0.73172,0.49217,0.78019]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":44,"number":41,"label":"41","title":"Rig Operating Manual","width":2000,"height":2829,"blocks":[{"text":"FIELD ISSUE DOCUMENT","box":[0.38446,0.51037,0.61554,0.52462]},{"text":"AUTHORISED OPERATIONAL REVISION","box":[0.31974,0.54173,0.68025,0.55598]},{"text":"Compiled from front-line combat reports, foundry archives, maintenance logs, and surviving","box":[0.12637,0.60444,0.8782,0.6187]},{"text":"Ironclad records throughout the Smoglands.","box":[0.32185,0.62155,0.67815,0.6358]},{"text":"Contains recognised Rig chassis profiles, approved weapons systems, operational \nclassifications, and battlefield revisions currently authorised for active deployment.","box":[0.16836,0.68426,0.83164,0.71562]},{"text":"Unauthorised reproduction punishable under corporate wartime statutes.","box":[0.20498,0.76408,0.79502,0.77834]},{"text":"RIG OPERATING MANUAL","box":[0.21504,0.20561,0.78494,0.25312]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":45,"number":42,"label":"42","title":"The information contained within has been compiled from foundry records, field maintenance","width":2000,"height":2829,"blocks":[{"text":"The information contained within has been compiled from foundry records, field maintenance \nreports, Ironclad combat logs, and front-line operational assessments. Due to the conditions of \nmodern warfare, individual machines may differ from factory-issued specifications as a result of \nsalvage repairs, field modifications, component shortages, or unauthorised alterations.","box":[0.11905,0.20835,0.88552,0.27392]},{"text":"Operators are reminded that no Rig remains factory-standard for long.","box":[0.11905,0.29102,0.6872,0.30527]},{"text":"Extended deployments, poor fuel quality, environmental contamination, and sustained combat \nstress place considerable strain upon all locomotive, structural, and engine systems. Frequent \nmaintenance inspections are mandatory wherever operationally possible. Crews are advised to \nmonitor heat accumulation carefully during combat operations, particularly in confined terrain \nor during prolonged engagements.","box":[0.11905,0.32238,0.88553,0.40505]},{"text":"The battlefields of the Smoglands are harsh on both Rig and Ironclad.","box":[0.11905,0.45351,0.67433,0.46777]},{"text":"Mud, ash, corrosive rainfall, industrial debris, and freezing conditions regularly interfere with \ntargeting systems, joint assemblies, and engine performance. In many regions, recovery of \ndisabled Rigs is considered impractical due to artillery activity, terrain collapse, or fuel \nexpenditure. Crews unable to maintain mobility are unlikely to survive prolonged enemy \ncontact.","box":[0.11905,0.48487,0.88553,0.56754]},{"text":"Despite this, the Rig remains the most effective armoured weapons platform yet developed since \nthe collapse of the old nations.","box":[0.11905,0.58465,0.88553,0.616]},{"text":"Whether employed in trench assaults, refinery sieges, convoy interceptions, or urban \nsuppression operations, the presence of a Rig formation continues to define the outcome of \nmodern engagements across the Smoglands.","box":[0.11905,0.63311,0.88552,0.68157]},{"text":"This document remains subject to ongoing revision as new chassis patterns, weapon systems, \nand battlefield adaptations emerge.","box":[0.11905,0.69867,0.88553,0.73003]},{"text":"Operators are advised to ensure they are referencing the latest authorised edition prior to \ndeployment.","box":[0.11905,0.74714,0.88552,0.77849]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":46,"number":43,"label":"43","title":"Modern warfare within the Smoglands relies heavily upon the deployment of mechanised","width":2000,"height":2829,"blocks":[{"text":"Modern warfare within the Smoglands relies heavily upon the deployment of mechanised \ncombat platforms capable of traversing terrain inaccessible to conventional armoured vehicles, \nwith capabilities of protecting its Ironclad from environmental hazards. While individual \ndesigns vary considerably between corporations, foundries, and field workshops, most \nrecognised Rig chassis fall within established operational classifications.","box":[0.11905,0.13038,0.88552,0.21305]},{"text":"These classifications are determined primarily by structural mass, armour distribution, engine \noutput, and intended battlefield role.","box":[0.11905,0.23015,0.88552,0.26151]},{"text":"It should be noted that field modifications, salvage reconstruction, and regional production \nshortages frequently result in deviations from standard specifications. Weight classifications \nshould therefore be treated as operational guidelines rather than exact measurements.","box":[0.11905,0.27861,0.88553,0.32708]},{"text":"LIGHT RIGS","box":[0.11905,0.37469,0.21657,0.3925]},{"text":"Light Rigs are designed for reconnaissance, flanking operations, rapid assaults, and industrial \npatrol duties. Their lighter frames allow for greater mobility across unstable terrain including \ntrench networks, refinery scaffolds, collapsed urban districts and the like.","box":[0.11905,0.40954,0.88553,0.458]},{"text":"While lightly armoured compared to larger chassis, Light Rigs remain dangerous when \ndeployed aggressively or in coordinated formations. Many corporations utilise Light platforms \nfor scouting, convoy interception, or harassment operations against exposed enemy supply \nlines.","box":[0.11905,0.47511,0.88552,0.54067]},{"text":"Light Rigs typically require less fuel, fewer replacement parts, and reduced logistical support \ncompared to heavier platforms.","box":[0.11905,0.55778,0.88553,0.58914]},{"text":"MEDIUM RIGS","box":[0.11905,0.63675,0.24361,0.65456]},{"text":"Medium Rigs represent the most commonly deployed battlefield classification throughout the \nSmoglands. Designed to balance mobility, protection, and firepower, these machines are capable \nof operating across a wide range of combat environments without requiring the extensive \nlogistical support demanded by heavier chassis.","box":[0.11905,0.6716,0.88552,0.73717]},{"text":"Most sustained engagements are fought and decided by Medium Rig formations.","box":[0.11905,0.75427,0.76563,0.76853]},{"text":"Due to their versatility, Medium platforms are frequently modified for specialised duties \nincluding trench assault, urban suppression, escort operations, and defensive line holding.","box":[0.11905,0.78563,0.88553,0.81699]},{"text":"RIG CLASSIFICATIONS","box":[0.11905,0.08233,0.36867,0.10609]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":47,"number":44,"label":"44","title":"HEAVY RIGS","width":2000,"height":2829,"blocks":[{"text":"HEAVY RIGS","box":[0.11905,0.08279,0.22478,0.10061]},{"text":"Heavy Rigs are breakthrough and siege platforms designed to withstand prolonged combat \nunder concentrated enemy fire. Their thick armour plating and oversized weapon systems make \nthem particularly effective during fortified assaults, industrial sieges, and static front-line \nengagements.","box":[0.11905,0.11765,0.88553,0.18321]},{"text":"The deployment of Heavy Rigs places significant strain upon supply chains. Fuel consumption, \nammunition requirements, and mechanical wear increase substantially during sustained \noperations. Recovery of disabled Heavy platforms is often considered impractical under active \nartillery conditions.","box":[0.11905,0.20032,0.88552,0.26588]},{"text":"Despite these limitations, Heavy Rigs remain among the most feared battlefield assets in active \nservice.","box":[0.11905,0.28299,0.88552,0.31435]},{"text":"COLOSSAL RIGS","box":[0.11905,0.36196,0.25017,0.37977]},{"text":"Colossal Rigs are rare, super-heavy war platforms reserved for major offensives, refinery defence \noperations, and corporate siege deployments. These machines represent the largest mechanised \nchassis currently fielded within the Smoglands and require immense industrial infrastructure to \nconstruct, maintain, and transport.","box":[0.11905,0.39681,0.88553,0.46238]},{"text":"Unlike smaller Rig classifications, Colossal platforms are rarely intended for rapid manoeuvre \nwarfare. Most are designed around oversized long-range weapon systems capable of delivering \nbombardments across entire combat sectors. Siege mortars, heavy artillery batteries, and \nextreme-calibre cannons are commonly mounted upon the hulls of these chassis, allowing \nColossals to function as mobile artillery fortresses capable of reshaping front lines from miles \naway.","box":[0.11905,0.47948,0.88553,0.57926]},{"text":"The appearance of a Colossal Rig on the battlefield is often sufficient to alter front-line morale \nand force immediate strategic redeployment by enemy commanders.","box":[0.11905,0.59636,0.88553,0.62772]},{"text":"FIELD IDENTIFICATION","box":[0.11905,0.67533,0.3135,0.69315]},{"text":"Rig crews are advised to identify enemy chassis by silhouette, engine exhaust signature, and \nweapon configuration whenever possible. Dust storms, smoke saturation, industrial fog, and \nartillery ash frequently obscure visual confirmation at long range.","box":[0.11905,0.71018,0.88553,0.75865]},{"text":"Misidentification of hostile Rig classifications remains a leading cause of failed engagements \nduring low-visibility operations across the Smoglands.","box":[0.11905,0.77575,0.88553,0.80711]},{"text":"When identification cannot be confirmed, operators are advised to assume hostile contact is \nheavier than initially reported.","box":[0.11905,0.82421,0.88551,0.85557]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":48,"number":45,"label":"45","title":"Ironclads","width":2000,"height":2829,"blocks":[{"text":"In the Smoglands, a Rig is only as deadly as the \none who commands it.","box":[0.11905,0.12293,0.49105,0.15429]},{"text":"Ironclads are the pilots, veterans, and \nconscripts who bind machine to will. Their \nskill determines how effectively a Rig can \nbring its weapons to bear in the chaos of \nbattle.","box":[0.11905,0.1714,0.49102,0.25407]},{"text":"Choosing an Ironclad","box":[0.11905,0.27117,0.30132,0.28543]},{"text":"Each Rig must be assigned a single Ironclad.","box":[0.11905,0.30253,0.47418,0.31678]},{"text":"An Ironclad provides the Rig’s Aim value, \ndetermining \nthe \nresult \nrequired \nto \nsuccessfully land hits when making attacks. A \nmore skilled Ironclad will land hits more \nreliably, increasing the effectiveness of all \nweapons equipped to the Rig.","box":[0.11905,0.33389,0.49102,0.43366]},{"text":"Ironclads also have an Iron cost, which \ncontributes toward the Rig’s total loadout.","box":[0.11905,0.45077,0.49102,0.48213]},{"text":"Commanders must decide where to place their \ntrust: in the machine, or in the pilot.","box":[0.11905,0.49923,0.49107,0.53059]},{"text":"IRONCLADS","box":[0.11905,0.08196,0.27176,0.11047]},{"text":"Ironclad\nACC\nIRON","box":[0.56116,0.12844,0.84897,0.14032]},{"text":"Rookie\n6+\n0","box":[0.56719,0.148,0.83187,0.15987]},{"text":"Experienced\n5+\n1","box":[0.54907,0.1675,0.83187,0.17938]},{"text":"Veteran\n4+\n3","box":[0.56497,0.187,0.83187,0.19888]},{"text":"Elite\n3+\n5","box":[0.57586,0.20651,0.83187,0.21838]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":49,"number":46,"label":"46","title":"Weapon Perks","width":2000,"height":2829,"blocks":[{"text":"Weapon Perks","box":[0.11905,0.08289,0.2453,0.09951]},{"text":"The various weapons available to Rigs may \nhave perks attached to them, changing how \nthey perform on the battlefield.","box":[0.11905,0.11681,0.47132,0.16528]},{"text":"Armour Piercing X\nIncreases the target Rig’s armour roll target \nnumber by X.","box":[0.11905,0.18238,0.46896,0.23084]},{"text":"Bombardment\nAttacks made with this weapon’s long range \n(LR) do not require line of sight and ignores \ncover. When attacking without line of sight, \nthe attack has -1 ACC. Attacks made this way \ncannot use the “Called Shot” action.","box":[0.11905,0.24795,0.48815,0.34772]},{"text":"Breaching\nFor each Critical Hit, apply 1 damage to the \naffected area with no Armour Roll in \naddition to its normal damage.","box":[0.11905,0.36483,0.47358,0.43039]},{"text":"Cold\nCold weapons do not generate Heat when \nfired.","box":[0.11905,0.4475,0.45896,0.49596]},{"text":"Flanking\nEach successful hit adds 1 additional damage \nto the damage pool when firing into a Rig's \nside or rear arc.","box":[0.11905,0.51307,0.48476,0.57863]},{"text":"Explosive X\nAll units within X” of the target’s base suffer \nHits equal to this attack’s Hits. Secondary \ntargets take half damage (rounded up), plus \nside or rear facing effects.","box":[0.11905,0.59859,0.47597,0.68126]},{"text":"Hot\nAttacks made with “Hot” weapons roll a D12 \nafter the attack is made. On a 6+, increase \nengine heat by 1, on a 11+, increase engine \nheat by 2.","box":[0.11905,0.69836,0.48313,0.78103]},{"text":"Hull\nColossal Rigs each have the option of \nequipping weapons on or within their Hull. \nWeapons with the Hull trait may only be \nequipped once on each Colossal Rig.","box":[0.11905,0.80099,0.47164,0.88366]},{"text":"Impale\nIf an attack from this weapon is a Critical Hit, \napply the Immobilised condition on the \naffected Rig.","box":[0.51355,0.08383,0.88485,0.1494]},{"text":"Incendiary\nFor each critical hit by this weapon, increase \nthe target’s Engine Heat by 1.","box":[0.51355,0.1665,0.87417,0.21497]},{"text":"Melee\nMelee weapons do not need to be reloaded.\nWhen two melee weapons are equipped, each \nweapon has +1 ROF.","box":[0.51355,0.23207,0.8831,0.29764]},{"text":"Penetrating\nHits of 5+ count as Critical Hits.","box":[0.51355,0.31759,0.77335,0.34895]},{"text":"Precision\nCalled Shots made with this weapon do not \nsuffer the -2 ACC penalty.","box":[0.51355,0.36891,0.86707,0.41737]},{"text":"Rupture\nIf an attack from this weapon is a Critical Hit, \napply the Ruptured condition on the target \ncomponent of the target Rig.","box":[0.51355,0.43447,0.88485,0.50004]},{"text":"Shock\nIf an attack from this weapon is a Critical Hit, \napply the Shocked condition on the affected \nRig.","box":[0.51355,0.51999,0.88485,0.58556]},{"text":"Staggering\nIf this attack hits, Roll a D6. On a 1-2, the \ntarget pivots 90° left. On a 3-4, the target is \npushed back 2\". On a 5-6, the target pivots \n90° right.","box":[0.51355,0.60267,0.86074,0.68534]},{"text":"Sustained Fire\nFor each Critical Hit rolled, add 1 additional \ndamage to the damage pool.","box":[0.51355,0.70244,0.87481,0.7509]},{"text":"Volatile\nIf this Rig makes an attack while at or above \nits Heat Threshold, each hit adds +1 damage \nto the damage pool.","box":[0.51355,0.77086,0.87287,0.83643]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":50,"number":47,"label":"47","title":"RIGS OF THE","width":2000,"height":2829,"blocks":[{"text":"RIGS OF THE \nCORPORATIONS","box":[0.11905,0.08141,0.37787,0.15654]},{"text":"Rig platforms operating throughout the \nSmoglands are manufactured according to the \nindustrial \ndoctrines \nand \nbattlefield \nrequirements \nof \ntheir \nrespective \nCorporations. While all recognised chassis \nfulfil similar operational roles, significant \nvariation exists in armour distribution, \nlocomotive design, engine performance, \nweapons \nintegration, \nand \nbattlefield \nphilosophy.","box":[0.11905,0.16962,0.49102,0.33781]},{"text":"Despite ongoing corporate rivalries, much of \nmodern Rig development continues to rely \nupon shared industrial standards established \nduring the early mechanised conflicts of the","box":[0.11905,0.35492,0.49102,0.42048]},{"text":"Smoglands. Numerous weapon systems have \nsince become widely adopted due to their \nreliability, ease of manufacture, and battlefield \neffectiveness. These standardised armaments \ncan now be found mounted across multiple \nrecognised chassis patterns regardless of \ncorporate origin.","box":[0.51355,0.08396,0.88553,0.20084]},{"text":"Contained within this manual are the \ncurrently recognised operational profiles of \nactive Rig platforms, approved weapons \nsystems, auxiliary equipment, and the \nclassifications of Ironclads authorised to \noperate them.","box":[0.51355,0.21795,0.88552,0.31772]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":51,"number":48,"label":"48","title":"Common Weapons","width":2000,"height":2829,"blocks":[{"text":"Common Light Rig Weapons","box":[0.11905,0.08383,0.36365,0.09809]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.18362,0.1102,0.86818,0.12446]},{"text":"Light Melee Weapon\n1\n4\n1\n-\n-\n0","box":[0.14637,0.13582,0.85479,0.14823]},{"text":"Auto Gun\n3\n1\n4 / 8\n-\nCold; Flanking\n1","box":[0.18354,0.16109,0.85496,0.17296]},{"text":"Light Cannon\n1\n5\n6 / 12\n-\nArmour Piercing 1\n2","box":[0.17048,0.18635,0.85496,0.19822]},{"text":"Rivet Gun\n2\n3\n6 / 12\n-\nSustained Fire\n2","box":[0.18215,0.21161,0.85496,0.22349]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.18362,0.28862,0.86818,0.30287]},{"text":"Medium Melee Weapon\n2\n4\n1\n-\n-\n0","box":[0.13644,0.31476,0.85479,0.32664]},{"text":"Machine Gun\n3\n1\n6 / 12\n-\nCold; Flanking\n1","box":[0.17068,0.34003,0.85479,0.3519]},{"text":"Heavy Cannon\n1\n6\n6 / 12\n-\nArmour Piercing 1\n2","box":[0.16657,0.36529,0.85479,0.37717]},{"text":"Rivet Rifle\n3\n3\n6 / 12\n-\nSustained Fire\n3","box":[0.18206,0.39055,0.85479,0.40243]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.18362,0.47049,0.86818,0.48474]},{"text":"Heavy Melee Weapon\n2\n5\n1\n-\n-\n0","box":[0.14402,0.49663,0.85479,0.50851]},{"text":"Heavy Machine Gun\n4\n1\n6 / 12\n-\nCold; Flanking\n1","box":[0.14755,0.52189,0.85479,0.53377]},{"text":"Siege Bombard\n2\n5\n10 / 20\n-1 SR\nBombardment, Explosive 3\n3","box":[0.16637,0.54716,0.85479,0.55904]},{"text":"Precision Cannon\n1\n7\n8 / 16\n+1 LR\nArmour Piercing 2, Precision\n2","box":[0.15663,0.57242,0.85479,0.5843]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.18362,0.65506,0.86818,0.66932]},{"text":"Demolisher Mortar\n1\n8\n8 / 16\n-1 SR\nHull, Bombardment, Explosive 5\n3","box":[0.15161,0.68121,0.85479,0.69308]},{"text":"Artillery Cannon\n2\n6\n12 / 24\n-1 SR\nHull, Armour Piercing 2\n3","box":[0.15884,0.70647,0.85479,0.71835]},{"text":"Siege Missile Battery\n4\n3\n8 / 16\n+1 LR\nHull, Explosive 2\n2","box":[0.14783,0.73173,0.85479,0.74361]},{"text":"Siege Howitzer\n2\n5\n10 / 20\n-1 SR\nExplosive 3, Bombardment\n2","box":[0.16674,0.75699,0.85479,0.76887]},{"text":"Common Medium Rig Weapons","box":[0.11905,0.26225,0.39002,0.2765]},{"text":"Common Heavy Rig Weapons","box":[0.11905,0.44349,0.37077,0.45775]},{"text":"Common Colossal Rig Weapons","box":[0.11905,0.62825,0.38986,0.64251]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":52,"number":49,"label":"49","title":"Krim Corporation","width":2000,"height":2829,"blocks":[{"text":"The Krim Corporation is the embodiment of \norder in the Smoglands, an empire of \ndiscipline, hierarchy, and exploitation. Once a \nvast consortium of rail lines, armouries, and \nindustrial networks, Krim centered it self with \na reputation for precision and control. When \nthe Smogfall plunged the world into chaos, \nThe Krim thrived by tightening its grip. Food, \nair, and fuel were rationed with military \nefficiency, and the corporation transformed \novernight from a logistical powerhouse into a \nmilitarised state.","box":[0.11905,0.34256,0.49102,0.54568]},{"text":"Industry under The Krim is as structured as a \nbattlefield. Factories run like barracks, their \nschedules enforced with military severity, \nevery cog in the machine expected to pull its \nweight. Their strength lies in standardisation: \nweapons and Rigs are built to consistent \npatterns, easy to repair, replace, and redeploy. \nUnlike Nox’s reckless overproduction, The \nKrim wastes nothing. Their philosophy is \nsimple, order outlasts chaos, and efficiency \nwill always triumph over excess.","box":[0.11905,0.56279,0.49102,0.74808]},{"text":"Life inside Krim’s walls reflects this grim logic. \nCitizens are not individuals but labourers and \nsoldiers, expected to serve until their \nusefulness is spent. Foot soldiers form the \nlowest tier of society, treated as expendable \nbodies sent into the wastes where survival is \nunlikely. Above them, administrators and \noverseers maintain the rigid order of the state.","box":[0.11905,0.76519,0.49102,0.89917]},{"text":"At the pinnacle are the Ironclads: Rig pilots \nforged through years of discipline and loyalty. \nMost Ironclads rise from the ranks of \nobedient soldiers, but the largest and most \nprestigious machines are reserved for Krim’s \naristocratic bloodlines. To these elite families, \npiloting a Rig is not just service, it is \ninheritance, proof of their natural right to \ncommand.","box":[0.51355,0.34328,0.88552,0.49437]},{"text":"On the battlefield, Krim fights like the \nmachine it has become. Armies march in \nlockstep, supply lines are maintained with \nrelentless precision, and victory is achieved \nnot through spectacle but through endurance. \nThey wage wars of attrition, confident that \ntheir structure will outlive their enemies’ \nchaos.","box":[0.51355,0.51147,0.88553,0.64546]},{"text":"The Krim’s Rigs embody this philosophy. They \nare standardised and uniform, built for \ndurability and reliability above all else. Their \nweapons are dependable - autocannons, \nartillery, and heavy machine guns designed to \nfire in any conditions and wreak havoc. The \nKrim Corporation’s Rigs advance with cold \ninevitability, each one a cog in the endless \nmarch of the corporate war machine.","box":[0.51355,0.66256,0.88553,0.81365]},{"text":"Relations with other factions are practical but \nstrained. Nox Industries is their most \ndangerous ally, a partner in conquest when \nconvenient, but an inevitable rival when the","box":[0.51355,0.83075,0.88552,0.89632]},{"text":"THE KRIM CORPORATION","box":[0.28904,0.2927,0.71091,0.32833]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":53,"number":50,"label":"50","title":"spoils must be divided, and tensions between","width":2000,"height":2829,"blocks":[{"text":"spoils must be divided, and tensions between \nthem are often high. Arcus Technologies is \noften a prised target, their coveted arc-tech \nfrequently stolen and installed onto Krim Rig \nchassis. Triton Engineering, with its clinging \nto tradition and isolationism, is seen as \nwasting precious resources that could fuel \nKrim’s \nwar \nmachine. \nThe \nFreegear, \nmeanwhile, are despised above all else. Their \nrebellion against order is intolerable, and \nKrim crushes their enclaves with ruthless \nefficiency, turning each campaign into a \nlesson in obedience for the rest of the \nSmoglands.","box":[0.11905,0.08396,0.49102,0.32057]},{"text":"The Smoglands are to be mastered, shaped \ninto order through iron will and endless \ndiscipline. To falter is to fail, and failure has no \nplace in The Krim’s design.","box":[0.11905,0.33768,0.49102,0.40324]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":54,"number":51,"label":"51","title":"STALKER","width":2000,"height":2829,"blocks":[{"text":"STALKER","box":[0.42487,0.08141,0.57511,0.11704]},{"text":"LIGHT RIG","box":[0.45658,0.11502,0.54342,0.13283]},{"text":"Engine Heat Table","box":[0.49269,0.70601,0.63372,0.71907]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73057,0.87213,0.74482]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46497,0.84921,0.47803]},{"text":"Light\n4\n3\n8","box":[0.51852,0.48961,0.83704,0.50387]},{"text":"Structure Points","box":[0.49269,0.53007,0.61861,0.54314]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55472,0.86059,0.56897]},{"text":"8\n7\n7\n7","box":[0.53492,0.57974,0.83704,0.594]},{"text":"Armour","box":[0.49269,0.62003,0.55593,0.6331]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64468,0.86059,0.65893]},{"text":"4+\n5+\n4+\n5+","box":[0.52907,0.66971,0.84289,0.68396]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78001,0.86776,0.79307]},{"text":"Igniter\n3\n1\n4 / 8\n+1 SR\nIncendiary\n2","box":[0.1921,0.80533,0.85519,0.81839]},{"text":"Missile Rack\n3\n2\n6 / 12\n+1 LR\nExplosive 3\n3","box":[0.17028,0.83059,0.85519,0.84366]},{"text":"Shredder Saw\n2\n4\n1\n+1\nMelee, Rupture\n2","box":[0.16656,0.85585,0.85519,0.86892]},{"text":"Originally developed as an inexpensive security \nand patrol platform, the Stalker quickly became \none of the most widely manufactured Krim Rig \nchassis. Its compact quadrupedal frame allowed \nit to navigate narrow industrial streets and \ncrowded worker zones far more effectively than \nlarger platforms, making it a common sight in \noccupied cities and labour sectors throughout \nKrim territory. Cheap to produce and simple to \nmaintain, Stalkers were often deployed in large \nnumbers both for internal security to control \nKrim society and to support front-line \nformations with reconnaissance and rapid \nassault duties. Among civilians living beneath \nKrim authority, the silhouette of a Stalker \nmoving through smoke-filled streets became \nsynonymous with surveillance, intimidation,","box":[0.11905,0.45717,0.46213,0.7211]},{"text":"and the ever-present reach of the Corporation.","box":[0.1235,0.72371,0.45344,0.73678]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":55,"number":52,"label":"52","title":"RAVAGER","width":2000,"height":2829,"blocks":[{"text":"RAVAGER","box":[0.41904,0.08141,0.58094,0.11704]},{"text":"MEDIUM RIG","box":[0.44305,0.11502,0.55694,0.13283]},{"text":"Engine Heat Table","box":[0.49269,0.70601,0.63372,0.71907]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73057,0.87213,0.74482]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46497,0.84921,0.47803]},{"text":"Medium\n4\n3\n9","box":[0.50519,0.48961,0.83704,0.50387]},{"text":"Structure Points","box":[0.49269,0.53007,0.61861,0.54314]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55472,0.86059,0.56897]},{"text":"10\n8\n8\n8","box":[0.53008,0.57974,0.83704,0.594]},{"text":"Armour","box":[0.49269,0.62003,0.55593,0.6331]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64468,0.86059,0.65893]},{"text":"4+\n4+\n4+\n5+","box":[0.52907,0.66971,0.84289,0.68396]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78001,0.86776,0.79307]},{"text":"Flame Thrower\n3\n2\n4 / 8\n+1 SR\nIncendiary 1\n2","box":[0.16075,0.80533,0.85519,0.81839]},{"text":"Rapid Assault Cannon\n3\n2\n6 / 12\n+1 SR\n-\n2","box":[0.13401,0.83059,0.85519,0.84366]},{"text":"Ripper Saw\n2\n6\n1\n+1\nMelee, Rupture\n3","box":[0.17505,0.85585,0.85519,0.86892]},{"text":"The Ravager was introduced to bridge the \nwidening gap between fast reconnaissance \nplatforms and increasingly expensive Heavy Rig \nprograms, designed as a cheap and versatile \nfront-line assault machine capable of sustained \ncombat across a wide range of battlefield \nconditions. Built around a durable industrial \nframe and adaptable weapons systems, the \nchassis quickly became the backbone of many \nKrim armoured divisions due to its balance of \nmobility, firepower, and relative ease of \nproduction. Ravagers are commonly deployed \nin coordinated assault formations where they \nsupport squadron offensives and defensive line \nengagements alike. Among Krim commanders, \nthe Ravager earned a reputation as a \ndependable machine built not for prestige, but","box":[0.11905,0.45717,0.46213,0.7211]},{"text":"for the grinding wars of attrition.","box":[0.17035,0.72371,0.40658,0.73678]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":56,"number":53,"label":"53","title":"DEFILER","width":2000,"height":2829,"blocks":[{"text":"DEFILER","box":[0.42882,0.08141,0.57117,0.11704]},{"text":"HEAVY RIG","box":[0.45247,0.11502,0.54753,0.13283]},{"text":"Engine Heat Table","box":[0.49269,0.70647,0.63372,0.71954]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73103,0.87213,0.74528]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46543,0.84921,0.4785]},{"text":"Heavy\n3\n4\n10","box":[0.51429,0.49008,0.84188,0.50433]},{"text":"Structure Points","box":[0.49269,0.53053,0.61861,0.5436]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55518,0.86059,0.56943]},{"text":"10\n9\n9\n9","box":[0.53008,0.58021,0.83704,0.59446]},{"text":"Armour","box":[0.49269,0.6205,0.55593,0.63356]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64514,0.86059,0.6594]},{"text":"3+\n4+\n3+\n4+","box":[0.52907,0.67017,0.84289,0.68443]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78047,0.86776,0.79354]},{"text":"Twin Assault Cannon\n4\n2\n6 / 12\n+1 SR\nStaggering\n2","box":[0.13697,0.80579,0.85519,0.81886]},{"text":"Arc Caster\n3\n3\n6 / 12\n+1 SR\nIncendiary; Volatile\n2","box":[0.17752,0.83106,0.85519,0.84412]},{"text":"Reaver Saw\n2\n6\n1\n+1\nMelee, Penetrating; Rupture\n3","box":[0.17502,0.85632,0.85519,0.86938]},{"text":"The Defiler was designed to do one thing above \nall \nelse: \nbreak \nenemy \nlines \nthrough \noverwhelming \nforce. \nBuilt \naround \nan \noverpowered industrial engine and a brutal \nweapons platform, early Defilers earned a \nreputation for turning prolonged engagements \ninto massacres of relentless pounding firepower. \nThick frontal armour and oversized weapon \nsystems allowed the chassis to continue \nadvancing through artillery fire that would \ncripple \nlighter \nplatforms. \nDefilers \nwere \nfrequently deployed at the centre of major \noffensives where their role was simple: absorb \npunishment, close the distance, and reduce \nenemy fortifications through sheer sustained \nviolence. Even now, decades after the first \nproduction runs left Krim foundries, the \nthunder of a Defiler advance remains one of the","box":[0.11905,0.46019,0.46213,0.7398]},{"text":"most feared sounds on the battlefields.","box":[0.15238,0.74242,0.42455,0.75548]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":57,"number":54,"label":"54","title":"DOMINATOR","width":2000,"height":2829,"blocks":[{"text":"DOMINATOR","box":[0.39546,0.08141,0.60451,0.11704]},{"text":"COLOSSAL RIG","box":[0.43977,0.11502,0.56022,0.13283]},{"text":"The Dominator is a siege platform built to \ndeliver overwhelming long-range firepower \ncapable of reducing entire defensive sectors to \nrubble before ground forces advanced. Towering \nabove \nconventional \nRig \nformations, \nthe \nDominator functions less as a battlefield \ncombatant and more as a walking artillery \nfortress, mounting immense bombardment \nweapons. Rare, enormously expensive, and \nlogistically \ndemanding \nto \nmaintain, \nDominators are deployed only during major \noffensives or strategic defence operations, where \ntheir presence alone is often enough to force \nenemy formations into retreat long before the","box":[0.11905,0.48539,0.46213,0.70228]},{"text":"first shells land.\nEngine Heat Table","box":[0.23299,0.70489,0.63372,0.71954]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73103,0.87213,0.74528]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46543,0.84921,0.4785]},{"text":"Colossal\n3\n4\n11","box":[0.50571,0.49008,0.84188,0.50433]},{"text":"Structure Points","box":[0.49269,0.53053,0.61861,0.5436]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55518,0.86059,0.56943]},{"text":"11\n10\n10\n9","box":[0.53008,0.58021,0.83704,0.59446]},{"text":"Armour","box":[0.49269,0.6205,0.55593,0.63356]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64514,0.86059,0.6594]},{"text":"2+\n3+\n3+\n4+","box":[0.52907,0.67017,0.84289,0.68443]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78047,0.86776,0.79354]},{"text":"Twin Assault Cannon\n4\n2\n6 / 12\n+1 SR\nStaggering\n2","box":[0.13697,0.80579,0.85519,0.81886]},{"text":"Heavy Arc Caster\n3\n4\n8 / 16\n+1 SR\nHull; Incendiary; Volatile\n2","box":[0.15208,0.83106,0.85519,0.84412]},{"text":"Long Reach Cannon\n2\n6\n12 / 24\n+1 LR\nHull\n2","box":[0.14124,0.85632,0.85519,0.86938]},{"text":"Heavy Rivet Repeater\n3\n4\n8 / 16\n-\nSustained Fire\n3","box":[0.13763,0.88158,0.85519,0.89464]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":58,"number":55,"label":"55","title":"Nox Industries","width":2000,"height":2829,"blocks":[{"text":"Nox Industries is the furnace of the \nSmoglands, \na \ncorporation \nforged \nin \nindustrious expansion. Before the Smogfall, \nNox was already infamous for pushing \nindustry further than anyone else dared, \ndrilling into unstable reserves and building \nfoundries where others saw only ruin. When \nthe skies collapsed, Nox did not waver, it \nseized the moment. Governments fell, \ncompetitors fractured, but Nox survived by \nimposing ruthless order, binding its citizens \ninto the machinery of the state. In the age that \nfollowed, it became one of the most feared and \nunyielding powers of the Smoglands.","box":[0.11905,0.33996,0.49102,0.57729]},{"text":"For Nox, industry is everything. Their cities \nare engines of endless production, where \nfactories roar without pause and the line \nbetween human and machine blurs. Workers \nare not individuals but expendable parts of a \ngreater whole, consumed and replaced as \nneeded. Sacrifice is expected and progress is \nmeasured not in comfort or freedom but in \noutput. To live under Nox is to accept that the \ncorporation \nalways \ncomes \nbefore \nthe \nindividual, for the greater good of industry.","box":[0.11905,0.5944,0.49102,0.77969]},{"text":"Nox is a totalitarian society where loyalty is \nmanufactured as carefully as its Rigs. Citizens \nare indoctrinated from birth to believe \nobedience is survival and service is duty. \nAmbition still exists, but only within the \nboundaries set by the corporation. The weak","box":[0.11905,0.7968,0.49102,0.89657]},{"text":"are culled by labour, and the strong are \nrewarded with responsibility, always under \nthe shadow of control.","box":[0.51355,0.34068,0.88552,0.38914]},{"text":"Ironclads \nare \nselected \nthrough \nstate \nconscription. Promising candidates are taken \nyoung, trained, and subjected to relentless \nindoctrination until they are unflinchingly \nloyal to the corporation. They are stripped of \nindividuality, their will reshaped to embody \nNox’s ideals.  An Ironclad of Nox is not a hero, \nbut a machine with a human heart beating \nonly for the corporation.","box":[0.51355,0.40625,0.88552,0.55734]},{"text":"Their Rigs reflect this doctrine of control. \nThey are hulking war machines, built not just \nfor battle but as symbols of Nox’s supremacy. \nOverbuilt and imposing, they are clad in thick \narmour and armed with brutal, unforgiving \nweaponry. Many draw from their industrial \nheritage; construction equipment reforged \ninto weapons, always standardised to ensure \nease of mass production.","box":[0.51355,0.57444,0.88553,0.72553]},{"text":"Relations with other factions are marked by \nrivalry \nand \nopportunism. \nThe \nKrim \nCorporation is their greatest competitor, \ntogether they are the twin titans of the \nSmoglands. Triton Engineering guards the \nlast great oil reserves, and Nox covets their \nresources above all else. Skirmishes and \nbattles between the two are constant, though \nTriton has at times reluctantly yielded","box":[0.51355,0.74264,0.88552,0.89372]},{"text":"NOX INDUSTRIES","box":[0.3547,0.2927,0.64529,0.32833]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":59,"number":56,"label":"56","title":"resources in exchange for ceasefires or","width":2000,"height":2829,"blocks":[{"text":"resources in exchange for ceasefires or \nprotection from the  Krim Corporation. For \nNox, such bargains are never permanent; their \nhunger for oil is endless. Arcus Technologies \nis a constant irritant, their raiders strike Nox \nfactories and convoys for materials and arc-\ntech, and Nox answers each raid in kind, \ncoveting Arcus's reactors even as it curses \ntheir interference. The Freegear Coalition, \nmeanwhile, is seen as little more than an \nannoyance, scavengers and saboteurs who \ndelay expansion. Nox sweeps them aside \nwhenever they stand in the way, more \nannoyed than concerned.","box":[0.11905,0.08396,0.49102,0.32057]},{"text":"Nox Industries is a furnace that consumes its \npeople and its enemies alike, forging strength \nfrom obedience and industrial expansion. To \nserve Nox is to abandon the self, for the good \nof the corporation.","box":[0.11905,0.33768,0.49102,0.42035]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":60,"number":57,"label":"57","title":"HAZARD","width":2000,"height":2829,"blocks":[{"text":"HAZARD","box":[0.42972,0.08141,0.57027,0.11704]},{"text":"LIGHT RIG","box":[0.45658,0.11502,0.54342,0.13283]},{"text":"Engine Heat Table","box":[0.49269,0.70396,0.63372,0.71702]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.72852,0.87213,0.74277]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46292,0.84921,0.47599]},{"text":"Light\n3\n2\n8","box":[0.51852,0.48757,0.83704,0.50182]},{"text":"Structure Points","box":[0.49269,0.52802,0.61861,0.54109]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55267,0.86059,0.56692]},{"text":"9\n8\n8\n7","box":[0.53492,0.5777,0.83704,0.59195]},{"text":"Armour","box":[0.49269,0.61799,0.55593,0.63105]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64263,0.86059,0.65689]},{"text":"3+\n4+\n5+\n5+","box":[0.52907,0.66766,0.84289,0.68191]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.77796,0.86776,0.79102]},{"text":"Mortar\n2\n4\n6 / 12\n-1 SR\nBombardment; Explosive 3\n3","box":[0.19052,0.80328,0.85519,0.81635]},{"text":"Igniter\n3\n1\n4 / 8\n+1 SR\nIncendiary\n2","box":[0.1921,0.82854,0.85519,0.84161]},{"text":"Hydraulic Claw\n1\n6\n1\n-\nMelee\n2","box":[0.15924,0.8538,0.85519,0.86687]},{"text":"The Hazard was designed to operate within the \nexpanding construction sectors of early Nox \nsettlements, where its reinforced manipulator \nclaws were used to lift structural beams, clear \ndebris, and assist in the rapid assembly of \nfactories and refinery districts. As Nox \nIndustries expanded deeper into contested \nterritory during the Age of Endless War, the \nsturdy frame was quickly adapted for combat \nuse, fitted with additional armour plating and \nmilitary-grade weapon systems while retaining \nmuch of its original industrial architecture. \nCheap to manufacture and highly adaptable, \nHazards became a common sight both on front \nlines and within the growing factory sprawls of \nNox-controlled territory, where they continue to \nserve as symbols of the corporation’s belief that","box":[0.11905,0.45768,0.46213,0.72161]},{"text":"industry and warfare are one and the same.","box":[0.13199,0.72422,0.44495,0.73729]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":61,"number":58,"label":"58","title":"CAUSTIC","width":2000,"height":2829,"blocks":[{"text":"CAUSTIC","box":[0.4286,0.08141,0.57139,0.11704]},{"text":"MEDIUM RIG","box":[0.44305,0.11502,0.55694,0.13283]},{"text":"Engine Heat Table","box":[0.49269,0.70396,0.63372,0.71702]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.72852,0.87213,0.74277]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46292,0.84921,0.47599]},{"text":"Medium\n3\n2\n9","box":[0.50519,0.48757,0.83704,0.50182]},{"text":"Structure Points","box":[0.49269,0.52802,0.61861,0.54109]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55267,0.86059,0.56692]},{"text":"11\n9\n9\n8","box":[0.53008,0.5777,0.83704,0.59195]},{"text":"Armour","box":[0.49269,0.61799,0.55593,0.63105]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64263,0.86059,0.65689]},{"text":"3+\n4+\n4+\n5+","box":[0.52907,0.66766,0.84289,0.68191]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.77796,0.86776,0.79102]},{"text":"Breach Cannon\n2\n4\n8 / 16\n-1 SR\nBombardment; Explosive 3\n2","box":[0.15939,0.80328,0.85519,0.81635]},{"text":"Impaler Gun\n2\n5\n10 / 20\n+1 SR\nSustained Fire\n3","box":[0.16932,0.82854,0.85519,0.84161]},{"text":"Impact Ram\n2\n4\n1\n+1\nMelee, Staggering\n2","box":[0.17124,0.8538,0.85519,0.86687]},{"text":"The Caustic traces its origins to heavily \narmoured demolition platforms once used to \ntear apart collapsed structures and breach \nunstable refinery sectors contaminated by \nchemical runoff and structural decay. Its \nreinforced frontal plating and immense impact \nrams \nproved \nequally \neffective \nagainst \nfortifications and enemy war machines, leading \nNox Industries to rapidly militarise the chassis \nfor front-line assault operations. Over time, the \nCaustic evolved into one of Nox’s most \ndependable \ncombat \nplatforms: \ndurable, \naggressive, and capable of operating effectively \nacross a wide range of battlefield conditions. \nThe Caustic remains a brutal expression of Nox \ndoctrine: \nrelentless \nadvance \nthrough \noverwhelming industrial force.","box":[0.11905,0.471,0.46212,0.73493]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":62,"number":59,"label":"59","title":"Sledge","width":2000,"height":2829,"blocks":[{"text":"Sledge","box":[0.43575,0.08141,0.56426,0.11704]},{"text":"HEAVY RIG","box":[0.45247,0.11502,0.54753,0.13283]},{"text":"Engine Heat Table","box":[0.49269,0.70421,0.63372,0.71728]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.72877,0.87213,0.74302]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46317,0.84921,0.47624]},{"text":"Heavy\n2\n3\n10","box":[0.51429,0.48782,0.84188,0.50207]},{"text":"Structure Points","box":[0.49269,0.52827,0.61861,0.54134]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55292,0.86059,0.56717]},{"text":"12\n10\n10\n9","box":[0.53008,0.57795,0.83704,0.5922]},{"text":"Armour","box":[0.49269,0.61824,0.55593,0.6313]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64288,0.86059,0.65714]},{"text":"3+\n3+\n4+\n4+","box":[0.52907,0.66791,0.84289,0.68216]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.77821,0.86776,0.79128]},{"text":"Quad Cannon\n4\n3\n6 / 12\n-\nSustained Fire\n3","box":[0.16409,0.80353,0.85519,0.8166]},{"text":"Demolisher Cannon\n2\n7\n10 / 20\n-1 SR\nExplosive 3\n2","box":[0.14154,0.82879,0.85519,0.84186]},{"text":"Power Claw\n2\n6\n1\n+1\nMelee, Breaching\n2","box":[0.17296,0.85405,0.85519,0.86712]},{"text":"Originally engineered for major industrial \nconstruction projects during the expansion of \nNox’s sprawling factory cities, the Sledge was \nbuilt \nto \ntransport \nenormous \nstructural \ncomponents and operate under punishing \nworkloads for extended periods without \nshutdown. Its massive frame and exceptional \nload-bearing capacity later made it an ideal \nplatform for oversized military weapon systems \nas warfare escalated across the Smoglands. \nModern Sledges now field devastating long-\nrange armaments protected by layers of thick \nalloy armour, allowing them to function as \nheavily fortified fire support platforms. Slow, \nimposing, and difficult to disable, the Sledge \nreflects Nox Industries’ preference for machines","box":[0.11905,0.45793,0.46213,0.70618]},{"text":"built not for elegance, but for endurance.","box":[0.14349,0.7088,0.43344,0.72186]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":63,"number":60,"label":"60","title":"MORDENT","width":2000,"height":2829,"blocks":[{"text":"MORDENT","box":[0.41642,0.08141,0.58358,0.11704]},{"text":"COLOSSAL RIG","box":[0.43977,0.11502,0.56022,0.13283]},{"text":"The Mordent was originally developed as a \nheavy \nindustrial \nlifting \nplatform \nused \nthroughout Nox construction zones, where large \ndorsal crane assemblies allowed it to transport \nmachinery \nand \nprefabricated \nstructural \ncomponents across unstable terrain. As the wars \nintensified and demand for mobile artillery \nincreased, the Mordent was gradually refined \nwith \nlong-range \nbombardment \nweapons \nmounted upon the chassis’ reinforced dorsal \nframe. Its stable quadrupedal design proved \nexceptionally effective at absorbing recoil during \nsustained artillery operations, allowing the \nMordent to deliver accurate long-range fire. \nToday, these Rigs are commonly deployed \nbehind advancing Nox formations, where the \ndistant thunder of their guns often signals the","box":[0.11905,0.45793,0.46213,0.72186]},{"text":"beginning of a major offensive.","box":[0.17904,0.72447,0.3979,0.73754]},{"text":"Engine Heat Table","box":[0.49269,0.70421,0.63372,0.71728]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.72877,0.87213,0.74302]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46317,0.84921,0.47624]},{"text":"Colossal\n2\n3\n11","box":[0.50571,0.48782,0.84188,0.50207]},{"text":"Structure Points","box":[0.49269,0.52827,0.61861,0.54134]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55292,0.86059,0.56717]},{"text":"14\n12\n12\n10","box":[0.53008,0.57795,0.84188,0.5922]},{"text":"Armour","box":[0.49269,0.61824,0.55593,0.6313]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64288,0.86059,0.65714]},{"text":"2+\n3+\n2+\n4+","box":[0.52907,0.66791,0.84289,0.68216]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.77821,0.86776,0.79128]},{"text":"Quad Cannon\n4\n3\n6 / 12 \n-\nSustained Fire\n2","box":[0.16409,0.80353,0.85519,0.8166]},{"text":"Bombard Cannon\n2\n4\n12 / 24\n-1 SR\nExplosive 5\n2","box":[0.15029,0.82879,0.85519,0.84186]},{"text":"Heavy Rocket Battery\n3\n4\n8 / 16\n+1 LR\nHull; Explosive 3\n3","box":[0.13696,0.85405,0.85519,0.86712]},{"text":"Incendiary Rocket Battery\n3\n3\n8 / 16\n-\nIncendiary 2\n2","box":[0.12894,0.87932,0.85519,0.89238]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":64,"number":61,"label":"61","title":"Triton Engineering","width":2000,"height":2829,"blocks":[{"text":"Triton Engineering was once the lifeblood of \nthe old world, controlling vast oil platforms \nand maritime industries that fed the furnaces \nof expansion. When the Smogfall came, their \noffshore strongholds became sanctuaries. \nWhile cities on land suffocated in black skies, \nTriton’s ocean platforms endured, fortified \nand guarded by the sea itself. From these \nbastions, they survived, clinging to their oil \nreserves and adapting their industrial diving \nsuits into the first generations of maritime \nRigs. In the centuries since, Triton has become \nan insular but formidable power, guarding \nwhat little remains of the Smogland’s fuel.","box":[0.11905,0.33987,0.49102,0.57721]},{"text":"Industry within Triton is resource-driven and \npragmatic. Oil is everything, the last great \nreserves that power the engines of war and \nsurvival. \nTheir \nplatforms \nare \nfloating \nfortresses, equipped with refineries, salvage \nyards, and recycling plants that ensure their \nlongevity. Triton is less expansive than Nox or \nKrim, but its control of oil grants it a unique \nleverage: every corporation needs what Triton \npossesses. Their strength is measured not in \nscale of production, but in the scarcity of what \nthey guard.","box":[0.11905,0.59431,0.49102,0.79671]},{"text":"Life under Triton is defined by tradition and \nloyalty. Communities are bound by heritage, \nwith families tracing their lineage back to the \noil divers, engineers, and platform workers \nwho first weathered the Smogfall. The sea has","box":[0.11905,0.81382,0.49102,0.89649]},{"text":"shaped their culture into one of pragmatism \nand resilience, where survival depends on \ntrust and duty to the platform. Stability is \nearned through service, and betrayal is met \nwith exile, a death sentence on the open \nwaters.","box":[0.51355,0.3406,0.88552,0.44037]},{"text":"Ironclads in Triton culture are chosen through \nrites of passage tied to the sea. Candidates \ndescend into the depths in modified suits, \ntasked with recovering relics, salvage, or \nresources from dangerous wrecks. Those who \nreturn alive and successful are deemed worthy \nof piloting a Rig. Many of Triton’s most \ncelebrated Ironclads come from families who \nhave served the corporation for generations, \ntheir service both an honour and a \nresponsibility passed down like an heirloom. \nTo pilot a Rig in Triton is to embody both \nheritage and sacrifice, a protector of the \nplatforms and their way of life.","box":[0.51355,0.45748,0.88552,0.69409]},{"text":"Triton fights not for conquest, but for \npreservation. Their doctrine is defensive, built \naround guarding their oil platforms and \nholding the seas against intruders. When \nforced to war, they strike with surgical \nprecision, deploying naval forces and Rigs \nadapted for both land and maritime combat. \nTheir machines are rugged and utilitarian, \nbearing the marks of their industrial roots. \nThey lack the experimental flair of Arcus or \nthe scale of Nox, but they endure, sturdy,","box":[0.51355,0.71119,0.88553,0.89649]},{"text":"TRITON ENGINEERING","box":[0.31557,0.2927,0.68443,0.32833]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":65,"number":62,"label":"62","title":"practical, and built to outlast.","width":2000,"height":2829,"blocks":[{"text":"practical, and built to outlast.","box":[0.11905,0.08396,0.35402,0.09821]},{"text":"Relations are defined by their monopoly on \noil. Nox covets their reserves, sparking \nconstant skirmishes. The Krim views them as \nwasteful, while Arcus often partners with \nthem in defence of the environment, though \ntension \nlingers \nbetween \ntradition \nand \nprogress. \nWith \nthe \nFreegear, \nTriton \noccasionally finds common cause, but their \nloyalty is always to their platforms first.","box":[0.11905,0.11532,0.49102,0.26641]},{"text":"Triton endures as the last great bastion of the \noil seas -  traditional, and unyielding, clinging \nto the ocean that has kept them alive since the \nworld fell.","box":[0.11905,0.28351,0.49102,0.34908]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":66,"number":63,"label":"63","title":"TRENCH","width":2000,"height":2829,"blocks":[{"text":"TRENCH","box":[0.43529,0.08141,0.56468,0.11704]},{"text":"LIGHT RIG","box":[0.45658,0.11502,0.54342,0.13283]},{"text":"Engine Heat Table","box":[0.49269,0.70613,0.63372,0.7192]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73069,0.87213,0.74494]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46509,0.84921,0.47816]},{"text":"Light\n3\n2\n8","box":[0.51852,0.48974,0.83704,0.50399]},{"text":"Structure Points","box":[0.49269,0.5302,0.61861,0.54326]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55484,0.86059,0.56909]},{"text":"8\n8\n8\n6","box":[0.53492,0.57987,0.83704,0.59412]},{"text":"Armour","box":[0.49269,0.62016,0.55593,0.63322]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.6448,0.86059,0.65906]},{"text":"3+\n4+\n4+\n4+","box":[0.52907,0.66983,0.84289,0.68409]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78013,0.86776,0.7932]},{"text":"Gatling Gun\n4\n1\n6 / 12\n-\nFlanking; Sustained Fire\n3","box":[0.17091,0.80545,0.85519,0.81852]},{"text":"Hook Shot\n1\n6\n6 / 12\n+1 SR\nImpale; Penetrating\n2","box":[0.17729,0.83071,0.85519,0.84378]},{"text":"Pry Anchor\n1\n5\n1\n+1\nMelee, Impale\n2","box":[0.1736,0.85598,0.85519,0.86904]},{"text":"The Trench was originally developed as a deep-\nwater industrial diving suit used throughout \nTriton Engineering’s offshore oil operations, \nallowing pilots to descend into the crushing \ndarkness beneath the platforms to perform \ndelicate \nmaintenance \non \npipelines \nand \nsubmerged infrastructure. Compact, heavily \nsealed, \nand \ncapable \nof \noperating \nboth \nunderwater and across unstable deck surfaces, \nthe Trench quickly became an icon of Triton \nplatform life and is widely regarded as the first \ntrue  Triton Rig ever constructed. Even now, \ngenerations later, many Triton pilots trace their \nheritage back to the operators who first \ndescended beneath the waves inside these \nmachines. Though modern Trench variants are \nnow commonly armed for combat, much of the","box":[0.11905,0.45985,0.46212,0.72378]},{"text":"chassis still reflects its industrial origins.","box":[0.14563,0.7264,0.43131,0.73946]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":67,"number":64,"label":"64","title":"NAUTILUS","width":2000,"height":2829,"blocks":[{"text":"NAUTILUS","box":[0.41472,0.08141,0.58528,0.11704]},{"text":"MEDIUM RIG","box":[0.44305,0.11502,0.55694,0.13283]},{"text":"Developed following the success of the Trench \nplatform, the Nautilus was designed to handle \nthe increasingly demanding construction and \nsalvage operations required to expand Triton \nEngineering’s \noffshore \ninfrastructure. \nIts \nenlarged \nframe \nand \nimmense \nvice-like \nmanipulator claws allowed it to lift heavy \nmachinery, aiding both submerged worksites \nand storm-battered platform decks. As conflict \nspread across the Smoglands, the Nautilus’ \ndurable frame and powerful hydraulic systems \nproved easily adaptable for military service, \ntransforming the once-industrial machine into \na formidable combat platform capable of \ncrushing enemy armour while enduring \npunishing \nbattlefield \nconditions. \nToday, \nNautilus formations remain common among","box":[0.11905,0.45985,0.46213,0.72378]},{"text":"Triton forces, valued for their resilience.","box":[0.14728,0.7264,0.42965,0.73946]},{"text":"Engine Heat Table","box":[0.49269,0.70613,0.63372,0.7192]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73069,0.87213,0.74494]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46509,0.84921,0.47816]},{"text":"Medium\n3\n2\n10","box":[0.50519,0.48974,0.84188,0.50399]},{"text":"Structure Points","box":[0.49269,0.5302,0.61861,0.54326]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55484,0.86059,0.56909]},{"text":"9\n9\n9\n7","box":[0.53492,0.57987,0.83704,0.59412]},{"text":"Armour","box":[0.49269,0.62016,0.55593,0.63322]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.6448,0.86059,0.65906]},{"text":"3+\n3+\n4+\n4+","box":[0.52907,0.66983,0.84289,0.68409]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78013,0.86776,0.7932]},{"text":"Rotary Gun\n4\n2\n6 / 12\n-\nFlanking; Sustained Fire\n2","box":[0.17323,0.80545,0.85519,0.81852]},{"text":"Harpoon Launcher\n1\n7\n6 / 12\n+1 SR\nImpale; Penetrating\n2","box":[0.14607,0.83071,0.85519,0.84378]},{"text":"Vice Grips\n2\n6\n1\n-\nMelee, Flanking; Precision\n3","box":[0.17783,0.85598,0.85519,0.86904]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":68,"number":65,"label":"65","title":"KRAKEN","width":2000,"height":2829,"blocks":[{"text":"KRAKEN","box":[0.43107,0.08141,0.56889,0.11704]},{"text":"HEAVY RIG","box":[0.45247,0.11502,0.54753,0.13283]},{"text":"Engine Heat Table","box":[0.49269,0.70671,0.63372,0.71978]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73127,0.87213,0.74552]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46567,0.84921,0.47874]},{"text":"Heavy\n2\n3\n11","box":[0.51429,0.49032,0.84188,0.50457]},{"text":"Structure Points","box":[0.49269,0.53078,0.61861,0.54384]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55542,0.86059,0.56968]},{"text":"10\n10\n10\n8","box":[0.53008,0.58045,0.83704,0.5947]},{"text":"Armour","box":[0.49269,0.62074,0.55593,0.6338]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64538,0.86059,0.65964]},{"text":"3+\n3+\n3+\n3+","box":[0.52907,0.67041,0.84289,0.68467]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78071,0.86776,0.79378]},{"text":"Rotary Cannon\n5\n2\n6 / 12\n-\nFlanking; Sustained Fire\n3","box":[0.15973,0.80603,0.85519,0.8191]},{"text":"Trident Launcher\n1\n7\n8 / 16\n+1 SR\nImpale; Penetrating\n2","box":[0.1524,0.8313,0.85519,0.84436]},{"text":"Pneumatic Crusher\n2\n5\n1\n+1\nMelee, Breaching\n2","box":[0.14503,0.85656,0.85519,0.86962]},{"text":"The Kraken was originally engineered for \nexploration and recovery operations within the \ndangerous depths beyond Triton’s established \ndrilling \nzones, \nwhere \nunstable \nterrain, \ncollapsing seabeds, and violent underwater \nconditions rendered conventional industrial \nplatforms ineffective. Its stable quadrupedal \nframe allowed it to traverse uneven surfaces \nwith remarkable reliability while carrying \nheavy equipment across the ocean floor for \nextended durations. As warfare intensified and \nthe demand for long-range firepower increased, \nthe Kraken’s broad chassis and exceptional \nstability made it an ideal weapons platform for \noversized artillery and heavy support systems. \nModern Krakens now serve as some of Triton \nEngineering’s most feared long-range combat","box":[0.11905,0.46043,0.46213,0.72436]},{"text":"machines.","box":[0.25266,0.72698,0.32428,0.74004]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":69,"number":66,"label":"66","title":"LEVIATHAN","width":2000,"height":2829,"blocks":[{"text":"LEVIATHAN","box":[0.40244,0.08141,0.59752,0.11704]},{"text":"COLOSSAL RIG","box":[0.43977,0.11502,0.56022,0.13283]},{"text":"When the oil wells beneath the great platforms \nbegan to dwindle and rival Corporations \nturned increasingly hostile toward Triton \nEngineering’s holdings, the platform councils \nrecognised that survival would require more \nthan defensive positions and fortified drilling \nstations. The Leviathan project was conceived \nas a direct answer to the escalating arms race \nconsuming the Smoglands: a colossal war \nmachine capable of protecting Triton territory \nthrough overwhelming force. Due to limited \nmanufacturing resources and the urgency of the \nproject, Leviathans were constructed using \nrecycled Trench cockpit assemblies retrofitted \ninto vast new armoured chassis, a practice that \ngave rise to the belief among Triton crews that \nevery Leviathan carries the spirit of the old","box":[0.11905,0.46043,0.46213,0.72436]},{"text":"platform workers within its hull.","box":[0.17282,0.72698,0.40412,0.74004]},{"text":"Engine Heat Table","box":[0.49269,0.70671,0.63372,0.71978]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73127,0.87213,0.74552]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46567,0.84921,0.47874]},{"text":"Colossal\n2\n3\n12","box":[0.50571,0.49032,0.84188,0.50457]},{"text":"Structure Points","box":[0.49269,0.53078,0.61861,0.54384]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55542,0.86059,0.56968]},{"text":"12\n11\n11\n9","box":[0.53008,0.58045,0.83704,0.5947]},{"text":"Armour","box":[0.49269,0.62074,0.55593,0.6338]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64538,0.86059,0.65964]},{"text":"2+\n3+\n2+\n3+","box":[0.52907,0.67041,0.84289,0.68467]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78071,0.86776,0.79378]},{"text":"Rotary Cannon\n5\n2\n6 / 12\n-\nFlanking; Sustained Fire\n2","box":[0.15973,0.80603,0.85519,0.8191]},{"text":"Precision Cannon\n1\n7\n8 / 16\n+1 LR\nArmour-Piercing 2; Precision\n2","box":[0.15061,0.8313,0.85519,0.84436]},{"text":"Incinerator\n3\n2\n6 / 12\n+1 SR\nIncendiary 2\n2","box":[0.17546,0.85656,0.85519,0.86962]},{"text":"Trident Launcher\n1\n7\n8 / 16\n+1 SR\nImpale; Penetrating\n3","box":[0.1524,0.88182,0.85519,0.89489]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":70,"number":67,"label":"67","title":"Arcus Technologies","width":2000,"height":2829,"blocks":[{"text":"Arcus Technologies rose from obscurity in the \nfinal years before the Smogfall, when a loose \nconsortium of engineers and researchers \nwarned of the atmospheric collapse to come. \nTheir \nwarnings \nwere \ndismissed, \ntheir \ninventions deemed too costly, and their \nresearch buried by rivals who profited from \nunchecked industry. When the skies finally \ndarkened, those who had ignored Arcus paid \nthe price. The collective that once struggled to \nbe \nheard \nbecame \nindispensable, \ntheir \nfiltration towers and experimental arc-\nreactors suddenly the only means of survival. \nOut of necessity, Arcus transformed into a \npower of its own, and in the age Of Oil and \nIron, it has become a force both feared and \nrespected.","box":[0.11905,0.34117,0.49102,0.62982]},{"text":"Arcus is a technocracy, governed not by \naristocracy or brute hierarchy, but by intellect \nand invention. Its citizens live within \ntowering, \nsealed \nenclaves \npowered \nby \nexperimental energy systems, their survival \ntied directly to innovation. Knowledge is the \nhighest currency in Arcus society, and those \nwho \nadvance \nits \ntechnology \nrise \nto \nprominence, while those who fail or stagnate \nare relegated to menial roles. It is a culture of \nprogress, where the pursuit of solutions \noutweighs morality. For Arcus, survival \ndepends on the mastery of the sciences.","box":[0.11905,0.64692,0.49102,0.86643]},{"text":"Ironclads within Arcus are chosen through","box":[0.11905,0.88353,0.49102,0.89779]},{"text":"rigorous testing. Candidates are subjected to \nexaminations \nof \nintellect, \nreflex, \nand \npsychological resilience, often drawn from the \nranks of engineers and scientists who \nunderstand the very systems they are meant to \npilot. The chosen are celebrated not as soldiers \nbut as guardians of knowledge, entrusted to \nwield Rigs as precise instruments of both war \nand progress. An Arcus Ironclad is a pilot and \na scientist in one, embodying the ideal of \nreason fused with survival.","box":[0.51355,0.3419,0.88553,0.52719]},{"text":"Arcus wages war as an extension of its \nphilosophy: measured, precise, and adaptive. \nArcus \nstrikes \nwith \ncalculation, \ntheir \nsquadrons favour targeted raids and surgical \nstrikes, dismantling supply lines and disabling \nkey infrastructure rather than seeking direct \nconfrontation.","box":[0.51355,0.5443,0.88552,0.66118]},{"text":"Their Rigs are specialised, efficient, and often \nexperimental. Many feature arc-reactors and \nadvanced energy systems that allow for \nweapons or capabilities beyond conventional \ndesign. These machines are less numerous but \nhighly adaptable. On the battlefield, they are \nsurgical instruments of war, fewer in number, \nbut devastatingly effective.","box":[0.51355,0.67828,0.88553,0.81227]},{"text":"Relations with other factions are fraught with \ncontradiction. Arcus views Krim as dangerous \nand inflexible. Nox Industries is both \nrespected and despised: Arcus admires the","box":[0.51355,0.82937,0.88552,0.89494]},{"text":"ARCUS TECHNOLOGIES","box":[0.31255,0.2927,0.68745,0.32833]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":71,"number":68,"label":"68","title":"sheer scale of their industry, but abhors the","width":2000,"height":2829,"blocks":[{"text":"sheer scale of their industry, but abhors the \ndevastation it causes. Their rivalry is bitter, \nmarked by constant raids on Nox factories \nand convoys, with Nox retaliating in kind. \nTriton Engineering is Arcus’ most natural ally, \ntheir shared focus on preservation forging \noccasional pacts, however they cannot agree \non the continued use of oil. The Freegear \nCoalition, meanwhile, is treated with wary \nsympathy, Arcus sometimes funnels them \nresources to weaken corporate rivals, but the \nCoalition’s rejection of all corporate power \nmakes true alliance impossible.","box":[0.11905,0.08396,0.49102,0.30347]},{"text":"They were the prophets no one heeded, the \ninnovators who saw the fall coming, and the \ntechnocrats who built their own survival.","box":[0.11905,0.32057,0.49102,0.36903]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":72,"number":69,"label":"69","title":"FLUX","width":2000,"height":2829,"blocks":[{"text":"FLUX\nLIGHT RIG","box":[0.45658,0.08141,0.54342,0.13283]},{"text":"Engine Heat Table","box":[0.49269,0.7057,0.63372,0.71877]},{"text":"-\n-\n-\n-\n-\n-\n+0\n+2\n+4\n+6","box":[0.50692,0.73026,0.87213,0.74451]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46466,0.84921,0.47773]},{"text":"Light\n5\n2\n8","box":[0.51852,0.48931,0.83704,0.50356]},{"text":"Structure Points","box":[0.49269,0.52976,0.61861,0.54283]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55441,0.86059,0.56866]},{"text":"8\n7\n7\n7","box":[0.53492,0.57944,0.83704,0.59369]},{"text":"Armour","box":[0.49269,0.61973,0.55593,0.63279]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64437,0.86059,0.65863]},{"text":"4+\n5+\n5+\n4+","box":[0.52907,0.6694,0.84289,0.68365]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.7797,0.86776,0.79277]},{"text":"Ion Cannon\n2\n2\n8 / 16\n+1 LR\nArmour-Piercing 2\n2","box":[0.17231,0.80502,0.85519,0.81809]},{"text":"Arc Thrower\n3\n1\n6 / 12\n+1 SR\nShock; Sustained Fire\n3","box":[0.16986,0.83028,0.85519,0.84335]},{"text":"Shock Blade\n2\n4\n1\n-\nMelee, Shock\n2","box":[0.17175,0.85555,0.85519,0.86861]},{"text":"The Flux was originally developed by the \nDivision of Voltaic Dynamics as a lightweight \nexperimental platform intended to test compact \nArc engine systems outside the controlled \nenvironments of Arcus arcologies. Built for \nspeed and precision, the chassis proved \nexceptionally effective during reconnaissance \noperations and fast-response defensive actions \nalong Arcus trade routes and fringe territories. \nUnlike the heavier industrial designs fielded by \nother Corporations, the Flux relied upon agility \nand advanced targeting systems rather than \narmour alone, using bursts of volatile arc energy \nto disable enemy systems before retaliation \ncould be coordinated. The Flux became a \nsymbol of Arcus’ belief that superior engineering \nand calculated force could overcome the crude,","box":[0.11905,0.45942,0.46213,0.72335]},{"text":"slow brutality dominating the Smoglands.","box":[0.13934,0.72596,0.4376,0.73903]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":73,"number":70,"label":"70","title":"DYNAMO","width":2000,"height":2829,"blocks":[{"text":"DYNAMO","box":[0.42439,0.08141,0.57559,0.11704]},{"text":"MEDIUM RIG","box":[0.44305,0.11502,0.55694,0.13283]},{"text":"The Dynamo was introduced as Arcus \nTechnologies’ primary front-line combat Rig, \ndesigned to provide a balanced and dependable \nweapons platform capable of supporting the \nsmaller, highly specialised squadrons fielded by \nthe Corporation. Built around an efficient arc-\nreactor system and sophisticated energy \ndistribution \narchitecture, \nthe \nDynamo \ncombined mobility, precision weaponry, and \nadvanced cooling systems within a relatively \ncompact chassis. While lacking the raw \ndurability of heavier industrial platforms, the \nDynamo excelled in coordinated operations \nwhere disciplined formations and superior \nbattlefield control allowed Arcus forces to \ndismantle larger enemies through precision","box":[0.11905,0.45942,0.46212,0.70767]},{"text":"strikes and sustained energy fire.\nEngine Heat Table","box":[0.17206,0.7057,0.63372,0.72335]},{"text":"-\n-\n-\n-\n-\n-\n+0\n+2\n+4\n+6","box":[0.50692,0.73026,0.87213,0.74451]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46466,0.84921,0.47773]},{"text":"Medium\n5\n2\n9","box":[0.50519,0.48931,0.83704,0.50356]},{"text":"Structure Points","box":[0.49269,0.52976,0.61861,0.54283]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55441,0.86059,0.56866]},{"text":"9\n8\n8\n7","box":[0.53492,0.57944,0.83704,0.59369]},{"text":"Armour","box":[0.49269,0.61973,0.55593,0.63279]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64437,0.86059,0.65863]},{"text":"4+\n5+\n5+\n3+","box":[0.52907,0.6694,0.84289,0.68365]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.7797,0.86776,0.79277]},{"text":"Voltaic Repeater\n3\n2\n6 / 12\n+1 SR\nSustained Fire; Shock\n3","box":[0.15651,0.80502,0.85519,0.81809]},{"text":"Rail Gun\n1\n7\n8 / 16\n-\nArmour-Piercing 2\n2","box":[0.18365,0.83028,0.85519,0.84335]},{"text":"Arc Lance\n2\n5\n1\n-\nMelee, Shock\n2","box":[0.1793,0.85555,0.85519,0.86861]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":74,"number":71,"label":"71","title":"GALVANIC","width":2000,"height":2829,"blocks":[{"text":"GALVANIC","box":[0.41409,0.08141,0.5859,0.11704]},{"text":"HEAVY RIG","box":[0.45247,0.11502,0.54753,0.13283]},{"text":"Engine Heat Table","box":[0.49269,0.70626,0.63372,0.71933]},{"text":"-\n-\n-\n-\n-\n-\n+0\n+2\n+4\n+6","box":[0.50692,0.73082,0.87213,0.74508]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46522,0.84921,0.47829]},{"text":"Heavy\n4\n3\n10","box":[0.51429,0.48987,0.84188,0.50412]},{"text":"Structure Points","box":[0.49269,0.53033,0.61861,0.54339]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55497,0.86059,0.56923]},{"text":"10\n9\n9\n8","box":[0.53008,0.58,0.83704,0.59425]},{"text":"Armour","box":[0.49269,0.62029,0.55593,0.63336]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64494,0.86059,0.65919]},{"text":"4+\n4+\n4+\n3+","box":[0.52907,0.66996,0.84289,0.68422]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78026,0.86776,0.79333]},{"text":"Arc Beam Cannon\n3\n2\n8 / 16\n+1 SR\nSustained Fire; Shock\n3","box":[0.14807,0.80558,0.85519,0.81865]},{"text":"Rail Cannon\n1\n8\n10 / 20\n+1 LR\nArmour-Piercing 2\n3","box":[0.17015,0.83085,0.85519,0.84391]},{"text":"Arc Sword\n2\n5\n1\n+1\nMelee, Shock\n2","box":[0.17796,0.85611,0.85519,0.86917]},{"text":"The Galvanic was engineered as a heavy assault \nplatform capable of mounting oversized Arc \nweapon systems previously considered too \nunstable for mobile deployment. Developed \njointly between the Division of Energetic \nPhenomena and the Division of Structural \nMetallurgy, the chassis was constructed around \nextensive cooling assemblies designed to contain \nthe immense electrical loads generated during \ncombat \noperations. \nOn \nthe \nbattlefield, \nGalvanics are feared for their ability to unleash \ndevastating bursts of arc energy capable of \ncrippling enemy systems and punching through \nheavily armoured targets with terrifying","box":[0.11905,0.45998,0.46213,0.67688]},{"text":"efficiency.","box":[0.2536,0.67949,0.32334,0.69256]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":75,"number":72,"label":"72","title":"TEMPEST","width":2000,"height":2829,"blocks":[{"text":"TEMPEST","box":[0.42027,0.08141,0.57973,0.11704]},{"text":"COLOSSAL RIG","box":[0.43977,0.11502,0.56022,0.13283]},{"text":"The Tempest represents the pinnacle of Arcus \nTechnologies’ experimental war engineering: a \ncolossal Arc-powered platform designed to \ndominate \nentire \nbattlefields \nthrough \noverwhelming energy projection. Towering \nabove conventional Rig squadrons, the Tempest \nmounts massive capacitor banks and long-\nrange arc weaponry capable of unleashing \ndevastating electrical bombardments across \nbattlefields. During operation, the machine’s \nreactor systems generate violent atmospheric \ninterference, filling the surrounding air with \nstatic discharge, and arcs of uncontrolled \nelectricity that have given rise to numerous \nbattlefield superstitions among enemy forces. \nRarely deployed outside major conflicts, the \nappearance of a Tempest is feared amongst","box":[0.11905,0.45998,0.46213,0.72391]},{"text":"commanders in every corporation.","box":[0.16546,0.72653,0.41148,0.73959]},{"text":"Engine Heat Table","box":[0.49269,0.70626,0.63372,0.71933]},{"text":"-\n-\n-\n-\n-\n-\n+0\n+2\n+4\n+6","box":[0.50692,0.73082,0.87213,0.74508]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46522,0.84921,0.47829]},{"text":"Colossal\n4\n3\n11","box":[0.50571,0.48987,0.84188,0.50412]},{"text":"Structure Points","box":[0.49269,0.53033,0.61861,0.54339]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55497,0.86059,0.56923]},{"text":"10\n10\n10\n10","box":[0.53008,0.58,0.84188,0.59425]},{"text":"Armour","box":[0.49269,0.62029,0.55593,0.63336]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64494,0.86059,0.65919]},{"text":"3+\n3+\n4+\n3+","box":[0.52907,0.66996,0.84289,0.68422]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78026,0.86776,0.79333]},{"text":"Heavy Machine Gun\n4\n2\n6 / 12\n-\nCold; Flanking\n2","box":[0.14061,0.80558,0.85519,0.81865]},{"text":"Rail Cannon\n1\n8\n10 / 20\n+1 LR\nArmour-Piercing 2\n3","box":[0.17015,0.83085,0.85519,0.84391]},{"text":"Arc Beam Cannon\n3\n2\n8 / 16\n+1 SR\nSustained Fire; Shock\n3","box":[0.14807,0.85611,0.85519,0.86917]},{"text":"Storm Cannon\n3\n4\n8 / 16\n-\nHull; Hot; Shock\n2","box":[0.16222,0.88137,0.85519,0.89444]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":76,"number":73,"label":"73","title":"Freegear Coalition","width":2000,"height":2829,"blocks":[{"text":"The Freegear Coalition was born not in \nboardrooms or fortified cities, but in the ashes \nleft \nbehind \nby \nthe \nSmogfall. \nWhen \ncorporations seized the last filtered enclaves \nand abandoned the weak to their fate, \nsurvivors banded together out of necessity. \nEscaped workers, deserters, engineers, and \nexiled families pooled their resources and \nknowledge, creating scattered enclaves hidden \nin ruins and wastelands. At first, these groups \nwere fragile and isolated. Over time, however, \nthey forged bonds, uniting under a simple \ncreed: survival without submission. Thus the \nFreegear Coalition emerged, a federation of \nrebels, scavengers, and independents bound \nby their refusal to live under corporate rule.","box":[0.11905,0.34009,0.49102,0.61163]},{"text":"Freegear \nsociety \nis \ndecentralised \nand \ncommunal. No board of directors or \naristocratic bloodlines dictate their lives. Each \nenclave governs itself, but together they share \nresources, knowledge, and protection. While \ncorporations demand obedience and sacrifice, \nthe Coalition values independence, ingenuity, \nand community. Their culture is one of \nresilience, refusing to surrender to corporate \noppression.","box":[0.11905,0.62874,0.49102,0.79693]},{"text":"Ironclads of the Freegear are chosen not by \nlineage or indoctrination, but by the people. A \npilot earns their place through courage, skill, \nor acts of defiance that prove their worth to \ntheir community. Some are deserters who","box":[0.11905,0.81404,0.49102,0.89671]},{"text":"stole their Rigs from corporate armies, others \nare mechanics who built their own from \nsalvage, and a few are everyday rebels thrust \ninto the role out of necessity. Their Rigs are \npractical, often a patchwork of stolen parts \nand improvised weaponry, painted with \nsymbols or slogans of resistance. A Freegear \nIronclad carries not just a machine into battle, \nbut the voice of their people.","box":[0.51355,0.34081,0.88552,0.4919]},{"text":"The Coalition does not fight like a traditional \narmy. They cannot match Krim’s endless \nlogistics or Nox’s industrial juggernaut, so \nthey fight on their own terms. Freegear \nsquadrons raid convoys, ambush supply lines, \nand \nsabotage \nfactories, \nstriking \nwhere \ncorporations are weakest. Their Rigs are \nunpredictable, \nreflecting \ntheir \npilots’ \ningenuity more than any standardised \ndoctrine. What they lack in numbers or \nrefinement, they make up for in adaptability \nand surprise.","box":[0.51355,0.50901,0.88552,0.71141]},{"text":"Relations with the great corporations are tense \nat best. Krim considers Freegear an intolerable \ndefiance of order, an enemy to be crushed \nabove all others. Nox barely acknowledges \nthem, treating them as pests to be crushed \nwhen they interfere with their industrial \nexpansion. \nArcus \noccasionally \noffers \nsympathetic support, seeing them as a useful \ncounterweight to rival powers, though the \nCoalition never forgets Arcus remains a","box":[0.51355,0.72851,0.88553,0.89671]},{"text":"FREEGEAR COALITION","box":[0.31573,0.2927,0.68423,0.32833]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":77,"number":74,"label":"74","title":"corporation at heart. Triton sometimes finds","width":2000,"height":2829,"blocks":[{"text":"corporation at heart. Triton sometimes finds \ncommon \nground \nwith \nFreegear \nwhen \ndefending against great corporations, but \nTriton’s insularity prevents any lasting \nalliance.","box":[0.11905,0.08396,0.49102,0.16663]},{"text":"The Freegear Coalition is not a superpower; it \nis an idea. Where the corporations see citizens \nas tools to be consumed, Freegear offers \nanother path, one of rebellion, independence, \nand survival on their own terms. For many \nscattered souls of the Smoglands, they \nrepresent resistance and hope: proof that life \ncan exist beyond the corporate walls.","box":[0.11905,0.18374,0.49102,0.31772]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":78,"number":75,"label":"75","title":"HIJACK","width":2000,"height":2829,"blocks":[{"text":"HIJACK","box":[0.43755,0.08141,0.56244,0.11704]},{"text":"LIGHT RIG","box":[0.45658,0.11502,0.54342,0.13283]},{"text":"Engine Heat Table","box":[0.49269,0.70578,0.63372,0.71884]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73034,0.87213,0.74459]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46474,0.84921,0.4778]},{"text":"Light\n4\n2\n10","box":[0.51852,0.48938,0.84188,0.50364]},{"text":"Structure Points","box":[0.49269,0.52984,0.61861,0.54291]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55449,0.86059,0.56874]},{"text":"9\n7\n7\n6","box":[0.53492,0.57951,0.83704,0.59377]},{"text":"Armour","box":[0.49269,0.6198,0.55593,0.63287]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64445,0.86059,0.6587]},{"text":"4+\n5+\n5+\n5+","box":[0.52907,0.66948,0.84289,0.68373]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.77978,0.86776,0.79284]},{"text":"Mech Rifle\n1\n6\n8 / 16\n-\nArmour-Piercing 1; Precision\n3","box":[0.17696,0.8051,0.85519,0.81816]},{"text":"Igniter\n3\n1\n4 / 8\n+1 SR\nIncendiary\n2","box":[0.1921,0.83036,0.85519,0.84343]},{"text":"Shredder Saw\n2\n4\n1\n+1\nMelee, Rupture\n2","box":[0.16656,0.85562,0.85519,0.86869]},{"text":"The Hijack originated within the scattered \nworkshops and salvage convoys of the early \nFreegear Coalition, where mechanics and \ndeserters began rebuilding abandoned and \nwrecked industrial walkers into crude but \nhighly \nadaptable \ncombat \nmachines. \nConstructed from a constantly changing \nmixture of salvaged components, the Hijack was \nnever intended to conform to standardised \nmanufacturing patterns, with many individual \nchassis differing significantly from one another \ndepending \non \navailable \nparts \nand \nthe \nexperience of their crews. Fast, unpredictable, \nand easy to repair in the field, Hijacks became \nfavoured among raiding groups striking at \ncorporate \nsupply \nlines \nthroughout \nthe \nSmoglands. The Hijack became proof that","box":[0.11905,0.4595,0.46212,0.72343]},{"text":"survival did not require corporate ownership.","box":[0.12741,0.72604,0.44953,0.73911]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":79,"number":76,"label":"76","title":"SCRAPHOUND","width":2000,"height":2829,"blocks":[{"text":"SCRAPHOUND","box":[0.38663,0.08141,0.61336,0.11704]},{"text":"MEDIUM RIG","box":[0.44305,0.11502,0.55694,0.13283]},{"text":"The Scraphound was developed specifically for \nlong-range salvage expeditions deep within the \nwastelands, where Freegear crews required \nmachines \ncapable \nof \nhauling \nrecovered \nmachinery and stripped iron plating back to \nhidden settlements and their workshops. Built \naround a rugged frame assembled from \nreclaimed industrial parts, the Scraphound \nprioritised reliability and carrying capacity over \nrefinement, allowing it to continue operating \nlong after more sophisticated machines had \nfailed. As conflict intensified across the \nSmoglands, many Scraphounds were armed \nand \nreinforced \nfor \ncombat, \nserving \nas \ndependable support platforms. Among Freegear \ncrews, a well-maintained Scraphound is often","box":[0.11905,0.4595,0.46212,0.70775]},{"text":"valued more highly than weapons themselves.\nEngine Heat Table","box":[0.12597,0.70578,0.63372,0.72343]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73034,0.87213,0.74459]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46474,0.84921,0.4778]},{"text":"Medium\n4\n2\n11","box":[0.50519,0.48938,0.84188,0.50364]},{"text":"Structure Points","box":[0.49269,0.52984,0.61861,0.54291]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55449,0.86059,0.56874]},{"text":"10\n8\n8\n7","box":[0.53008,0.57951,0.83704,0.59377]},{"text":"Armour","box":[0.49269,0.6198,0.55593,0.63287]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64445,0.86059,0.6587]},{"text":"4+\n4+\n4+\n5+","box":[0.52907,0.66948,0.84289,0.68373]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.77978,0.86776,0.79284]},{"text":"Sniper Cannon\n1\n7\n8 / 16\n+1 LR\nArmour-Piercing 1; Precision\n3","box":[0.16086,0.8051,0.85519,0.81816]},{"text":"Flame Thrower\n3\n2\n4 / 8\n+1 SR\nIncendiary\n2","box":[0.16075,0.83036,0.85519,0.84343]},{"text":"Ripper Saw\n2\n6\n1\n+1\nMelee, Rupture\n3","box":[0.17505,0.85562,0.85519,0.86869]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":80,"number":77,"label":"77","title":"DEFIANCE","width":2000,"height":2829,"blocks":[{"text":"DEFIANCE","box":[0.41621,0.08141,0.5838,0.11704]},{"text":"HEAVY RIG","box":[0.45247,0.11502,0.54753,0.13283]},{"text":"Armour","box":[0.49269,0.64594,0.55593,0.659]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.67058,0.86059,0.68484]},{"text":"3+\n4+\n3+\n4+","box":[0.52907,0.69561,0.84289,0.70987]},{"text":"Structure Points","box":[0.49269,0.55597,0.61861,0.56904]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.58062,0.86059,0.59487]},{"text":"11\n9\n9\n8","box":[0.53008,0.60565,0.83704,0.6199]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.49087,0.84921,0.50394]},{"text":"Heavy\n3\n3\n12","box":[0.51429,0.51552,0.84188,0.52977]},{"text":"Engine Heat Table","box":[0.49269,0.73191,0.63372,0.74498]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.75647,0.87213,0.77072]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78002,0.86776,0.79309]},{"text":"Rotary Cannon\n5\n2\n6 / 12\n-\nSustained Fire; Flanking\n3","box":[0.15973,0.80534,0.85519,0.81841]},{"text":"Demolisher Cannon\n2\n6\n10 / 20\n-1 SR\nExplosive 3\n2","box":[0.14154,0.8306,0.85519,0.84367]},{"text":"Cleaver Axe\n2\n7\n1\n+1\nMelee\n2","box":[0.17228,0.85587,0.85519,0.86893]},{"text":"The Defiance emerged during the growing \nconflicts between the Freegear Coalition and the \nexpanding corporate powers, designed by \nformer Ironclads and renegade engineers who \nsought to create a true front-line combat Rig \nindependent \nof \ncorporate \nmanufacturing \ndoctrine. \nUnlike \nmany \nearlier \nFreegear \nplatforms cobbled together from industrial \nmachinery, the Defiance was intentionally \nengineered for war from the outset, though still \nheavily reliant on salvaged components and \nimprovised systems. Its adaptable chassis \nallowed crews to field a wide variety of \nscavenged \nweaponry \nand \nbattlefield \nmodifications, making no two Defiance \nplatforms entirely alike. The Rig became a \nsymbol \nof \norganised \nresistance \nagainst \ncorporate control, often seen at the frontlines of \nraiding parties and strong defensive firing lines.","box":[0.11905,0.45974,0.46212,0.75503]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":81,"number":78,"label":"78","title":"RAMPART","width":2000,"height":2829,"blocks":[{"text":"RAMPART","box":[0.41512,0.08141,0.58486,0.11704]},{"text":"COLOSSAL RIG","box":[0.43977,0.11502,0.56022,0.13283]},{"text":"The Rampart is an exceptionally rare super-\nheavy platform developed by the Freegear \nCoalition during the escalating territorial wars \nof the late Age of Endless War. Limited \nindustrial capacity and the immense resources \nrequired to maintain such a machine mean that \nvery few Ramparts exist, with sightings of even \na single operational platform considered \nunusual throughout the wastelands. Mounted \nupon its immense chassis is the largest known \ncannon in the Smoglands, a devastating \nartillery weapon capable of crippling entire \nsquadrons at extreme distances. Within \nFreegear society, the appearance of a Rampart \ncarries enormous symbolic weight; citizens \ngather in great numbers simply to witness the \nmachine as it passes through their territories, \nand its departure for war is often marked by","box":[0.11905,0.45974,0.46213,0.73935]},{"text":"celebrations and fuel offerings.","box":[0.18005,0.74197,0.39688,0.75503]},{"text":"Engine Heat Table","box":[0.49269,0.70602,0.63372,0.71909]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73058,0.87213,0.74483]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46498,0.84921,0.47805]},{"text":"Colossal\n3\n3\n13","box":[0.50571,0.48963,0.84188,0.50388]},{"text":"Structure Points","box":[0.49269,0.53008,0.61861,0.54315]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55473,0.86059,0.56898]},{"text":"12\n11\n11\n10","box":[0.53008,0.57976,0.84188,0.59401]},{"text":"Armour","box":[0.49269,0.62005,0.55593,0.63311]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64469,0.86059,0.65895]},{"text":"2+\n3+\n3+\n4+","box":[0.52907,0.66972,0.84289,0.68398]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78002,0.86776,0.79309]},{"text":"Demolisher Cannon\n2\n6\n10 / 20\n-1 SR\nExplosive 3\n3","box":[0.14154,0.80534,0.85519,0.81841]},{"text":"Rotary Cannon\n5\n2\n6 / 12\n-\nFlanking; Sustained Fire\n3","box":[0.15973,0.8306,0.85519,0.84367]},{"text":"Precision Cannon\n1\n7\n8 / 16\n+1 LR\nArmour-Piercing 2; Precision\n2","box":[0.15061,0.85587,0.85519,0.86893]},{"text":"Annihilation Cannon\n2\n6\n12 / 24\n+1 LR\nHull\n2","box":[0.1372,0.88113,0.85519,0.89419]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":82,"number":79,"label":"79","title":"Mercenary Nomads","width":2000,"height":2829,"blocks":[{"text":"Not all Rig manufacturers were consumed \nduring the rise of the great Corporations.","box":[0.11905,0.14066,0.49102,0.17202]},{"text":"Scattered throughout the Smoglands remain \nnumerous smaller foundries and independent \nmanufacturing houses that survived the \nCorporate Ascendancy through negotiation \nor continued usefulness to the dominant \npowers surrounding them. While many were \nfully absorbed into the vast war economies of \nthe major Corporations, others retained \nlimited \nindependence \nby \nsupplying \nspecialised machinery, maintaining industrial \ninfrastructure, or producing small numbers of \nmilitarised Rig chassis under corporate \noversight.","box":[0.11905,0.18913,0.49102,0.40863]},{"text":"These surviving manufacturers became the \nprimary source of military hardware for the \nMercenary Nomads.","box":[0.11905,0.42574,0.49102,0.4742]},{"text":"Unlike the standing armies of the major \nCorporations, Nomad forces possess no \ncentralised industrial base of their own. \nInstead, Nomad Ironclads purchase, barter, \nsalvage, or commission their Rigs directly \nfrom the smaller subsidiary manufacturers \noperating within the fringes of corporate \nterritory. As a result, many Nomad squadrons \nare closely associated with the manufacturers \nthat supply them, often fielding distinct \nchassis patterns tied to particular foundries or \nindustrial regions.","box":[0.11905,0.4913,0.49102,0.69371]},{"text":"Though officially independent, these minor \nmanufacturers rarely exist entirely outside the \ninfluence of the great Corporations. Most \noperate within corporate borders, pay heavy \ntaxation, or rely upon protection agreements \nin order to continue manufacturing military-\ngrade equipment. In return, the Corporations \ntolerate the continued trade of militarised \nRigs for practical reasons. Nomad activity \nstabilises dangerous frontier regions, protects \ntrade routes, generates valuable taxation, and","box":[0.11905,0.71081,0.49102,0.89611]},{"text":"allows conflicts to be fought indirectly \nwithout committing official military assets.","box":[0.51355,0.14066,0.88552,0.17202]},{"text":"As a result, relationships between Nomad \ngroups, minor manufacturers, and the major \nCorporations vary greatly throughout the \nSmoglands. Some manufacturers maintain \nclose economic and political ties to their \nparent Corporations, while others quietly arm \nthose willing to fight against them.","box":[0.51355,0.18913,0.88552,0.30601]},{"text":"Despite their reputation for opportunism, \nmany Nomad crews possess considerable \nbattlefield \nexperience, \nhaving \nsurvived \nconditions and conflicts that would destroy \nconventional \nmilitary \nformations. \nTheir \nmachines are often poorly standardised and  \nmaintained through constant salvage and \nrepair, but in the hands of experienced \nIronclads they remain every bit as dangerous \nas the mass-produced Rigs fielded by the great \nCorporations.","box":[0.51355,0.32311,0.88888,0.50841]},{"text":"Mercenary Nomad chassis and those of the \nminor manufacturers may be fielded freely in \nany standard Squadron, whether alongside a \nsingle corporation's Rigs or in a mixed force. In \na Campaign, Nomad support follows the \nMercenary Nomad for Hire rules in the \nAftermath Phase.","box":[0.51355,0.52551,0.88557,0.64239]},{"text":"MERCENARy NOMADS","box":[0.31293,0.08141,0.68706,0.11704]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":83,"number":80,"label":"80","title":"Vost Armouries","width":2000,"height":2829,"blocks":[{"text":"Vost Armouries","box":[0.11905,0.14011,0.25252,0.15437]},{"text":"Operating \ndeep \nwithin \nthe \nindustrial \nterritories of the Krim Corporation, Vost \nArmories specialises in fast and adaptable \ncombat platforms intended for frontier \nconflicts, convoy defence, and independent \nmilitary \ncontracts. \nThough \nofficially \nsubordinate to Krim military authority, Vost \nmaintains a reputation for producing reliable \nand versatile machines popular among \nMercenary Nomads operating beyond the \nreach of major supply lines.","box":[0.11905,0.17147,0.49102,0.35677]},{"text":"Kaido Dynamics","box":[0.11905,0.37387,0.25977,0.38813]},{"text":"Kaido \nDynamics \nis \nan \nexperimental \nmanufacturer operating along the outer \nterritories bordering Nox Industries and the \nsouthern trade routes. Known for advanced \nventing systems and volatile plasma-based \nweapon technologies, Kaido’s machines are \nhighly sought after by experienced Ironclads \ndespite \ntheir \ndemanding \nmaintenance \nrequirements and unpredictable battlefield \nbehaviour.","box":[0.11905,0.40523,0.49102,0.57342]},{"text":"Harrow Industrial","box":[0.11905,0.59053,0.27294,0.60478]},{"text":"Harrow \nIndustrial \nprovides \nland-based \nindustrial and defensive support for Triton \nEngineering’s sprawling offshore operations, \nmanufacturing \nrugged \nutility \nplatforms \ncapable of operating in unstable coastal \nenvironments and refinery districts. Their \nmachines are known for their durability, \nsimple maintenance requirements, and strong \ndefensive \ncapabilities, \nmaking \nthem \na \ncommon sight protecting supply depots and \nfrontier \nsettlements \nthroughout \nTriton-\naligned territories.","box":[0.11905,0.62189,0.49102,0.82429]},{"text":"Lucent Arcworks","box":[0.51355,0.14011,0.65696,0.15437]},{"text":"Lucent \nArcworks \noperates \nunder \nthe \ntechnological shadow of Arcus Technologies, \nproducing \nhighly \nspecialised \ncombat \nplatforms built around advanced energy \nsystems \nand \nexperimental \nbattlefield \ntechnologies. Though smaller in scale than the \ngreat \nArcus \ndivisions, \nLucent \nremains \nrespected for its refined engineering standards \nand willingness to pursue unconventional \nreactor and weapons research unsuitable for \nlarger production programs.","box":[0.51355,0.17147,0.88552,0.35677]},{"text":"Salvager’s Union","box":[0.51355,0.37387,0.65347,0.38813]},{"text":"The Salvager’s Union is not a single \ncorporation, but a decentralised network of \nroaming \nsalvage \nconvoys \nand \nhidden \nworkshops \nscattered \nthroughout \nthe \nSmoglands. Serving as one of the primary \nindustrial \nbackbones \nof \nthe \nFreegear \nCoalition, the Union specialises not only in \nadapting salvaged machinery into functional \nwar machines, but also in the dangerous \nrecovery of materials and wrecked Rigs from \nthe battlefields of the Smoglands. Much of the \nraw metal, parts and fuel sustaining Freegear \nsettlements passes through Salvager’s Union \nhands at some stage.","box":[0.51355,0.40523,0.88553,0.64184]},{"text":"MINOR CORPORATIONS","box":[0.30508,0.08141,0.69491,0.11704]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":84,"number":81,"label":"81","title":"LANCER","width":2000,"height":2829,"blocks":[{"text":"LANCER","box":[0.4024,0.08141,0.53092,0.11704]},{"text":"MEDIUM RIG","box":[0.40972,0.11502,0.52361,0.13283]},{"text":"The Lancer was developed by Vost Armories as \na fast and highly adaptable combat platform \nintended to serve the growing demand for \nflexible front-line Rigs throughout the Krim \nterritories. Built around a lightweight but \ndurable frame with a wide variety of compatible \nweapon configurations, the Lancer quickly \nearned a reputation as an exceptionally \nversatile battlefield machine capable of fulfilling \nreconnaissance, assault, escort, and skirmishing \nroles with equal effectiveness. Even outside \nKrim influence, the silhouette of a Lancer has \nbecome a familiar sight accompanying convoys, \nroaming wasteland trade routes, and fighting in \ncountless \nsmaller \nskirmishes \nacross \nthe \nSmoglands. For many Mercenary Ironclads, \npurchasing a Lancer for their squadrons has \nnever been a regretful decision.","box":[0.11905,0.46283,0.46213,0.74244]},{"text":"Engine Heat Table","box":[0.49269,0.70911,0.63372,0.72217]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73367,0.87213,0.74792]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46807,0.84921,0.48113]},{"text":"Medium\n4\n3\n9","box":[0.50519,0.49271,0.83704,0.50697]},{"text":"Structure Points","box":[0.49269,0.53317,0.61861,0.54624]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55782,0.86059,0.57207]},{"text":"10\n9\n8\n7","box":[0.53008,0.58284,0.83704,0.5971]},{"text":"Armour","box":[0.49269,0.62313,0.55593,0.6362]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64778,0.86059,0.66203]},{"text":"4+\n5+\n4+\n4+","box":[0.52907,0.67281,0.84289,0.68706]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78311,0.86776,0.79617]},{"text":"Breach Cannon\n2\n4\n8 / 16\n-1 SR\nBombardment; Explosive 3\n2","box":[0.15939,0.80843,0.85519,0.82149]},{"text":"Flame Thrower\n3\n2\n4 / 8\n+1 SR\nIncendiary\n2","box":[0.16075,0.83369,0.85519,0.84676]},{"text":"Iron Lance\n2\n6\n1\n-\nMelee, Armour Piercing 2\n3","box":[0.17691,0.85895,0.85519,0.87202]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":85,"number":82,"label":"82","title":"DRIFTER","width":2000,"height":2829,"blocks":[{"text":"DRIFTER","box":[0.46115,0.08141,0.60549,0.11704]},{"text":"MEDIUM RIG","box":[0.47639,0.11502,0.59028,0.13283]},{"text":"The Drifter was developed by Kaido Dynamics, \nan \nexperimental \nmanufacturer \noperating \nwithin the outer territories of Nox Industries \nunder heavy corporate sponsorship. Unlike the \nmass-produced \nindustrial \nwar \nmachines \nfavoured by Nox, Kaido Dynamics pursued \nmore \nadvanced \nand \nunconventional \ntechnologies, The Drifter emerged as the \ncompany’s most successful combat platform: a \nfast and adaptable medium Rig. To compensate \nfor the immense heat generated by its \nexperimental systems, the chassis incorporates \nadvanced venting assemblies and enhanced \ncooling architecture far beyond what is \ncommonly found on standard industrial Rigs, \nallowing experienced Ironclads to sustain \naggressive combat output. Drifters are highly \nsought after for their state of the art \ntechnologies.","box":[0.11905,0.46283,0.46213,0.75812]},{"text":"Engine Heat Table","box":[0.49269,0.70911,0.63372,0.72217]},{"text":"-\n-\n-\n-\n-\n+0\n+0\n+2\n+4\n+6","box":[0.50692,0.73367,0.87213,0.74792]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46807,0.84921,0.48113]},{"text":"Medium\n3\n2\n9","box":[0.50519,0.49271,0.83704,0.50697]},{"text":"Structure Points","box":[0.49269,0.53317,0.61861,0.54624]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55782,0.86059,0.57207]},{"text":"12\n8\n8\n8","box":[0.53008,0.58284,0.83704,0.5971]},{"text":"Armour","box":[0.49269,0.62313,0.55593,0.6362]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64778,0.86059,0.66203]},{"text":"3+\n4+\n3+\n5+","box":[0.52907,0.67281,0.84289,0.68706]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78311,0.86776,0.79617]},{"text":"Flame Thrower\n3\n2\n4 / 8\n+1 SR\nIncendiary\n2","box":[0.16075,0.80843,0.85519,0.82149]},{"text":"Plasma Torch\n2\n3\n6 / 12\n+1 SR\nBreaching\n2","box":[0.16678,0.83369,0.85519,0.84676]},{"text":"Rapid Assault Cannon\n3\n2\n6 / 12\n+1 SR\n-\n2","box":[0.13401,0.85895,0.85519,0.87202]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":86,"number":83,"label":"83","title":"SILO","width":2000,"height":2829,"blocks":[{"text":"SILO\nLIGHT RIG","box":[0.45658,0.08141,0.54342,0.13283]},{"text":"Originally developed by Harrow Industrial as a \ncompact demolition and industrial clearance \nplatform, the Silo was designed to operate across \nthe harsh refinery zones and collapsing coastal \ninfrastructure surrounding Triton Engineering’s \nland-based holdings. Its stable quadrupedal \nframe allowed it to traverse uneven terrain \nwhile carrying heavy industrial tools used to \ndismantle ruined structures and clear defensive \nobstacles. As conflict across the Smoglands \nintensified, Harrow Industrial adapted the \ninexpensive chassis for military use, fitting the \nmachine with armour plating and combat \nweapon systems. Cheap to cast and easy to \nmaintain, the Silo became widely used as a \ndefensive support Rig protecting supply depots, \nrefinery corridors, and frontier settlements \naligned with Triton Engineering.","box":[0.11905,0.45974,0.46213,0.73935]},{"text":"Engine Heat Table","box":[0.49269,0.70602,0.63372,0.71909]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73058,0.87213,0.74483]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46498,0.84921,0.47805]},{"text":"Light\n4\n2\n8","box":[0.51852,0.48963,0.83704,0.50388]},{"text":"Structure Points","box":[0.49269,0.53008,0.61861,0.54315]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55473,0.86059,0.56898]},{"text":"10\n6\n8\n6","box":[0.53008,0.57976,0.83704,0.59401]},{"text":"Armour","box":[0.49269,0.62005,0.55593,0.63311]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64469,0.86059,0.65895]},{"text":"4+\n5+\n4+\n5+","box":[0.52907,0.66972,0.84289,0.68398]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78002,0.86776,0.79309]},{"text":"Mortar\n2\n4\n6 / 12\n-1 SR\nBombardment; Explosive 3\n3","box":[0.19052,0.80534,0.85519,0.81841]},{"text":"Igniter\n3\n1\n4 / 8\n+1 SR\nIncendiary\n2","box":[0.1921,0.8306,0.85519,0.84367]},{"text":"Wrecking Ball\n1\n5\n1\n+1\nMelee, Staggering\n2","box":[0.16476,0.85587,0.85519,0.86893]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":87,"number":84,"label":"84","title":"VAGABOND","width":2000,"height":2829,"blocks":[{"text":"VAGABOND","box":[0.40569,0.08141,0.5943,0.11704]},{"text":"LIGHT RIG","box":[0.45658,0.11502,0.54342,0.13283]},{"text":"The Vagabond was developed by the Salvager’s \nUnion as a long-range recovery and transport \nplatform \nintended \nto \nsupport \nNomad \nexpeditions \noperating \ndeep \nwithin \nthe \nwastelands beyond established trade routes. \nBuilt around a lightweight but durable chassis, \nthe machine features oversized fuel reserves and \na powerful industrial loader arm capable of \nlifting \nwrecked \ncomponents, \nrecovering \ndamaged machinery, and hauling salvage \nacross difficult terrain for extended periods \nwithout resupply. Though never intended as a \ndedicated combat platform, the harsh realities \nof the Smoglands saw many Vagabonds \ngradually armed and reinforced to defend \nthemselves against rival salvage crews.","box":[0.11905,0.45974,0.46213,0.70799]},{"text":"Engine Heat Table","box":[0.49269,0.70602,0.63372,0.71909]},{"text":"-\n-\n-\n-\n-\n+0\n+2\n+4\n+6\n+8","box":[0.50692,0.73058,0.87213,0.74483]},{"text":"Weight\nSpeed\nExhaust\nIron","box":[0.51207,0.46498,0.84921,0.47805]},{"text":"Light\n5\n2\n8","box":[0.52029,0.48963,0.83704,0.50388]},{"text":"Structure Points","box":[0.49269,0.53008,0.61861,0.54315]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.55473,0.86059,0.56898]},{"text":"9\n7\n7\n6","box":[0.53492,0.57976,0.83704,0.59401]},{"text":"Armour","box":[0.49269,0.62005,0.55593,0.63311]},{"text":"Hull\nArms\nLegs\nEngine","box":[0.52188,0.64469,0.86059,0.65895]},{"text":"3+\n5+\n5+\n5+","box":[0.52907,0.66972,0.84289,0.68398]},{"text":"Weapon\nROF\nSTR\nRNG\nACC\nPerks\nIron","box":[0.1853,0.78002,0.86776,0.79309]},{"text":"Missile Rack\n3\n2\n6 / 12\n+1 LR\nExplosive 3\n3","box":[0.17028,0.80534,0.85519,0.81841]},{"text":"Arc Thrower\n3\n1\n6 / 12\n+1 SR\nShock; Sustained Fire\n3","box":[0.16986,0.8306,0.85519,0.84367]},{"text":"Power Loader\n1\n5\n1\n-\nMelee, Breaching\n2","box":[0.16563,0.85587,0.85519,0.86893]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":88,"number":85,"label":"85","title":"Equipment List","width":2000,"height":2829,"blocks":[{"text":"Equipment Name\nEffect\nIron","box":[0.12073,0.19248,0.86774,0.20674]},{"text":"1. Penetrating Rounds\nChoose one ranged weapon. It has the \"Penetrating\" perk. \n2","box":[0.12549,0.2378,0.85403,0.25205]},{"text":"2. High Calibre \nAmmunition\nChoose one ranged weapon on this Rig, it has +1 STR. \n3","box":[0.12549,0.28878,0.85403,0.31491]},{"text":"3. Hot Point \nAmmunition","box":[0.12549,0.34606,0.21795,0.37219]},{"text":"When this Rig's heat is equal to or higher than the Heat Threshold, ranged \nweapons have +1 STR. \n2","box":[0.29674,0.34611,0.85403,0.37225]},{"text":"4. Advanced Ammo \nStorage\nMay re-roll any hit rolls for one attack made with a ranged weapon. Discard. \n1","box":[0.12549,0.40334,0.85403,0.42947]},{"text":"5. Synchronised Flexor \nMotors","box":[0.12549,0.46062,0.28909,0.48675]},{"text":"If this Rig equips two identical Melee weapons, it may re-roll all failed hit rolls \nonce per attack action.\n2","box":[0.29674,0.46067,0.85403,0.4868]},{"text":"6. Extended Barrel\nChoose one ranged weapon on this Rig, add 2\" / 4\" RNG to its SR and LR \nprofile. \n1","box":[0.12549,0.51795,0.85403,0.54408]},{"text":"7. Stabilised Weapon \nJoints\nThis Rig may make attack actions within a 180’ firing arc.\n2","box":[0.12549,0.57518,0.85403,0.60131]},{"text":"8. Sophisticated \nPeriscopes","box":[0.12549,0.63246,0.24033,0.65859]},{"text":"Gain +1 ACC when attacking with weapons targeting enemy Rigs that are in \nLOS and within 6\".\n1","box":[0.29674,0.63251,0.85403,0.65864]},{"text":"9. Arc-Enhanced \nTargeting System","box":[0.12549,0.68974,0.24649,0.71587]},{"text":"Gain +1 ACC when attacking with ranged weapons targeting enemy Rigs that \nare within LOS and are further than 12\" away.\n1","box":[0.29674,0.68979,0.85403,0.71592]},{"text":"10. Thermal Sights\nThis Rig has +1 ACC bonus against Rigs whose Heat is above the Heat \nThreshold.\n2","box":[0.12549,0.74707,0.85403,0.7732]},{"text":"11. Flare Launchers","box":[0.12549,0.81142,0.26257,0.8233]},{"text":"Fire a bright flare into the sky, marking a location on the battlefield. Until the \nend of the round, ALL Rigs gain +1 ACC attack rolls against targets within line \nof sight and 6\" of the flare. Discard.","box":[0.29674,0.79722,0.81957,0.83761]},{"text":"2","box":[0.84435,0.8106,0.85403,0.82485]},{"text":"12. Artillery Spotting \nModule","box":[0.12549,0.86158,0.27898,0.88771]},{"text":"This Rig may use an action [1] to call in an artillery bombardment anywhere \nwithin line of sight. Roll a D12 for each Rig within 6\" of the location. On a 9+, \na Rig suffers 1 STR 8 hit. Roll for location. Discard.","box":[0.29674,0.8545,0.81958,0.89489]},{"text":"2","box":[0.84435,0.86788,0.85403,0.88213]},{"text":"Rig Equipment\nEquipment offers unique strategies and loadouts for Rigs. Each Equipment can only be taken \nonce per Rig. Equipment with “Discard” should only be discarded after successful use. Where \nan Equipment is activated and generates heat, this is noted in square brackets [X].","box":[0.11905,0.08289,0.88553,0.15093]},{"text":"Equipment Table A - Improving attacks, accuracy and range","box":[0.11905,0.16304,0.59955,0.17729]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":89,"number":86,"label":"86","title":"Equipment Table B","width":2000,"height":2829,"blocks":[{"text":"Equipment Name\nEffect\nIron","box":[0.12073,0.18967,0.86823,0.20392]},{"text":"1. Reinforced Iron \nPlating\nThis Rig has +1 to armour rolls against front facing attacks.\n3","box":[0.12549,0.22869,0.85452,0.25482]},{"text":"2. Ablative Armour \nPlating\n After this Rig receives damage from an attack, ignore that damage. Discard.\n2","box":[0.12549,0.28597,0.85452,0.3121]},{"text":"3. Impact Roll Cage\nThis Rig has +1 to armour rolls when targeted by melee and ram attacks.\n1","box":[0.12549,0.34955,0.85452,0.3638]},{"text":"4. Reinforced Leg \nJoints\nThe Rig gains immunity to Slowed and Immobilised.\n2","box":[0.12549,0.40053,0.85452,0.42666]},{"text":"5. Concentrated Fuel\nThis Rig has +2\" to SPD. If the Rig suffers a Fuel Line Rupture, take 2 additional \ndamage to the engine.\n2","box":[0.12549,0.45786,0.85452,0.48399]},{"text":"6. Heat Conductive \nLubricants\nIf this Rig's engine heat is above the threshold, it has +2 SPD.\n1","box":[0.12549,0.51509,0.85452,0.54122]},{"text":"7. Hydraulic Anchor \nSpikes","box":[0.12073,0.57236,0.26773,0.5985]},{"text":"If this Rig remained stationary and did not move during its turn, it has +1 \nACC. If it fires with this bonus, it may not move until the end of the round.\n2","box":[0.29198,0.57242,0.85452,0.59855]},{"text":"8. Extinguisher\nWhen making a Heat Threshold roll, first roll a D12. On a 4+, ignore the Heat \nThreshold roll. Discard.\n1","box":[0.12549,0.6297,0.85452,0.65583]},{"text":"9. Exotic Engine \nCoolant\nReduce final results of Heat Threshold Rolls by 1.\n1","box":[0.12549,0.68692,0.85452,0.71306]},{"text":"10. Thermal Purge \nVent","box":[0.12549,0.7442,0.25862,0.77034]},{"text":"If this Rig remained stationary and did not move during its turn, reduce \nEngine Heat by 2 in the Maintenance Phase.\n2","box":[0.29674,0.74426,0.85452,0.77039]},{"text":"11. Supplementary \nHeat Vent","box":[0.12549,0.80148,0.261,0.82762]},{"text":"When this Rig's heat is higher than the Heat Threshold, it may use a Vent Heat \nAction [0] once per activation. This Rig's next attack costs [-1] but suffers -1 \nACC.","box":[0.29674,0.79441,0.82055,0.8348]},{"text":"1","box":[0.84484,0.80778,0.85452,0.82204]},{"text":"12. External Fuel \nTanks\nThe next action does not generate any heat. Discard.\n1","box":[0.12549,0.85876,0.85452,0.88489]},{"text":"Equipment Table B - Protection, movement and engine / heat management","box":[0.11905,0.16235,0.71508,0.1766]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":90,"number":87,"label":"87","title":"Equipment Table C","width":2000,"height":2829,"blocks":[{"text":"Equipment Name\nEffect\nIron","box":[0.12073,0.15996,0.86726,0.17421]},{"text":"1. Smoke Dispensers\nUse an action to deploy a smokescreen [1]. ALL Rigs within 6\" of this Rig are \nconsidered to be in Light Cover until the end of the round.\n2","box":[0.12549,0.199,0.85275,0.22514]},{"text":"2. Reflexive Sensor \nUnit","box":[0.12549,0.25623,0.26008,0.28236]},{"text":"At any time, place any preparation token next to any one friendly Rig without \ngenerating heat. Discard.\n1","box":[0.29198,0.25628,0.85275,0.28241]},{"text":"3. Manual Override \nPanel","box":[0.12549,0.31351,0.26638,0.33964]},{"text":"Re-roll any dice, at the cost of generating 1 heat per dice re-rolled. Dice re-\nrolled this way can only be re-rolled once.\n1","box":[0.29674,0.31356,0.85356,0.33969]},{"text":"4. Grapple Winch Unit","box":[0.12549,0.37792,0.28441,0.38979]},{"text":"Make an attack action with RNG 8” and ACC +1 for [0]. If the target is equal \nto or lighter in weight class, move the target Rig directly towards this Rig by \nD6+2”. If the target is of heavier weight class, move toward the target Rig \ninstead. A Rig stops being pulled if it collides with terrain. Discard.","box":[0.29674,0.35659,0.81863,0.41123]},{"text":"1","box":[0.84388,0.37709,0.85356,0.39134]},{"text":"5. Radio Scrambler\n Choose an enemy Rig within 18\". Each controlling player rolls a D12. If the \ntarget Rig rolls lower, that Rig is Stalled. Discard.\n1","box":[0.12073,0.42812,0.85275,0.45425]},{"text":"6. Ramming Frame\nThis Rig may use the \"Ram\" action while suffering only half damage to itself, \nrounded up.\n2","box":[0.12549,0.4854,0.85275,0.51153]},{"text":"7. Unstable Power \nSource","box":[0.12549,0.54263,0.25479,0.56876]},{"text":"As an action, the Rig may choose to self destruct. It is destroyed and \nautomatically explodes.\n1","box":[0.29674,0.54268,0.85275,0.56881]},{"text":"8. Emergency Repair \nKit\nRestore 3 Structure Points to any damaged part of the Rig. Discard.\n2","box":[0.12549,0.59991,0.85275,0.62604]},{"text":"9. Battlefield Recovery \nRig","box":[0.12549,0.65719,0.28619,0.68332]},{"text":"[CAMPAIGN ONLY] When purchased in the campaign, the Recovery \nRig allows the player to roll on the salvage table D3 times in the Salvage \nthe Battlefield step in the Aftermath Phase.","box":[0.29198,0.64825,0.81904,0.69267]},{"text":"5","box":[0.84428,0.66393,0.85315,0.67699]},{"text":"10. Iron Market Parts \nCache","box":[0.12549,0.71447,0.27962,0.7406]},{"text":"[CAMPAIGN ONLY] Once per Aftermath Phase, when repairing a Rig, \nignore one permanent negative trait gained from repairs.\n3","box":[0.29198,0.71337,0.85315,0.74211]},{"text":"11. Contracted \nRecovery Crew","box":[0.12549,0.77175,0.23335,0.79788]},{"text":"[CAMPAIGN ONLY] When checking if a destroyed Rig is lost, add +2 \nto the recovery roll. This equipment does not function if the Rig \nexploded.","box":[0.29198,0.76281,0.81901,0.80723]},{"text":"3","box":[0.84388,0.77805,0.85356,0.7923]},{"text":"12. Experimental \nLoad-Bearing Frame","box":[0.12549,0.82903,0.27115,0.85516]},{"text":"[CAMPAIGN ONLY] Choose a Rig in your Squadron, it gains +1 Iron \ncapacity.\n3","box":[0.29198,0.82793,0.85554,0.85667]},{"text":"Equipment Table C - Battlefield tricks, reactions and campaign-only gear","box":[0.11905,0.13053,0.69853,0.14479]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":91,"number":88,"label":"88","title":"Illustration","width":2000,"height":2829,"blocks":[{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":92,"number":89,"label":"89","title":"Deploying to War and Formations","width":2000,"height":2829,"blocks":[{"text":"Of Oil and Iron has no army-points system. \nBalance in standard play comes from both \nsides fielding a Squadron Formation of the \nsame type; within their Iron capacity, players \nare free to equip their Rigs however they wish. \nPlayers may choose to field different \nSquadron formations of the same formation \ntype for a more narrative experience.","box":[0.51355,0.12377,0.88553,0.25775]},{"text":"Of Oil and Iron is a setting shaped by rival \ncorporations, roaming nomads, and the \nbrutal struggle for control of the Smoglands.","box":[0.11905,0.12293,0.49102,0.1714]},{"text":"In this section, you will find rules for \nEngagements, the standard way to play Of Oil \nand Iron, and also the Campaign, which ties \ntogether multiple Engagements into a longer, \nstory driven system.","box":[0.11905,0.1885,0.49106,0.27117]},{"text":"To play an Engagement, players must:","box":[0.11905,0.28828,0.42171,0.30253]},{"text":"• \nChoose a Squadron Formation, of the \nsame type (Skirmish, Operation or \nWarfront).","box":[0.11905,0.31963,0.49102,0.3681]},{"text":"• \nEquip Weapons and Equipment on the \nRigs of their chosen Squadron type.","box":[0.11905,0.3852,0.49102,0.41656]},{"text":"• \nChoose a Deployment.","box":[0.11905,0.43366,0.33303,0.44792]},{"text":"• \nChoose an Engagement.","box":[0.11905,0.46502,0.34392,0.47928]},{"text":"• \nSet up the Battlefield.","box":[0.11905,0.49638,0.31999,0.51063]},{"text":"Following the rules for Engagements are \nSpecial Engagements, which have specified \nDeployments. These Engagements are a more \nnarrative way to play, and may be less \nbalanced than standard Engagements.","box":[0.11905,0.52774,0.49102,0.61041]},{"text":"Assembling a Squadron","box":[0.11905,0.62627,0.33345,0.6429]},{"text":"A collection of Rigs fielded to battle are \nknown as a Squadron. Squadrons are fielded \nin formations dependent on the size of the \nengagement. Players agree on an Engagement, \nthen choose a Squadron Formation from the \navailable selection. Players add to their \nsquadron the Rigs listed on the Squadron \nFormation.","box":[0.11905,0.6602,0.49102,0.79418]},{"text":"DEPLOYING TO WAR","box":[0.11905,0.08141,0.45817,0.11704]},{"text":"A \nSkirmish \nor \nan \nOperation \nare \nrecommended for most players, while a \nWarfront would be a lengthy battle.","box":[0.51355,0.70565,0.88552,0.75411]},{"text":"SKIRMISH","box":[0.51355,0.27674,0.59773,0.29337]},{"text":"OPERATION","box":[0.51355,0.39036,0.60437,0.40699]},{"text":"WARFRONT","box":[0.51355,0.54374,0.60125,0.56037]},{"text":"Formation\nLight\nMedium\nHeavy\nColossal","box":[0.52514,0.30249,0.87708,0.31437]},{"text":"Sword\n2\n1","box":[0.54149,0.32205,0.71673,0.33392]},{"text":"Mace\n1\n1\n1","box":[0.5445,0.34155,0.78403,0.35343]},{"text":"Dagger\n4","box":[0.53825,0.36105,0.64943,0.37293]},{"text":"Formation\nLight\nMedium\nHeavy\nColossal","box":[0.52514,0.41611,0.87708,0.42799]},{"text":"Claymore\n1\n1\n1\n1","box":[0.52985,0.43567,0.85133,0.44754]},{"text":"Broadsword\n3\n1\n1","box":[0.52195,0.45517,0.85133,0.46705]},{"text":"Lance\n1\n2\n2","box":[0.54271,0.47467,0.78403,0.48655]},{"text":"Morningstar\n1\n3\n1","box":[0.52035,0.49418,0.78403,0.50606]},{"text":"Axe\n1\n3","box":[0.5494,0.51368,0.78403,0.52556]},{"text":"Formation\nLight\nMedium\nHeavy\nColossal","box":[0.52514,0.56914,0.87708,0.58102]},{"text":"Battleaxe\n2\n2\n2","box":[0.53212,0.5887,0.85133,0.60058]},{"text":"Greatsword\n4\n2\n1\n1","box":[0.5236,0.6082,0.85133,0.62008]},{"text":"Warhammer\n2\n3\n1","box":[0.52015,0.62771,0.85133,0.63958]},{"text":"Scythe\n3\n2\n2","box":[0.54037,0.64721,0.85133,0.65909]},{"text":"Maul\n2\n4","box":[0.54515,0.66671,0.78403,0.67859]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":93,"number":90,"label":"90","title":"Iron Costs and Equipment","width":2000,"height":2829,"blocks":[{"text":"Each \nRig \nmay \nbe \nfielded \nwith \nits \ncorresponding \nprinted \nRig \nCommand \nTerminal, Weapon Cards and Equipment \nCards. However players may choose to use the \nSquadron Roster to fill out this information \ninstead - which is a more printer-friendly \nversion to play, encapsulating all of the \ninformation on the terminal and card assets. \nThis can be found at the back of this book.","box":[0.11905,0.08396,0.49102,0.23505]},{"text":"Iron Costs","box":[0.11905,0.25215,0.20732,0.26641]},{"text":"When outfitting a Rig, players must carefully \nchoose weapons and equipment within the \nlimits of the Rig’s Iron Capacity. Each Rig has \na fixed Iron Capacity that determines how \nmuch gear it can carry, with heavier weapons \nand advanced equipment costing more Iron.","box":[0.11905,0.28351,0.49102,0.38329]},{"text":"Players must strategise to create efficient and \neffective loadouts, balancing powerful options \nwith the constraints of the Rig’s capacity. \nChoose wisely, every weapon and piece of \nequipment shapes how your Rig performs on \nthe battlefield!","box":[0.11905,0.40039,0.49102,0.50017]},{"text":"Equipping Weapons and Equipment","box":[0.11905,0.51504,0.42338,0.52929]},{"text":"Equipping weapons on a Rig is a critical step \nin customising its battlefield role and \neffectiveness. \nEach \nRig \nhas \nspecific \nrestrictions based on its weight class and \nmanufacturer, and the equippable weapons \nare listed in the Rig Operating Manual (p 41).","box":[0.11905,0.5464,0.49102,0.64617]},{"text":"Colossal Rigs may equip a single additional \nHull-Mounted Weapon, giving them extra \nfirepower.","box":[0.11905,0.66328,0.49102,0.71174]},{"text":"While there are weapon cards for each \nweapon included with each Rig, a summary of \nweapons is included which are useful when \npreparing the Rig Squadron Roster.","box":[0.11905,0.72884,0.49102,0.79441]},{"text":"All Rigs must always equip at least two \nweapons. After equipping weapons, Rigs may \nuse the remaining Iron to equip Equipment. \nEquipment may only be equipped once per \nRig.","box":[0.11905,0.81151,0.49102,0.89418]},{"text":"A Rig may equip two of the same weapon, and \nmay fill both weapon slots with melee \nweapons. A Rig equipped with two melee \nweapons gains the benefits described under \nthe Melee weapon perk.","box":[0.51355,0.08396,0.88553,0.16663]},{"text":"Engagements","box":[0.51355,0.18249,0.63272,0.19912]},{"text":"Whenever players sit down for a game of Of \nOil and Iron, they are agreeing to play an \nEngagement. An Engagement outlines how \nboth sides deploy their Rigs, how long the \nbattle takes, and what conditions decide \nvictory.","box":[0.51355,0.21642,0.88556,0.3162]},{"text":"Players can choose an Engagement or roll \nrandomly for one using a D12 and consulting \nthe table below. Engagements 9-12 are Special \nEngagements, with asymmetric objectives.","box":[0.51355,0.3333,0.88553,0.39887]},{"text":"Roll\nEngagement\n1\nIron Clash\n2\nHigh Value Target\n3\nPoint of Control\n4\nTotal Command\n5\nPush the Line\n6\nSupply Airdrop\n7\nSalvage Heist\n8\nSabotage\n9\nAmbush\n10\nHold the Line\n11\nBreakthrough\n12\nSiege","box":[0.56443,0.42596,0.78058,0.69474]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[{"page":41,"end":null,"label":"p 41","box":[0.43908,0.63192,0.47358,0.64617]}]},{"index":94,"number":91,"label":"91","title":"The Battlefield","width":2000,"height":2829,"blocks":[{"text":"The Battlefield","box":[0.11905,0.08383,0.24153,0.09809]},{"text":"The Smoglands stretch across a vast region of \nbroken \nindustry, \nabandoned \nfrontiers, \npolluted coasts, and scattered enclaves of \ncorporate power. Battles take place across an \nenormous range of environments.","box":[0.11905,0.11519,0.49102,0.19786]},{"text":"Designed to fit on a kitchen table for \naccessible gaming, there are a choice of \neffective game board sizes widely available in \nthe market. Players may choose any size of \nboard in combination with any Engagement.","box":[0.11905,0.21497,0.49102,0.29764]},{"text":"• \n22 x 30 inches","box":[0.11905,0.30595,0.26721,0.32021]},{"text":"• \n24 x 24 inches","box":[0.11905,0.32852,0.26264,0.34277]},{"text":"• \n36 x 36 inches","box":[0.11905,0.35109,0.26264,0.36534]},{"text":"22 x 30 inches is the standard for the \nEngagements in this rulebook. Players using a \nsmaller or larger battlefield should adjust \ndistances and deployment zones as needed.","box":[0.11905,0.38245,0.49102,0.44801]},{"text":"When deploying Warfront sized Squadrons, a \nlarger battlefield is recommended (36 x 36 \ninches, or more!).","box":[0.11905,0.46512,0.49102,0.51358]},{"text":"Terrain","box":[0.11905,0.53068,0.18172,0.54494]},{"text":"The battlefield is more than scenery. It shapes \nthe flow of combat. Dense ruins give Light \nRigs places to skirmish. Open ground allows \nHeavy Rigs to bring their full power to bear. \nElevated \nstructures, \ntrenches, \npipelines, \nbroken Rigs, slag piles, abandoned Rigs, and \nstorm barriers all play a part in how each Rig \nfights. Choosing diverse terrain creates \nmemorable battles!","box":[0.11905,0.56204,0.49102,0.71313]},{"text":"There are very few battles that take place over \na wide, open wasteland devoid of features. \nPlayers can choose and agree upon the \namount and density of terrain. Certain \nEngagements will suggest terrain types and \namounts, but players should build the \nbattlefield that they want to play on.","box":[0.11905,0.73024,0.49102,0.84712]},{"text":"When placing terrain, players should alternate \nplacing a piece of terrain, until they both agree","box":[0.11905,0.86422,0.49102,0.89558]},{"text":"the battlefield is sufficiently populated with \nterrain.","box":[0.51355,0.08396,0.88552,0.11532]},{"text":"Terrain in Of Oil and Iron offers blocking of \nline of sight, and are simple in their \nimplementation:","box":[0.51355,0.13242,0.88552,0.18089]},{"text":"When choosing how much terrain to add to \nthe battlefield for the Engagement, players can \nchoose a level of terrain density, or roll on the \nfollowing table, unless otherwise specified in \nthe Engagement.","box":[0.51355,0.19799,0.88552,0.28066]},{"text":"This will be noted as “Standard Engagement”. \nCertain Engagements may have different rules \nor recommendations for the battlefield and \nterrain.","box":[0.51355,0.4232,0.88556,0.48876]},{"text":"Engagement Length","box":[0.51355,0.50587,0.68226,0.52012]},{"text":"Engagements usually last between 4 and 6 \nrounds unless specific victory conditions are \nmet. At the end of the 4th round, roll a D12. \nOn a roll of 8+, the Engagement ends. \nOtherwise, roll again at the end of the 5th","box":[0.51355,0.53723,0.88552,0.6199]},{"text":"round - this time, the Engagement ends on a \nroll of 5+. The Engagement automatically \nends at the end of the 6th round.","box":[0.51355,0.62275,0.88552,0.67121]},{"text":"This will be noted as “Standard Engagement”. \nCertain Engagements may have different rules \nfor the length of Engagement.","box":[0.51355,0.68832,0.88556,0.73678]},{"text":"Deployments","box":[0.51355,0.75388,0.62613,0.76814]},{"text":"Deployments show players where their \nSquadrons begin the Engagement. Each \ndeployment map illustrates the battlefield \ndivided into a grid, with every square \nrepresenting a 5 inch by 5 inch area. These \nexamples use the standard 22 x 30 inch \nbattlefield size, and should be adjusted based","box":[0.51355,0.78524,0.88552,0.90212]},{"text":"D6 Roll\nTerrain Density\n1-2\nLow 10% \n3-4\nMedium 30%\n5-6\nHigh 50%","box":[0.57793,0.31374,0.81442,0.39167]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":95,"number":92,"label":"92","title":"Battlefield and Objectives","width":2000,"height":2829,"blocks":[{"text":"on player preference if other board sizes are \nused.","box":[0.11905,0.08396,0.49101,0.11532]},{"text":"Players can choose a Deployment, or roll a \nD12 and consult the numbered list of \nDeployments to choose randomly.","box":[0.11905,0.13242,0.49102,0.18089]},{"text":"When deploying, players roll off to see who \ndeploys first. Then, starting with the winning \nplayer, players take turns placing one Rig in \ntheir deployment zone, until all Rigs are \ndeployed.","box":[0.11905,0.19799,0.49102,0.28066]},{"text":"This will be noted as “Standard Deployment”. \nCertain Engagements may have different rules \nfor Deployment.","box":[0.11905,0.29777,0.49106,0.34623]},{"text":"OBJECTIVES","box":[0.11905,0.36209,0.21601,0.37872]},{"text":"Objectives represent strategic assets, resource \ncaches, transmission relays, fuel depots, \nsalvage sites, or other valuable locations \nacross the battlefield. Many Engagements use \nObjectives to determine victory.","box":[0.11905,0.39602,0.49102,0.47869]},{"text":"Objectives may be represented using the \nprovided tokens, terrain pieces, or any \nsuitably thematic models agreed upon by both \nplayers.","box":[0.11905,0.49579,0.49102,0.56136]},{"text":"Unless stated otherwise by the Engagement, \nObjectives should be placed at least 6” away \nfrom all battlefield edges and at least 6” away \nfrom each other.","box":[0.11905,0.57847,0.49102,0.64403]},{"text":"A Rig controls an Objective if it is within 3” of \nit. Unless otherwise stated, a Rig may only \ncontrol one Objective at a time. If both players \nhave Rigs controlling the same Objective, it is \ncontested and neither player controls it.","box":[0.11905,0.66114,0.49102,0.74381]},{"text":"When an engagement instructs to use an \nobjective, players may choose which objective \ntype to use for the game. Salvage and Valuable \nAsset objectives are only used for certain \nengagements.","box":[0.11905,0.76091,0.49102,0.84358]},{"text":"Domination: The player with the greatest \nnumber of Rigs controlling the Objective \ncontrols it.","box":[0.51355,0.08396,0.88552,0.13242]},{"text":"Weight of Iron: The player with the heaviest \nweight class Rig controlling the objective \ncontrols it.","box":[0.51355,0.14953,0.88553,0.19799]},{"text":"Heat Supremacy: The player with the Rig that \nhas the hottest engine controlling the \nobjective controls it.","box":[0.51355,0.21509,0.88552,0.26356]},{"text":"Salvage: A Rig, when within 1” of the \nobjective, may perform an action with a heat \ncost of [2], to collect the piece of salvage. \nRemove it from the battlefield and place it \nnext to the capturing Rig’s control terminal.","box":[0.51355,0.28066,0.88553,0.36333]},{"text":"In campaign mode, each Salvage objective is \nworth 3 Salvage.","box":[0.51355,0.38044,0.88553,0.41179]},{"text":"This objective may not be suitable for all \nengagements.","box":[0.51355,0.4289,0.88552,0.46026]},{"text":"Valuable Asset: This objective requires to be \ndestroyed to claim it, using the following \nprofile:","box":[0.51355,0.47736,0.88553,0.52582]},{"text":"An objective token","box":[0.62514,0.77798,0.76935,0.79223]},{"text":"Victory Points","box":[0.51355,0.80933,0.63488,0.82359]},{"text":"Many engagements use Victory Points (VP). \nUsually the player with the most VP at the end \nof the engagement wins the game.","box":[0.51355,0.84069,0.88552,0.88916]},{"text":"Structure Points\nArmour","box":[0.54816,0.54345,0.81784,0.55533]},{"text":"8\n5+","box":[0.60096,0.56651,0.79889,0.57958]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":96,"number":93,"label":"93","title":"Deployments","width":2000,"height":2829,"blocks":[{"text":"Deployment 2\nDeployment 1","box":[0.24558,0.11427,0.75442,0.12852]},{"text":"Deployment 4\nDeployment 3","box":[0.24558,0.40528,0.75442,0.41954]},{"text":"Deployment 6\nDeployment 5","box":[0.24558,0.68851,0.75442,0.70276]},{"text":"DEPLOYMENTS","box":[0.39965,0.08196,0.60035,0.11047]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[],"figures":[[0.11864,0.13532,0.48685,0.33165],[0.51315,0.13532,0.88135,0.33165],[0.11864,0.42647,0.48685,0.6228],[0.51315,0.42647,0.88135,0.6228],[0.11864,0.70956,0.48685,0.90589],[0.51315,0.70122,0.88135,0.89755]]},{"index":97,"number":94,"label":"94","title":"Deployments 7–12","width":2000,"height":2829,"blocks":[{"text":"Deployment 8\nDeployment 7","box":[0.24558,0.11427,0.75442,0.12852]},{"text":"Deployment 10\nDeployment 9","box":[0.24558,0.40528,0.75925,0.41954]},{"text":"Deployment 12\nDeployment 11","box":[0.24074,0.68782,0.75925,0.70208]},{"text":"For Engagements with more than 2 players.","box":[0.55624,0.90715,0.83826,0.91903]},{"text":"For Engagements with more than 2 players.","box":[0.55624,0.62436,0.83826,0.63624]},{"text":"For Engagements with more than 2 players.","box":[0.16174,0.90715,0.44375,0.91903]},{"text":"For each of their Rigs, players take turns to each roll a D6, \n1-6 corresponding to their letter counterparts. That Rig is","box":[0.11905,0.33228,0.49029,0.35842]},{"text":"deployed in the corresponding letter on their side.","box":[0.14302,0.36079,0.46247,0.37267]},{"text":"DEPLOYMENTS","box":[0.39965,0.08196,0.60035,0.11047]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[],"figures":[[0.11864,0.13532,0.48685,0.33165],[0.51315,0.13593,0.88135,0.33227],[0.11864,0.42677,0.48685,0.6231],[0.51315,0.42677,0.88135,0.6231],[0.11864,0.70956,0.48685,0.90589],[0.51315,0.70956,0.88135,0.90589]]},{"index":98,"number":95,"label":"95","title":"Engagements","width":2000,"height":2829,"blocks":[{"text":"ENGAGEMENT: IRON CLASH","box":[0.31594,0.08196,0.68402,0.11047]},{"text":"Corporations collide in the open wastes where ruined pipelines and mud plains stretch into the \nhorizon. Neither side expected resistance, but both refuse to back down. Their objective: destroy \nthe enemy.","box":[0.11905,0.11678,0.88553,0.16524]},{"text":"Battlefield and Deployment","box":[0.11905,0.17611,0.35141,0.19036]},{"text":"Standard Engagement.","box":[0.11905,0.20747,0.30531,0.22172]},{"text":"Engagement Length","box":[0.11905,0.23882,0.28775,0.25308]},{"text":"Standard Engagement, or when one Squadron \nis left standing.","box":[0.11905,0.27018,0.49102,0.30154]},{"text":"Engagement Special Rules","box":[0.11905,0.31864,0.339,0.3329]},{"text":"Destroy the enemy Squadron.","box":[0.11905,0.35,0.35823,0.36426]},{"text":"Victory Conditions","box":[0.51355,0.17611,0.67643,0.19036]},{"text":"Players total the VP earned from objectives. \nHighest score at the end of the engagement \nwins.","box":[0.51355,0.20747,0.88552,0.25593]},{"text":"Players receive VP for each enemy Rig they \nhave destroyed based on the Rig’s weight class:","box":[0.51355,0.27303,0.88552,0.30439]},{"text":"Weight Class\nVictory Points\nLight\n2\nMedium\n3\nHeavy\n4\nColossal\n5","box":[0.534,0.3372,0.82335,0.41502]},{"text":"ENGAGEMENT: HIGH VALUE TARGET","box":[0.25663,0.48937,0.74336,0.51788]},{"text":"Some assets are worth more than an entire battlefield. A prototype Rig, a command unit, a \ncorporate defector… Whatever it is, its destruction or extraction will shift the balance of power. \nExpect overwhelming resistance and no margin for error.","box":[0.11905,0.52306,0.88553,0.57152]},{"text":"Battlefield and Deployment","box":[0.11905,0.58246,0.35141,0.59671]},{"text":"Standard Engagement.","box":[0.11905,0.61382,0.30531,0.62807]},{"text":"Engagement Length","box":[0.11905,0.64518,0.28775,0.65943]},{"text":"Standard Engagement, or when all but one \nHigh Value Target  is eliminated.","box":[0.11905,0.67653,0.49102,0.70789]},{"text":"Engagement Special Rules","box":[0.11905,0.725,0.339,0.73925]},{"text":"Each player must then nominate one of their \nRigs as their High Value Target.","box":[0.11905,0.75636,0.49102,0.78771]},{"text":"Eliminate the opponent’s High Value Target.","box":[0.11905,0.80482,0.47366,0.81907]},{"text":"Victory Conditions","box":[0.51355,0.58246,0.67643,0.59671]},{"text":"The last player with their High Value Target \nstill intact wins the engagement.","box":[0.51355,0.61382,0.86798,0.64518]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":99,"number":96,"label":"96","title":"ENGAGEMENT: POINT OF CONTROL","width":2000,"height":2829,"blocks":[{"text":"Weight Class\nVictory Points\nLight\n2\nMedium\n3\nHeavy\n4\nColossal\n5","box":[0.534,0.34802,0.82335,0.42584]},{"text":"ENGAGEMENT: POINT OF CONTROL","box":[0.27107,0.08196,0.72892,0.11047]},{"text":"Refineries, oil stockpiles, choke points… Hold them, and the battlefield bends to your will. Lose \nthem, and your forces rust in the dust while the enemy tightens its grip.","box":[0.11905,0.11678,0.88552,0.14814]},{"text":"Battlefield and Deployment","box":[0.11905,0.17611,0.35141,0.19036]},{"text":"Standard Engagement.","box":[0.11905,0.20747,0.30074,0.22172]},{"text":"Each player then takes turns places two \nobjectives.","box":[0.11905,0.23882,0.49102,0.27018]},{"text":"Engagement Length","box":[0.11905,0.28729,0.28775,0.30154]},{"text":"Standard Engagement.","box":[0.11905,0.31864,0.30074,0.3329]},{"text":"Engagement Special Rules","box":[0.11905,0.35,0.339,0.36426]},{"text":"At the end of each round, each player gets 2 \nVP for each controlled objective.","box":[0.11905,0.38136,0.49102,0.41272]},{"text":"Victory Conditions","box":[0.51355,0.17611,0.67643,0.19036]},{"text":"Players total the VP earned from objectives. \nThe player with the highest score at the end of \nthe engagement wins.","box":[0.51355,0.20747,0.88552,0.25593]},{"text":"Players also receive Victory Points for each \nenemy Rig they have destroyed based on the \nRig’s weight class:","box":[0.51355,0.27303,0.88552,0.3215]},{"text":"ENGAGEMENT: TOTAL COMMAND","box":[0.27859,0.48937,0.72139,0.51788]},{"text":"Secure command zones, crush resistance, and prove to the Smoglands your corporation controls \nthe battlefield from horizon to horizon.","box":[0.11905,0.52306,0.88552,0.55442]},{"text":"Battlefield and Deployment","box":[0.11905,0.58246,0.35141,0.59671]},{"text":"Standard Engagement. Players take turns \nplacing one objective each.","box":[0.11905,0.61382,0.49102,0.64518]},{"text":"Engagement Length","box":[0.11905,0.66228,0.28775,0.67653]},{"text":"Standard Engagement or until a player \nachieves total control.","box":[0.11905,0.69364,0.49102,0.725]},{"text":"Engagement Special Rules","box":[0.11905,0.7421,0.339,0.75636]},{"text":"The game ends when one player controls both \nobjectives.","box":[0.11905,0.77346,0.49102,0.80482]},{"text":"Victory Conditions","box":[0.51355,0.58246,0.67643,0.59671]},{"text":"If a player controls both objectives at the end \nof any round, that player wins immediately.","box":[0.51355,0.61382,0.88552,0.64518]},{"text":"If neither player achieves total control by the \nend, the engagement is a draw.","box":[0.51355,0.66228,0.88552,0.69364]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":100,"number":97,"label":"97","title":"ENGAGEMENT: PUSH THE LINE","width":2000,"height":2829,"blocks":[{"text":"ENGAGEMENT: PUSH THE LINE","box":[0.29379,0.08196,0.70619,0.11047]},{"text":"The frontline is no longer a boundary, it’s an objective. Advance into enemy territory and secure \nground. Every position taken must be defended, every gain paid for in oil and iron. Fall back, \nand the enemy reclaims everything.","box":[0.11905,0.11678,0.88554,0.16524]},{"text":"Battlefield and Deployment","box":[0.11905,0.17822,0.35141,0.19247]},{"text":"Use Deployment 1 or 2.","box":[0.11905,0.20957,0.3088,0.22383]},{"text":"Engagement Length","box":[0.11905,0.24093,0.28775,0.25519]},{"text":"Standard Engagement.","box":[0.11905,0.27229,0.30074,0.28654]},{"text":"Engagement Special Rules","box":[0.11905,0.30365,0.339,0.3179]},{"text":"At the start of each round, players earn 2 VP \nfor each of their Rigs inside the opponent’s \nterritory.","box":[0.11905,0.33501,0.49102,0.38347]},{"text":"Victory Conditions","box":[0.51355,0.17822,0.67643,0.19247]},{"text":"Players total the VP earned from destroying \nenemy Rigs. The player with the highest score \nat the end of the engagement wins.","box":[0.51355,0.20957,0.88552,0.25804]},{"text":"Players also receive VP for each enemy Rig \nthey have destroyed based on the Rig’s weight \nclass:","box":[0.51355,0.27514,0.88552,0.3236]},{"text":"ENGAGEMENT: SUPPLY AIRDROP","box":[0.27858,0.48937,0.72138,0.51788]},{"text":"In the Smoglands, logistics win wars. Crates slam into the dirt under fire, packed with fuel, \nmunitions, and machine parts. Resources are precious here, and you must take everything you \ncan.","box":[0.11905,0.52306,0.88554,0.57152]},{"text":"Battlefield and Deployment","box":[0.11905,0.58141,0.35141,0.59566]},{"text":"Standard Engagement. Divide the battlefield \nequally into 4 quadrants, numbering each.","box":[0.11905,0.61276,0.49102,0.64412]},{"text":"Engagement Length","box":[0.11905,0.66123,0.28775,0.67548]},{"text":"Five rounds.","box":[0.11905,0.69258,0.21879,0.70684]},{"text":"Engagement Special Rules","box":[0.11905,0.72394,0.339,0.7382]},{"text":"At the start of the second round, roll a D6.","box":[0.11905,0.7553,0.45862,0.76955]},{"text":"1 \nto \n4: \nplace \nthe \nobjective \nin \nthe \ncorresponding table quarter.","box":[0.11905,0.78666,0.49101,0.81802]},{"text":"5 to 6: place the objective in the centre of the \nbattlefield.","box":[0.11905,0.83512,0.49101,0.86648]},{"text":"The player controlling the objective at the end \nof round five wins.","box":[0.51355,0.58153,0.88553,0.61289]},{"text":"Victory Conditions","box":[0.51355,0.63,0.67643,0.64425]},{"text":"The player controlling the objective at the end \nof the engagement wins.","box":[0.51355,0.66135,0.88553,0.69271]},{"text":"Weight Class\nVictory Points\nLight\n2\nMedium\n3\nHeavy\n4\nColossal\n5","box":[0.534,0.3462,0.82335,0.42402]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":101,"number":98,"label":"98","title":"ENGAGEMENT: SALVAGE HEIST","width":2000,"height":2829,"blocks":[{"text":"ENGAGEMENT: SALVAGE HEIST","box":[0.28915,0.08196,0.71084,0.11047]},{"text":"Battlefields are goldmines for those bold enough to strip them bare. Wrecked Rigs are of high \nsalvage value! Grab what you can before the enemy realises what you’re stealing… and why.","box":[0.11905,0.11678,0.88553,0.14814]},{"text":"Battlefield and Deployment","box":[0.11905,0.17822,0.35141,0.19247]},{"text":"Standard Engagement. Each player then take \nturns placing three objectives each.","box":[0.11905,0.20957,0.49102,0.24093]},{"text":"Engagement Length","box":[0.11905,0.25804,0.28775,0.27229]},{"text":"Standard Engagement.","box":[0.11905,0.2894,0.30074,0.30365]},{"text":"Engagement Special Rules","box":[0.11905,0.32075,0.339,0.33501]},{"text":"Use \nSalvage \nObjectives. \nEach \nSalvage \nObjective is worth 2 VP.","box":[0.11905,0.35211,0.49102,0.38347]},{"text":"Victory Conditions","box":[0.51355,0.17822,0.67643,0.19247]},{"text":"Players total the VP earned from objectives. \nThe player with the highest score at the end of \nthe engagement wins.","box":[0.51355,0.20957,0.88552,0.25804]},{"text":"ENGAGEMENT: SABOTAGE","box":[0.3252,0.48937,0.67478,0.51788]},{"text":"Not every victory comes from a kill. From ruptured pipelines to disabled generators, small acts \nof destruction can cripple entire offensives. Strike fast, disappear faster.","box":[0.11905,0.52306,0.88552,0.55442]},{"text":"Battlefield and Deployment","box":[0.11905,0.58141,0.35141,0.59566]},{"text":"Standard Engagement. Each player then take \nturns placing three objectives each under \ntheir control.","box":[0.11905,0.61276,0.49102,0.66123]},{"text":"Engagement Length","box":[0.11905,0.67833,0.28775,0.69258]},{"text":"Four rounds.","box":[0.11905,0.70969,0.22365,0.72394]},{"text":"Engagement Special Rules","box":[0.11905,0.74105,0.339,0.7553]},{"text":"Use Valuable Asset objectives with the \nfollowing profile.","box":[0.11905,0.7724,0.49102,0.80376]},{"text":"Structure Points\nArmour","box":[0.15366,0.83006,0.42334,0.84194]},{"text":"8\n5+","box":[0.20646,0.85312,0.40439,0.86619]},{"text":"Victory Conditions","box":[0.51355,0.58141,0.67643,0.59566]},{"text":"The first player to destroy each of the other \nplayer’s objectives wins.","box":[0.51355,0.61276,0.88552,0.64412]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":102,"number":99,"label":"99","title":"SPECIAL ENGAGEMENT: AMBUSH","width":2000,"height":2829,"blocks":[{"text":"SPECIAL ENGAGEMENT: AMBUSH","box":[0.27442,0.08196,0.72553,0.11047]},{"text":"The first warning is muzzle flash through the smog. Engines roar to life as fire rains down from \nconcealed positions. Strike the enemy while you have the advantage.","box":[0.11905,0.11678,0.88553,0.14814]},{"text":"Battlefield and Deployment","box":[0.11905,0.174,0.35141,0.18825]},{"text":"Standard Engagement. Use Deployment 9.","box":[0.11905,0.20536,0.45872,0.21961]},{"text":"Engagement Length","box":[0.11905,0.23672,0.28775,0.25097]},{"text":"Standard Engagement.","box":[0.11905,0.26807,0.30074,0.28233]},{"text":"Engagement Special Rules","box":[0.11905,0.29943,0.339,0.31368]},{"text":"This Engagement is for two players. One \nplayer is the Ambusher, the other is the Target.","box":[0.11905,0.33079,0.49102,0.36215]},{"text":"The Target deploys their Squadron first. After \nthe Target has deployed all Rigs, the \nAmbusher secretly notes the position of each \nof their Rigs using markers, tokens, or a \nsketch, anywhere 4” from the battlefield edge.","box":[0.11905,0.37925,0.49102,0.46192]},{"text":"During the first round, all Target Rigs count as \nhaving Preparation: Brace for Incoming Fire \nactive against the first attack made against \nthem.","box":[0.51355,0.17413,0.88556,0.23969]},{"text":"Victory Conditions","box":[0.51355,0.2568,0.67643,0.27105]},{"text":"Players receive VP for each enemy Rig they \nhave destroyed based on the Rig’s weight class, \nthe player with the most wins:","box":[0.51355,0.28816,0.88552,0.33662]},{"text":"SPECIAL ENGAGEMENT: HOLD THE LINE","box":[0.2335,0.48937,0.76649,0.51788]},{"text":"Retreat is not authorized. Behind you lies infrastructure, civilians, or something far more \nvaluable. The enemy will come in waves, testing iron and resolve. The line must hold, no matter \nthe cost.","box":[0.11905,0.52306,0.88553,0.57152]},{"text":"Battlefield and Deployment","box":[0.11905,0.58141,0.35141,0.59566]},{"text":"Standard Engagement. Use deployment 5 or 9.","box":[0.11905,0.61276,0.48644,0.62702]},{"text":"Engagement Length","box":[0.11905,0.64412,0.28775,0.65838]},{"text":"Four rounds.","box":[0.11905,0.67548,0.22365,0.68973]},{"text":"Engagement Special Rules","box":[0.11905,0.70684,0.339,0.72109]},{"text":"This Engagement is for two players or two \nteams of players. One player / team will be the \nAttacker and the other will be the Defender. \nThe Defender cannot leave their Deployment \nZone.","box":[0.11905,0.7382,0.49102,0.82087]},{"text":"Victory Conditions","box":[0.51355,0.58141,0.67643,0.59566]},{"text":"If the Defender has 50% of their Squadron \n(rounded up) still operational, they win the \nEngagement. Otherwise, the Attacker wins \nthe Engagement.","box":[0.51355,0.61276,0.86604,0.67833]},{"text":"Weight Class\nVictory Points\nLight\n2\nMedium\n3\nHeavy\n4\nColossal\n5","box":[0.534,0.35562,0.82335,0.43343]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":103,"number":100,"label":"100","title":"SPECIAL ENGAGEMENT: SIEGE","width":2000,"height":2829,"blocks":[{"text":"SPECIAL ENGAGEMENT: SIEGE","box":[0.29427,0.48937,0.70573,0.51788]},{"text":"The enemy’s power is concentrated behind reinforced walls and layered defences. Command \nhubs, refineries, and foundries lie within. Break through the outer ring and collapse the city \nfrom the inside.","box":[0.11905,0.52419,0.88553,0.57265]},{"text":"Battlefield and Deployment","box":[0.11905,0.58141,0.35141,0.59566]},{"text":"Standard Engagement. Each player then takes \nturns placing three valuable asset objectives, \nfor a total of six - one at a time.","box":[0.11905,0.61276,0.49102,0.66123]},{"text":"Engagement Length","box":[0.11905,0.67833,0.28775,0.69258]},{"text":"Standard Engagement.","box":[0.11905,0.70969,0.30074,0.72394]},{"text":"Engagement Special Rules","box":[0.11905,0.74105,0.339,0.7553]},{"text":"This Engagement is for two players. One \nplayer will be the Attacker and the other will \nbe the Defender. Objectives have the \nfollowing profile.","box":[0.11905,0.7724,0.49102,0.83797]},{"text":"Victory Conditions","box":[0.51355,0.58141,0.67643,0.59566]},{"text":"At the end of the Engagement, the Defender \nscores 2 victory points for every objective still \non the battlefield. The Attacker scores 1 \nvictory point for each objective they have \ndestroyed. The Attacker also receives 1 \nvictory point for each enemy Rig they have \ndestroyed.","box":[0.51355,0.61276,0.88485,0.72964]},{"text":"The player with the most victory points wins. \nIf players have the same amount of victory \npoints, the Defender wins.","box":[0.51355,0.74675,0.88054,0.79521]},{"text":"SPECIAL ENGAGEMENT: BREAKTHROUGH","box":[0.22537,0.08196,0.77458,0.11047]},{"text":"The enemy line is strong, but not unbreakable. Relentless pressure and raw momentum are your \nweapons. Punch through, split their forces, and turn a stalemate into a rout.","box":[0.11905,0.11566,0.88551,0.14701]},{"text":"Battlefield and Deployment","box":[0.11905,0.174,0.35141,0.18825]},{"text":"Standard Engagement. Use Deployment 5.","box":[0.11905,0.20536,0.45872,0.21961]},{"text":"Engagement Length","box":[0.11905,0.23672,0.28775,0.25097]},{"text":"Standard Engagement.","box":[0.11905,0.26807,0.30074,0.28233]},{"text":"Engagement Special Rules","box":[0.11905,0.29943,0.339,0.31368]},{"text":"This Engagement is for two players or teams of \nplayers. One player /team will be the Attacker \nand the other will be the Defender. The \nAttacker is considered “Player 1” on the \nDeployment map.","box":[0.11905,0.33079,0.49102,0.41346]},{"text":"Victory Conditions","box":[0.51355,0.174,0.67643,0.18825]},{"text":"The Attacker must move at least 50% of their \nSquadron (rounded up) to the opposite side \nof the battlefield, exiting the other side to \nwin. Otherwise, the Defender wins.","box":[0.51355,0.20536,0.87723,0.27092]},{"text":"Structure Points\nArmour","box":[0.15366,0.85935,0.42334,0.87123]},{"text":"8\n5+","box":[0.20646,0.88242,0.40439,0.89548]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":104,"number":101,"label":"101","title":"Campaign","width":2000,"height":2829,"blocks":[{"text":"Starting a Campaign","box":[0.51355,0.08396,0.6875,0.09821]},{"text":"Each player commands a Squadron composed \nof Rigs from a single faction. Before \nembarking on a campaign, players must \nassemble their Squadron with the following \nrestrictions:","box":[0.51355,0.11532,0.88552,0.19799]},{"text":"• \nStart with a Skirmish sized Squadron.","box":[0.51355,0.21509,0.84572,0.22935]},{"text":"• \nEach player starts with 15 Iron to \ndistribute across their starting Squadron.","box":[0.51355,0.24645,0.88552,0.27781]},{"text":"• \nIronclads may only start as Rookie or \nExperienced.","box":[0.51355,0.29492,0.88553,0.32627]},{"text":"• \nEach player maintains a Squadron Roster, \ntracking the status of their forces over \ntime.","box":[0.51355,0.34338,0.88552,0.39184]},{"text":"• \nPlayers \nearn \nsalvage \nand \nIronclad \nexperience through each engagement. \nThese rewards are used to repair, improve \nand expand the Squadron during the \ncampaign.","box":[0.51355,0.40894,0.88553,0.49162]},{"text":"Campaign Structure","box":[0.51355,0.50872,0.68534,0.52297]},{"text":"A campaign is played by linking together the \nindividual Engagements that the group \nchooses, followed by and Aftermath Phase. \nPlayers may play against any other participant \nin the campaign.","box":[0.51355,0.54008,0.88553,0.62275]},{"text":"Campaign","box":[0.11905,0.08141,0.30539,0.11704]},{"text":"In the shadow of smoldering cities and the \nrusting hulks of a world that once thrived, the \nSmoglands \nhave \nbecome \nthe \nultimate \nbattleground. Oil seeps through cracked earth \nlike blood, and iron glimmers beneath the ash-\nstreaked soil, a promise of power for those bold \nenough to claim it.","box":[0.11905,0.13012,0.49106,0.247]},{"text":"In this brutal era of decay, corporations rise \nfrom the ruins, each with a singular goal: \ndominance. \nTitans \nof \nindustry \ndeploy \nmonstrous Rigs to crush resistance, while others \nfight to wrestle control from their grasp.","box":[0.11905,0.26411,0.49106,0.34678]},{"text":"Yet the road to supremacy is treacherous. The \nland is scarred with toxic storms and the \nremnants of countless failed revolutions. \nMercenaries, drawn by the clink of coin sell \ntheir firepower to the highest bidder. Every \nskirmish leaves wreckage to scavenge, every \nvictory comes at a cost, and every defeat is a \nwarning whispered on the winds of the wastes.","box":[0.11905,0.36388,0.49107,0.49787]},{"text":"Now, the struggle begins. The roads of this \nbroken world await your mark. Will your \nchosen corporation carve its name into history \nas conquerors of the Smoglands, or be \nswallowed by the ever-turning gears of war?","box":[0.11905,0.51497,0.49107,0.59764]},{"text":"Campaigns are made up of a series of linked \ngames in which players control an evolving \nSquadron of Rigs. In a Campaign, each player \nbuilds a starting Squadron, plays a series of \nengagements and advances their Squadron \nthrough repairs, upgrades and Ironclad \nprogression.","box":[0.11905,0.61475,0.49102,0.73163]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":105,"number":102,"label":"102","title":"Winning the Campaign and Fielding Your Squadron","width":2000,"height":2829,"blocks":[{"text":"Winning the Campaign","box":[0.11905,0.08383,0.31729,0.09809]},{"text":"A campaign is played as a season of a fixed \nnumber of Engagements agreed by the group \nsix is the recommended default; eight to ten \nfor a longer war. Players track Renown \nalongside Salvage on their Roster. Renown is \nthe measure of a Squadron's dominance over \nthe season.","box":[0.11905,0.11519,0.49102,0.23207]},{"text":"After each Engagement, each player earns \nRenown:","box":[0.11905,0.24918,0.49102,0.28053]},{"text":"• \n3 Renown for winning an Engagement (1 \nif it is a draw)","box":[0.11905,0.29764,0.49102,0.329]},{"text":"• \n1 Renown for each enemy Rig destroyed","box":[0.11905,0.3461,0.47253,0.36035]},{"text":"• \n1 Renown for each Objective captured","box":[0.11905,0.37746,0.45636,0.39171]},{"text":"When the season's final Engagement is \ncomplete, the player with the most Renown is \nthe victor of the campaign. If tied, the player \nwho destroyed the most enemy Rigs across \nthe season wins.","box":[0.11905,0.40882,0.49102,0.49149]},{"text":"Fielding Your Squadron","box":[0.51355,0.08383,0.71517,0.09809]},{"text":"A player's Squadron Roster may grow far \nbeyond the size of any single battle. For each \nEngagement, both players agree a Formation \ntype (Skirmish, Operation, or Warfront) and \neach fields a Squadron Type from that \nFormation, drawn from the Rigs on their \nRoster. Rigs not chosen are held in reserve and \ntake no part in that battle. Players may field \ndifferent \nSquadron \nFormations \nof \nthe \nFormation Type.","box":[0.51355,0.11519,0.88553,0.28338]},{"text":"Roster depth therefore protects players \nagainst losses rather than letting them \noverwhelm an opponent: a larger Roster \nmeans more choice and replacements ready \nfor the next contract, not more Rigs on the \ntable.","box":[0.51355,0.30049,0.88552,0.40026]},{"text":"If a player cannot field the agreed Formation, \nbecause losses have reduced their Roster \nbelow its requirements, they field as many \nRigs as they can and immediately receive \nUnderdog Reinforcement to rebuild before \nthe next Engagement.","box":[0.51355,0.41737,0.88553,0.51714]},{"text":"Engagements","box":[0.51355,0.53425,0.62577,0.5485]},{"text":"Before each Engagement:","box":[0.51355,0.56561,0.71657,0.57986]},{"text":"1. Select an Engagement or roll randomly for \none. (p67-72)","box":[0.51355,0.59696,0.88552,0.62832]},{"text":"2. Select a Deployment or roll randomly for \none. (p65-66) Some Engagements require a \nspecific Deployment.","box":[0.51355,0.64543,0.88556,0.69389]},{"text":"3. Select a Battlefield. The Battlefield is a \nsuggestion for terrain type, and has effects for \naftermath sequence, awarding players (or \nsometimes damaging Rigs!).","box":[0.51355,0.71099,0.88553,0.77656]},{"text":"4. Play the Engagement normally.","box":[0.51355,0.79366,0.78244,0.80792]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[{"page":67,"end":72,"label":"p67-72","box":[0.55897,0.61407,0.61396,0.62832]},{"page":65,"end":66,"label":"p65-66","box":[0.56515,0.66253,0.62014,0.67678]}]},{"index":106,"number":103,"label":"103","title":"Salvage and Experience","width":2000,"height":2829,"blocks":[{"text":"Salvage and Experience","box":[0.11905,0.08383,0.31579,0.09809]},{"text":"Throughout a campaign, players earn Salvage \nand Ironclad Experience based on their \nperformance in engagements. Salvage allows \nSquadrons to repair damaged Rigs and \npurchase new equipment and Rigs. Salvage \nrepresents the material gains recovered from \nthe battlefield, while Experience reflects the \nknowledge and skill gained by Ironclads \nthrough surviving repeated combat.","box":[0.11905,0.11519,0.49102,0.26628]},{"text":"Both Salvage and Experience are gained after \neach engagement during the Aftermath Phase. \nKeep track of all Salvage and Experience on \nthe Squadron Roster.","box":[0.11905,0.28338,0.49102,0.34895]},{"text":"Certain Engagements may have special rules \nthat reward various amounts of salvage or \nexperience.","box":[0.11905,0.57116,0.49102,0.61962]},{"text":"Event\nSalvage\nWinning an Engagement\nD6\nLosing an Engagement\nD3\nDestroyed a light Rig\n1\nDestroyed a medium Rig\n1\nDestroyed a heavy Rig\n2\nDestroyed a colossal Rig\n3\nCaptured an Objective\n1\nCapture a Salvage Objective\n3","box":[0.12073,0.36456,0.48179,0.54852]},{"text":"In the event of an Engagement draw, both \nplayers receive the winning rewards.","box":[0.51355,0.08396,0.88552,0.11532]},{"text":"Earning Salvage","box":[0.51355,0.13242,0.64899,0.14668]},{"text":"Objectives: \nMany \nengagements \nfeature \nobjectives that can be captured. Each objective \ncaptured during the game awards 1 Salvage \nper Victory Point. Salvage Objectives award 3 \nSalvage.","box":[0.51355,0.16378,0.88553,0.24645]},{"text":"Destroying Rigs: When a player destroys an \nenemy Rig, they earn Salvage based on the \nRig’s weight class. Heavier Rigs yield more \nrecoverable parts.","box":[0.51355,0.26356,0.88553,0.32912]},{"text":"Battlefield Salvage: At the end of the \nengagement, \nplayers \nmay \nsalvage \nthe \nbattlefield. This represents crews sweeping the \narea for usable parts.","box":[0.51355,0.34623,0.88552,0.41179]},{"text":"Battlefield Bonuses: Certain battlefields \nprovide additional Salvage based on the \nenvironment. For example, winning a battle in \na Iron Mine or Rig Graveyard may award \nextra Salvage due to the abundance of scrap. \nEach battlefield lists its specific bonuses in the \ntable below.","box":[0.51355,0.4289,0.88553,0.54578]},{"text":"Roll\nBattlefield\nLoss Aftermath Effect\nVictory Aftermath Effect\n1\nWasteland\n+1 Salvage\n+3 Salvage\n2\nOil Field\n1 Free Repair\n3 Free Repairs\n3\nIron Mine\n+2 Salvage\n+5 Salvage\n4\nSalvage Yard\n1 Free Equipment, +1 Salvage\n2 Free Equipment, +2 Salvage\n5\nSettlement\n+1 XP for each Ironclad\n+2 XP for each Ironclad\n6\nRig Graveyard\n1 Light Rig, +1 Salvage\n1 Medium Rig, +2 Salvage\n7\nRig Hangar\n1 Heavy Rig, +1 Salvage\n1 Heavy Rig, +3 Salvage","box":[0.12119,0.63266,0.85263,0.79019]},{"text":"8\nIndustrial \nComplex\n1 Free Weapon, +1 Salvage\n2 Free Weapons, +2 Salvage","box":[0.1339,0.79167,0.83719,0.82078]},{"text":"9\nCity Centre\n+2 XP for 1 Ironclad\n+5 XP for 1 Ironclad\n10\nFuel Depot\n2 Free Repairs, +1 Salvage\n4 Free Repairs, +2 Salvage\n11\nToxic Flats\n2 damage to 1 Rig\n2 damage to 2 Rigs\n12\nStorm Belt\n3 damage to 1 Rig\n3 damage to 2 Rigs","box":[0.12906,0.82289,0.82575,0.89915]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":107,"number":104,"label":"104","title":"Ironclad Experience and Aftermath","width":2000,"height":2829,"blocks":[{"text":"Earning Ironclad Experience","box":[0.11905,0.08383,0.36101,0.09809]},{"text":"Ironclads gain Experience by participating in \nengagements and surviving the trials of \ncombat. Experience allows Ironclads to level \nup, granting them re-rolls and other bonuses.","box":[0.11905,0.11519,0.49102,0.18076]},{"text":"Survival: An Ironclad gains Experience for \nsurviving an engagement.","box":[0.11905,0.19786,0.49102,0.22922]},{"text":"Objectives and Combat: Ironclads earn \nExperience for capturing objectives and for \ndestroying enemy Rigs. The amount gained is \nlisted in the mission or in the Experience \ntable.","box":[0.11905,0.24632,0.49102,0.329]},{"text":"Event\nXP\nIronclad survives the Engagement\n1\nDestroyed a light Rig\n1\nDestroyed a medium Rig\n2\nDestroyed a heavy Rig\n3\nDestroyed a colossal Rig\n4\nCaptured or secured an objective\n1","box":[0.12073,0.34461,0.46383,0.48616]},{"text":"Using Your Rewards","box":[0.51355,0.08383,0.68373,0.09809]},{"text":"Salvage and Experience are spent or applied \nduring the Aftermath Phase. Players decide \nwhether to repair damaged Rigs, purchase \nnew equipment, or expand their Squadron.","box":[0.51355,0.11519,0.88552,0.18076]},{"text":"Growing a Squadron requires careful resource \nmanagement, balancing risk, reward and \nlong-term strategy as the campaign unfolds.","box":[0.51355,0.19786,0.88552,0.24632]},{"text":"Aftermath Phase","box":[0.51355,0.26343,0.6546,0.27768]},{"text":"After each engagement, players complete the \nAftermath Phase, which includes:","box":[0.51355,0.29479,0.88552,0.32614]},{"text":"1. Check if destroyed Rigs are lost","box":[0.51355,0.34325,0.79575,0.3575]},{"text":"2. Check for damage and repair Rigs","box":[0.51355,0.37461,0.81673,0.38886]},{"text":"3. Check if Ironclads are lost","box":[0.51355,0.40597,0.75315,0.42022]},{"text":"4. Ironclad Experience","box":[0.51355,0.43732,0.70616,0.45158]},{"text":"5. Salvage the Battlefield","box":[0.51355,0.46868,0.71925,0.48293]},{"text":"6. Underdog Reinforcements","box":[0.51355,0.50004,0.75696,0.51429]},{"text":"7. Visit the Iron Market","box":[0.51355,0.5314,0.71336,0.54565]},{"text":"Players repeat this process after every \nEngagement.","box":[0.51355,0.56276,0.88552,0.59411]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":108,"number":105,"label":"105","title":"Rig Recovery and Permanent Damage","width":2000,"height":2829,"blocks":[{"text":"1. Check if destroyed Rigs are lost","box":[0.11905,0.08383,0.40213,0.09809]},{"text":"Roll a D12 for each Rig destroyed during the \nEngagement.","box":[0.11905,0.11519,0.49101,0.14655]},{"text":"• \nA Rig that did not explode is recovered on \na 2+","box":[0.11905,0.16365,0.49102,0.19501]},{"text":"• \nA Rig that exploded is recovered on a 7+","box":[0.11905,0.21212,0.47138,0.22637]},{"text":"On a failure, the Rig is permanently lost and \nremoved from the Roster. A recovered Rig \nreturns with the components that were \nDisabled or Catastrophically Damaged at the \nmoment \nof \nits \ndestruction; \nall \nother \ncomponents retain the Structure Points they \nhad \nwhen \nthe \nRig \nwas \ndestroyed. \nCatastrophically \nDamaged \nor \nDisabled \ncomponents are repaired during step 2.","box":[0.11905,0.24347,0.49102,0.39456]},{"text":"2. Check for damage and repair Rigs","box":[0.51355,0.08383,0.81855,0.09809]},{"text":"Rigs carry over any damage sustained during \nan Engagement and may be repaired between \nEngagements.","box":[0.51355,0.11519,0.88552,0.16365]},{"text":"• \nEach Rig may repair any 3 Structure \nPoints for free. After which, repairs can be \nmade at the cost of 1 Salvage for every 3 \nStructure Points repaired (1 Salvage \nminimum).","box":[0.51355,0.18076,0.88553,0.26343]},{"text":"• \nRestoring a Disabled component to \nCatastrophically Damaged costs 1 Salvage.","box":[0.51355,0.28053,0.88552,0.31189]},{"text":"• \nRestoring a Catastrophically Damaged \ncomponent to full Structure Points costs 1 \nSalvage.","box":[0.51355,0.329,0.88552,0.37746]},{"text":"• \nWhenever a Catastrophically Damaged or \nDisabled component is repaired, it gains \none permanent negative trait, rolled on \nthe Permanent Damage table for that \ncomponent (roll a D6). If the rolled trait is \nalready present, roll again.","box":[0.51355,0.39456,0.88553,0.49434]},{"text":"Roll\nDamage Trait\nHull Effects","box":[0.134,0.51712,0.45246,0.52899]},{"text":"1-2\nLoad Frame Buckled\n-1 maximum Iron. If over capacity, remove equipment as necessary","box":[0.13757,0.53817,0.81876,0.55005]},{"text":"3-4\nLayered Hull Breach\n-2 to hull armour rolls","box":[0.13757,0.56531,0.51957,0.57719]},{"text":"5-6\nStructural Integrity \nCompromised\nAll components have -1 maximum Structure Points","box":[0.13757,0.58574,0.71575,0.61]},{"text":"Roll\nDamage Trait\nArms Effects","box":[0.134,0.6134,0.46005,0.62528]},{"text":"1-2\nDisrupted Targeting Optics -1 ACC when attacking with this weapon","box":[0.13757,0.63393,0.64763,0.64634]},{"text":"3-4\nHydraulic Pressure Loss\nThis weapon has -1 STR (to a minimum of 1)","box":[0.13757,0.66108,0.67703,0.67348]},{"text":"5-6\nIgnition Routing Fault\nBackfires on a roll of 1 when firing, dealing 1 damage to the arms, once per \nattack action\nRoll\nDamage Trait\nLegs Effects","box":[0.134,0.68203,0.88178,0.72157]},{"text":"1-2\nClutch Degradation\nSpeed is reduced by 1” (to a minimum of 1”)","box":[0.13757,0.73022,0.67326,0.74262]},{"text":"3-4\nRotation Joint Seizure\nPivot is reduced by half","box":[0.13757,0.75736,0.53005,0.76977]},{"text":"5-6\nReverse Drive Cutout\nCannot backpedal or sidestep","box":[0.13757,0.78451,0.56782,0.79691]},{"text":"Roll\nDamage Trait\nEngine Effects","box":[0.134,0.80598,0.4703,0.81786]},{"text":"1-2\nRadiator Bypass Failure\nAdd +1 to all Heat Threshold rolls","box":[0.13757,0.82651,0.60174,0.83891]},{"text":"3-4\nHeat Exchanger Buckled\nHeat Threshold moves one space to the left on the Heat Track","box":[0.13757,0.85365,0.7849,0.86606]},{"text":"5-6\nExhaust Routing Collapse\nEngine Exhaust is reduced by 1","box":[0.13757,0.8808,0.58276,0.8932]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":109,"number":106,"label":"106","title":"Salvage and Reinforcement","width":2000,"height":2829,"blocks":[{"text":"Salvage Table\n3. Check if Ironclads are lost","box":[0.11905,0.08383,0.62644,0.09809]},{"text":"Even if a Rig is destroyed, its Ironclad may \nsurvive. Roll a D12 for each Ironclad whose \nRig was destroyed.","box":[0.11905,0.11519,0.49102,0.16365]},{"text":"• \nIf the Rig did not explode, the Ironclad \nsurvives on a 2+","box":[0.11905,0.18076,0.49102,0.21212]},{"text":"• \nIf the Rig exploded, the Ironclad survives \non a 5+","box":[0.11905,0.22922,0.49102,0.26058]},{"text":"Otherwise the Ironclad is lost and must be","box":[0.11905,0.27768,0.49102,0.29194]},{"text":"replaced with a Rookie. A surviving \nIronclad whose Rig was lost may be \nreassigned to a newly acquired Rig, \nretaining their Experience, Level, and Re-\nRolls.","box":[0.14928,0.29479,0.49102,0.37746]},{"text":"4. Ironclad Experience","box":[0.11905,0.39456,0.30805,0.40882]},{"text":"Experience is gained by surviving, capturing \nobjectives and destroying enemy rigs.","box":[0.11905,0.42592,0.49102,0.45728]},{"text":"At the end of an Engagement, apply \nexperience gained by Ironclads, level them up \nand assign the relevant level perks.","box":[0.11905,0.47438,0.49102,0.52285]},{"text":"When an Ironclad levels up, they acquire a \nlevel perk. Level perks offer re-rolls or \npromotions. If an Ironclad can be promoted, \nthey must take the promotion.","box":[0.11905,0.53995,0.49102,0.60552]},{"text":"Re-rolls can each be used once per game. The \nnumber of re-rolls resets each new game.","box":[0.11905,0.62262,0.49102,0.65398]},{"text":"Level XP\nLevel Perk","box":[0.12126,0.67202,0.31249,0.68628]},{"text":"1\n0\nStarting Ironclad","box":[0.13808,0.69659,0.35361,0.70965]},{"text":"2\n3\n+1 Re-roll","box":[0.13808,0.71888,0.30383,0.73195]},{"text":"3\n6\n+1 Re-roll","box":[0.13808,0.7406,0.30383,0.75424]},{"text":"4\n10\nIronclad Promotion OR +1 Re-roll","box":[0.1379,0.7629,0.48283,0.77654]},{"text":"5\n15\n+1 Re-roll","box":[0.1379,0.78519,0.30383,0.79883]},{"text":"6\n20\n+1 Re-roll","box":[0.1379,0.80749,0.30383,0.82113]},{"text":"7\n25\nIronclad Promotion OR +1 Re-roll","box":[0.1379,0.82978,0.48283,0.84343]},{"text":"8\n30\n+1 Re-roll","box":[0.1379,0.85208,0.30383,0.86572]},{"text":"9\n35\n+1 Re-roll","box":[0.1379,0.87437,0.30383,0.88802]},{"text":"10\n40\nIronclad Promotion OR +1 Re-roll","box":[0.13328,0.89667,0.48283,0.91031]},{"text":"5. Salvage the Battlefield","box":[0.51355,0.32483,0.71854,0.33909]},{"text":"After a battle, a Squadron’s surviving Rigs \nscour the wreckage for parts and abandoned \nmachines. For each surviving Rig, roll a D12 \nand consult the Salvage table and gain that \nreward.","box":[0.51355,0.35619,0.88552,0.43886]},{"text":"Add +1 to the roll if this Rig landed the final \nblow \non \nan \nenemy \nRig \nduring \nthe \nEngagement.","box":[0.51355,0.45597,0.88552,0.50443]},{"text":"When acquiring a destroyed Rig, its stats \nremain the same as when it was destroyed. It \nmay be repaired or scrapped for salvage. It \nmust have been destroyed during the previous \nEngagement. If no Rigs were destroyed, \nnothing is acquired.","box":[0.51355,0.52153,0.88553,0.62131]},{"text":"6. Underdog Reinforcement","box":[0.51355,0.63841,0.74759,0.65267]},{"text":"Compare the total Salvage value of each \nplayer's Roster (sum the recruit cost of every \nRig, plus banked Salvage). The player with the \nlower total receives bonus Salvage equal to D3 \nat the end of each Engagement. If a player was \nunable to field the agreed Formation, they \ninstead receive an additional D6 Salvage and \nmay rebuild before the next Engagement. This \nreinforcement \nrepresents \nsympathetic \nbackers, desperate scavenging, and contracts \nof opportunity flowing to the underdog.","box":[0.51355,0.66977,0.88553,0.85507]},{"text":"Result\nReward","box":[0.51667,0.1075,0.75768,0.12182]},{"text":"1\nNothing of value","box":[0.53736,0.13259,0.7873,0.14565]},{"text":"2\n3 Salvage","box":[0.53736,0.15882,0.75924,0.17189]},{"text":"3\n5 Salvage","box":[0.53736,0.18448,0.76167,0.19813]},{"text":"4-6\nRoll a D12 on Equipment Table A","box":[0.52948,0.21072,0.85143,0.22378]},{"text":"7-9\nRoll a D12 on Equipment Table B","box":[0.52948,0.23695,0.85144,0.25002]},{"text":"10-12\nRoll a D12 on Equipment Table C","box":[0.52024,0.26319,0.85144,0.27625]},{"text":"13\nAny destroyed Rig","box":[0.53256,0.28942,0.79529,0.30249]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":110,"number":107,"label":"107","title":"Iron Market and Recruiting","width":2000,"height":2829,"blocks":[{"text":"Assigning an Ironclad","box":[0.51355,0.08383,0.69854,0.09809]},{"text":"A new Rig is assigned an Ironclad from the \nplayer’s roster.","box":[0.51355,0.11519,0.88553,0.14655]},{"text":"If a Squadron has no unassigned Ironclads, \nthey may recruit a new one or transfer an \nexisting Ironclad from another Rig. Ironclads \nretain their Experience, levels and re-rolls \nwhen reassigned.","box":[0.51355,0.16365,0.88552,0.24632]},{"text":"New Ironclads are recruited for their Iron cost \nusing Salvage. Only Rookie or Experienced \nIronclads can be recruited.","box":[0.51355,0.26343,0.88552,0.31189]},{"text":"Repair Status of Newly Recruited Rigs","box":[0.51355,0.329,0.83288,0.34325]},{"text":"All newly purchased Rigs begin the campaign \nfully operational with:","box":[0.51355,0.36035,0.88553,0.39171]},{"text":"• All components at full structure points","box":[0.51355,0.40882,0.83756,0.42307]},{"text":"• No permanent negative traits","box":[0.51355,0.44017,0.76057,0.45443]},{"text":"• No catastrophic or destroyed components","box":[0.51355,0.47153,0.86213,0.48579]},{"text":"These Rigs are considered fresh deployments \nbrought in from storage, transport or \ncorporate supply.","box":[0.51355,0.50289,0.88552,0.55135]},{"text":"Once a Rig is purchased, equipped and \nassigned an Ironclad, it becomes part of the \nplayer’s active Squadron. It may be deployed \nin any future engagement with its Squadron.","box":[0.51355,0.56846,0.88553,0.63402]},{"text":"Second-Hand Rigs","box":[0.51355,0.65113,0.66982,0.66538]},{"text":"Not every Rig that enters a Squadron is fresh \nfrom a factory floor. Across the Smoglands, \ndamaged Rigs can be repaired, restored or \nwelded together to be made serviceable. These \nbattered Rigs are known as second-hand Rigs, \nand they provide a cheaper alternative for \nSquadrons operating with limited Salvage, but \nthey always come with permanent drawbacks.","box":[0.51355,0.68249,0.88552,0.81647]},{"text":"Second-Hand Rigs can be purchased at 50% \nthe Salvage cost. When second-hand Rig is \npurchased, it automatically starts with \npermanent damage and lost structure points.","box":[0.51355,0.83357,0.88552,0.89914]},{"text":"7. Visit the Iron Market","box":[0.11905,0.08383,0.3167,0.09809]},{"text":"When visiting the Iron Market, players may \nspend Salvage to buy weapons, equipment and \nrecruit new Rigs for their Squadron. Rigs and \nEquipment a player owns goes into their \n“Hangar”, representing an inventory that \nholds the player’s Rigs and Equipment, that \ncan be stored until they are used.","box":[0.11905,0.11519,0.49102,0.23207]},{"text":"Weapons and Equipment may be bought for \nthe amount of Salvage equal to its Iron cost on \nthe equipment table.","box":[0.11905,0.24918,0.49102,0.29764]},{"text":"Recruiting a Rig represents acquiring a new \nchassis, refurbishing a recovered Rig or \nnegotiating \na \ncorporate \ncontract \nfor \nadditional war assets. New Rigs allow a \nSquadron to expand its operational capacity \nand replace machines lost during the \ncampaign. A Rig may be purchased for its \nSalvage cost using the table below.","box":[0.11905,0.31474,0.49102,0.44873]},{"text":"Equipping the Rig","box":[0.11905,0.58611,0.27235,0.60036]},{"text":"• \nA newly recruited Rig must be equipped \nbefore it can take part in an engagement.","box":[0.11905,0.61747,0.49102,0.64883]},{"text":"• \nA Rig comes with 5 or 6 Iron to spend on \nweapons (see table).","box":[0.11905,0.66593,0.49101,0.69729]},{"text":"• \nA Rig must have at least two weapons.","box":[0.11905,0.71439,0.45505,0.72865]},{"text":"• \nAdditional Weapons and equipment are \npurchased separately from the Iron \nMarket at their listed Salvage cost, which \nis the same as their Iron cost.","box":[0.11905,0.74575,0.49102,0.81132]},{"text":"• \nA Rig cannot exceed its maximum Iron \ncapacity when equipped.","box":[0.11905,0.82842,0.49102,0.85978]},{"text":"Rig Type\nSalvage Cost Starting Iron\nLight Rig\n4\n5\nMedium Rig\n8\n5\nHeavy Rig\n12\n6\nColossal Rig\n16\n6","box":[0.12073,0.46434,0.47958,0.56348]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":111,"number":108,"label":"108","title":"Scrapping and Mercenaries","width":2000,"height":2829,"blocks":[{"text":"Roll once on the Permanent Damage table for \neach of the following components:","box":[0.11905,0.08396,0.49032,0.11532]},{"text":"• Legs","box":[0.11905,0.13242,0.16791,0.14668]},{"text":"• Weapon (choose one mounted weapon)","box":[0.11905,0.16378,0.45162,0.17804]},{"text":"• Hull","box":[0.11905,0.19514,0.16725,0.20939]},{"text":"• Engine","box":[0.11905,0.2265,0.18825,0.24075]},{"text":"A second hand Rig therefore starts with four \npermanent negative traits, one for each \ncomponent type.","box":[0.11905,0.25786,0.49032,0.30632]},{"text":"These traits represent structural fatigue, faulty \nsystems, mismatched parts or previous \nbattlefield traumas. Players may not remove \nthese permanent traits through repairs.","box":[0.11905,0.32342,0.49032,0.38899]},{"text":"In addition, roll 1 D3 for each component. \nThey start with that much damage.","box":[0.11905,0.40609,0.49032,0.43745]},{"text":"Scrapping Rigs and Equipment","box":[0.11905,0.45456,0.38038,0.46881]},{"text":"While visiting the Iron Market, Rigs and \nEquipment can be scrapped or sold for salvage \nat half of their stated salvage costs, rounded \nup.","box":[0.11905,0.48591,0.49032,0.55148]},{"text":"Mercenary Nomad for Hire","box":[0.11905,0.56858,0.34797,0.58284]},{"text":"Squadrons operating in the Smoglands often \ncall upon independent Ironclads to reinforce \ntheir forces. These hired guns do not join the \nSquadron permanently, but offer temporary \nsupport during moments of desperation or \nopportunity.","box":[0.11905,0.59994,0.49032,0.69972]},{"text":"A Mercenary Support Slot provides a simple \nway for players to stay competitive in a \ncampaign, especially if they have suffered \nheavy losses or fallen behind in Salvage.","box":[0.11905,0.71682,0.49032,0.78239]},{"text":"Hiring a Mercenary Rig","box":[0.51425,0.08383,0.71316,0.09809]},{"text":"Once per campaign, during the Aftermath \nphase, a player may hire a Mercenary Rig for \na single engagement.","box":[0.51425,0.11519,0.88552,0.16365]},{"text":"Restrictions on Mercenary Rigs","box":[0.51425,0.18076,0.77809,0.19501]},{"text":"A Mercenary Rig is used for one engagement \nonly, then leaves the Squadron and cannot be \nretained. Mercenary Rigs are piloted by hired \noperators and have the following restrictions:","box":[0.51425,0.21212,0.88552,0.27768]},{"text":"• \nA Mercenary Rig costs no Salvage.","box":[0.51425,0.29479,0.82074,0.30904]},{"text":"• \nThe Rig is temporary and does not join the \nSquadron roster.","box":[0.51425,0.32614,0.88552,0.3575]},{"text":"• \nA Mercenary Rig may be a Light or \nMedium Rig (Heavy and Colossal Rigs are \ntoo costly or rare for short-term \ncontracts.)","box":[0.51425,0.37461,0.88553,0.44017]},{"text":"• \nMercenary Ironclads never gain or spend \nExperience, and cannot be assigned to \nother Rigs.","box":[0.51425,0.45728,0.88552,0.50574]},{"text":"• \nCannot capture or secure objectives","box":[0.51425,0.52285,0.83141,0.5371]},{"text":"• \nIf destroyed, a Mercenary Rig is simply \nlost. It may still be acquired through \nsalvage.","box":[0.51425,0.5542,0.88552,0.60267]},{"text":"Equipping a Mercenary Rig","box":[0.51425,0.61977,0.74497,0.63402]},{"text":"A Mercenary Rig comes pre-equipped with a \nbasic loadout provided by the contractor. \nThey come with their relevant starting Iron \ndependant on their weight class to spend on \nWeapons and Equipment. Rigs must always \nhave two weapons equipped.","box":[0.51425,0.65113,0.88552,0.7509]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":112,"number":109,"label":"109","title":"Squadron Reference Charts","width":2000,"height":2829,"blocks":[{"text":"Krim Corporation Rigs","box":[0.4061,0.37801,0.5939,0.39226]},{"text":"Mercenary Rigs","box":[0.43666,0.90918,0.56333,0.92344]},{"text":"Freegear Coalition Rigs","box":[0.40554,0.66229,0.59445,0.67655]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":113,"number":110,"label":"110","title":"Squadron Reference Charts","width":2000,"height":2829,"blocks":[{"text":"Triton Engineering Rigs","box":[0.40333,0.37801,0.59667,0.39226]},{"text":"Nox Industries Rigs","box":[0.4205,0.90918,0.57949,0.92344]},{"text":"Arcus Technologies Rigs","box":[0.39612,0.66229,0.59358,0.67655]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":114,"number":111,"label":"111","title":"Quick Reference","width":2000,"height":2829,"blocks":[{"text":"QUICK REFERENCE","box":[0.11905,0.08141,0.42823,0.11704]},{"text":"Phases of a Round:","box":[0.11905,0.13012,0.28217,0.14438]},{"text":"Initiative Phase: Roll a D12 to determine \nstarting player.","box":[0.11905,0.16148,0.49102,0.19284]},{"text":"Activation Phase: Take turns activating Rigs.","box":[0.11905,0.20994,0.48269,0.2242]},{"text":"Maintenance Phase: Roll for Heat Threshold, \nReduce heat by Exhaust value, handle other \nend of round effects.","box":[0.11905,0.2413,0.49102,0.28976]},{"text":"Actions (up to 5 per Rig):","box":[0.11905,0.30687,0.33168,0.32112]},{"text":"Move [1] up to full speed, pivot up to 90 \ndegrees, backpedal and side step at half speed.","box":[0.11905,0.55773,0.49102,0.58909]},{"text":"Fire Weapon / Melee Attack [1]","box":[0.11905,0.60619,0.38385,0.62045]},{"text":"Called Shot [1] choose hit location, -2 ACC, \ncannot hit engine from front arc.","box":[0.11905,0.63755,0.49102,0.66891]},{"text":"Ram [1]","box":[0.11905,0.68601,0.18755,0.70027]},{"text":"Reload [1] all weapons","box":[0.11905,0.81145,0.30471,0.8257]},{"text":"Repair [1] remove one condition or roll a D3 \nto repair that many structure points.","box":[0.11905,0.8428,0.49101,0.87416]},{"text":"Shut Down [0] forfeit activation to reduce \nengine heat to 0","box":[0.11905,0.89127,0.49102,0.92262]},{"text":"Use Equipment [X]","box":[0.51355,0.08383,0.67528,0.09809]},{"text":"Prepare [1] place relevant token face down","box":[0.51355,0.11519,0.85985,0.12944]},{"text":"• \nPrepare Evasive Manoeuvre: move when \ntargeted by an attack","box":[0.51355,0.14655,0.88552,0.17791]},{"text":"• \nPrepare Return Fire : retaliate with an \nattack","box":[0.51355,0.19501,0.88552,0.22637]},{"text":"• \nPrepare Brace for Incoming Fire:+2 \narmour roll against first front facing attack","box":[0.51355,0.24347,0.88552,0.27483]},{"text":"Attacking:","box":[0.51355,0.29194,0.60118,0.30619]},{"text":"1. Declare attacker and target","box":[0.51355,0.32329,0.74878,0.33755]},{"text":"2. Check range (after declaring target)","box":[0.51355,0.35465,0.81891,0.36891]},{"text":"3. Verify line of sight","box":[0.51355,0.38601,0.68133,0.40026]},{"text":"Light cover: -1 ACC; Heavy cover: -2 ACC","box":[0.51355,0.41737,0.84252,0.43162]},{"text":"4. Roll to hit","box":[0.51355,0.44873,0.61388,0.46298]},{"text":"5. Apply weapon effects","box":[0.51355,0.48008,0.70374,0.49434]},{"text":"6. Determine impact location","box":[0.51355,0.51144,0.75059,0.5257]},{"text":"7. Calculate damage","box":[0.51355,0.66823,0.67564,0.68249]},{"text":"Add together:","box":[0.51355,0.69959,0.62505,0.71384]},{"text":"+ Total strength from each successful hit","box":[0.51355,0.73095,0.83923,0.7452]},{"text":"+ 2 if attacking the side arc","box":[0.51355,0.76231,0.72941,0.77656]},{"text":"+ 4 if attacking the rear arc","box":[0.51355,0.79366,0.72945,0.80792]},{"text":"+ Perks","box":[0.51355,0.82502,0.57388,0.83928]},{"text":"8. Make Armour Rolls, negate 1 damage for \neach success.","box":[0.51355,0.85638,0.88552,0.88774]},{"text":"9. Update Rig’s structure points","box":[0.51355,0.90484,0.76585,0.9191]},{"text":"Action\nHeat\nMove\n1\nFire Weapon\n1\nMelee Attack\n1\nCalled Shot\n1\nRam\n1\nReload\n1\nRepair\n1\nShut Down\n0\nPrepare\n1\nUse Equipment\nX","box":[0.18141,0.34309,0.41701,0.53652]},{"text":"Roll\nImpact Location\n1-4\nHull\n5-7\nArms\n8-10\nLegs\n11-12\nEngine","box":[0.56383,0.54593,0.82244,0.63503]},{"text":"Weight Class\nHit STR\nPush Back\nLight\nD6 + 1\n2”\nMedium\nD6 + 2\n2”\nHeavy\nD6 + 3\n3”\nColossal\nD6 + 4\n3”","box":[0.12569,0.71197,0.46895,0.80009]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":115,"number":112,"label":"112","title":"Quick Reference · Heat and Damage","width":2000,"height":2829,"blocks":[{"text":"Heat Threshold:","box":[0.11905,0.08383,0.25389,0.09809]},{"text":"In the Maintenance Phase, each Rig rolls a D12 plus engine heat and compares the result:","box":[0.11905,0.11519,0.83256,0.12944]},{"text":"Catastrophic Damage:","box":[0.11905,0.52285,0.30696,0.5371]},{"text":"When a component's Structure Points reach 0, it becomes Catastrophically Damaged and the \neffects below apply. Further damage to a Catastrophically Damaged component Disables it. Two \nDisabled components destroy the Rig.","box":[0.11905,0.5542,0.88552,0.60267]},{"text":"Location\nCatastrophically Damaged\nDisabled","box":[0.14558,0.6257,0.75033,0.63877]},{"text":"Hull\nThe Rig is Stalled.\nThe Rig is stalled and Shocked.","box":[0.16416,0.65331,0.76241,0.66524]},{"text":"Arms\nRoll a D12 to determine affected arm.\n1-3 left, 4-6 right, that weapon is Disabled.\nBoth weapons are Disabled.","box":[0.16036,0.68123,0.74324,0.70736]},{"text":"Legs\nThe Rig is Slowed\nThe Rig is Immobilised. It can still pivot.","box":[0.16403,0.7233,0.82492,0.73523]},{"text":"Engine\nMove heat to Heat Threshold if heat is below\nHeat cannot be Exhausted / reduced.","box":[0.15524,0.7583,0.80486,0.77023]},{"text":"Result\nDescription\nEffect","box":[0.13116,0.15075,0.64562,0.16382]},{"text":"1-5\nNothing Happens\nThe engine performs as intended.","box":[0.14321,0.17723,0.61375,0.19036]},{"text":"6-7\nSystem Stall\nSuffer 2 damage to the Hull. The Rig is Stalled.","box":[0.14321,0.21135,0.70709,0.22447]},{"text":"8-9\nHydraulic Blowout\nSuffer 2 damage to the Legs. The Rig is Slowed.","box":[0.14321,0.24546,0.70967,0.25859]},{"text":"10-11\nAmmunition Detonation Suffer 2 damage to the Arms. The Rig is Shocked.","box":[0.13397,0.27921,0.7259,0.2927]},{"text":"12-13\nFuel Line Rupture\nRoll for an impact location. That component becomes Ruptured.","box":[0.13397,0.31369,0.83938,0.32681]},{"text":"14-15\nStructural Buckling\nEach component suffers 1 damage (Hull, Engine, Arms, Legs).","box":[0.13397,0.3478,0.82493,0.36093]},{"text":"16-17\nEmergency Shutdown The Rig powers down automatically. It cools to safe levels, reduce the","box":[0.13397,0.37414,0.87726,0.39504]},{"text":"heat to the start of the Heat Track, but must skip its next activation.","box":[0.36758,0.38982,0.86186,0.40288]},{"text":"18\nChain Reaction\nEach component suffers 1 damage (Hull, Engine, Arms, Legs) \nRoll again!","box":[0.14637,0.40825,0.88346,0.437]},{"text":"19\nEngine Failure\nThe Engine’s structure points are reduced to 0 and suffers Catastrophic \nDamage. If it is already Catastrophically Damaged, it becomes Disabled.","box":[0.14637,0.44306,0.86335,0.47024]},{"text":"20+\nCatastrophic Failure\nThe Rig suffers Catastrophic Damage to all components.\nHeat can no longer be decreased.","box":[0.14103,0.47648,0.77721,0.50523]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":116,"number":113,"label":"113","title":"Rules Glossary","width":2000,"height":2829,"blocks":[{"text":"RULES GLOSSARY","box":[0.11905,0.08141,0.4145,0.11704]},{"text":"ACC (Accuracy) - A modifier applied to attack \nrolls that makes attacks easier or harder to hit.","box":[0.11905,0.1308,0.47116,0.16079]},{"text":"Action - A task a Rig performs during its \nactivation, such as moving, firing weapons, \nrepairing, or preparing a reaction.","box":[0.11905,0.17414,0.43954,0.22105]},{"text":"Activation - A Rig’s turn during the Activation \nPhase. A Rig may perform up to 5 actions when \nactivated.","box":[0.11905,0.23441,0.47491,0.28131]},{"text":"Arc - The directional facing zones of a Rig: Front, \nSide, and Rear.","box":[0.11905,0.29467,0.48685,0.32466]},{"text":"Armour - A defensive value representing a Rig \ncomponent’s ability to resist damage.","box":[0.11905,0.33801,0.46815,0.368]},{"text":"Armour Piercing X - A weapon perk that \nincreases the target Rig’s armour roll target \nnumber by X.","box":[0.11905,0.38136,0.43875,0.42826]},{"text":"Armour Roll - A defensive roll made after \ndamage is calculated. Each successful result equal \nto or above the armour value negates 1 damage.","box":[0.11905,0.44162,0.48687,0.48853]},{"text":"Bombardment - A weapon perk allowing attacks \nwithout line of sight at long range.","box":[0.11905,0.50188,0.48565,0.53187]},{"text":"Breaching - A weapon perk where critical hits \ninflict 1 direct damage to the affected component \nwithout an Armour Roll.","box":[0.11905,0.54523,0.48472,0.59213]},{"text":"Called Shot - An attack that targets a specific \ncomponent instead of rolling for impact location, \nsuffering -2 ACC.","box":[0.11905,0.60549,0.48576,0.6524]},{"text":"Campaign - A linked series of engagements \nwhere Rigs, Ironclads, salvage, and damage \npersist between battles.","box":[0.11905,0.66575,0.44678,0.71266]},{"text":"Catastrophically Damaged - A component \nreduced to 0 Structure Points. It suffers severe \npenalties and cannot be repaired.","box":[0.11905,0.72602,0.45992,0.77292]},{"text":"Chain Reaction - A Heat Threshold result \ncausing all components to suffer damage before \nrolling again on the Heat Threshold table.","box":[0.11905,0.78628,0.47266,0.83318]},{"text":"Colossal Rig - The largest Rig weight class, \nmounted on an 80mm base.","box":[0.11905,0.84654,0.43962,0.87653]},{"text":"Component - A section of a Rig: Hull, Arms, \nLegs, or Engine.","box":[0.51355,0.08398,0.8508,0.11396]},{"text":"Condition - A status effect affecting a Rig’s \nperformance, such as Shocked, Slowed, or Stalled.","box":[0.51355,0.12732,0.87967,0.15731]},{"text":"Cover - Terrain or obstruction reducing the \neffectiveness of attacks. Cover may be Light or \nHeavy.","box":[0.51355,0.17066,0.85738,0.21757]},{"text":"Critical Hit - Triggered when an attack roll \nscores a natural 6, or by certain weapon perks.","box":[0.51355,0.23093,0.85345,0.26091]},{"text":"D3 - A three-result roll generated using a D6:\n1–2 = 1, 3–4 = 2, 5–6 = 3.","box":[0.51355,0.27427,0.84783,0.30426]},{"text":"D6 - A six-sided dice.","box":[0.51355,0.31761,0.67368,0.33068]},{"text":"D12 - A twelve-sided dice.","box":[0.51355,0.34404,0.70926,0.3571]},{"text":"Damage Pool - The total attack strength \ngenerated before Armour Rolls are made.","box":[0.51355,0.37046,0.81793,0.40045]},{"text":"Deployment - The starting positions of both \nsquadrons at the beginning of an engagement.","box":[0.51355,0.4138,0.85295,0.44379]},{"text":"Destroyed - The state of a whole Rig once 2 of its \ncomponents are Disabled, removing it from play.","box":[0.51355,0.45715,0.8788,0.48713]},{"text":"Disabled - A component that has taken further \ndamage after becoming Catastrophically \nDamaged. Disabled components cannot be \nRepaired (except between battles in a Campaign) \nor targeted further. If 2 of a Rig's components are \nDisabled, the Rig is Destroyed.","box":[0.51355,0.50049,0.87878,0.59816]},{"text":"Emergency Shutdown - A Heat Threshold result \nwhere a Rig cools to safe levels but skips its next \nactivation.","box":[0.51355,0.61151,0.87765,0.65842]},{"text":"Engagement - A single battle played in Of Oil \nand Iron.","box":[0.51355,0.67178,0.85666,0.70176]},{"text":"Engine - The Rig component responsible for heat \nmanagement and power generation.","box":[0.51355,0.71512,0.88098,0.7451]},{"text":"Engine Exhaust - The amount of heat removed \nduring the Maintenance Phase.","box":[0.51355,0.75846,0.86531,0.78845]},{"text":"Engine Failure - A catastrophic Heat Threshold \nresult causing immediate catastrophic damage to \nthe Engine component.","box":[0.51355,0.8018,0.87664,0.84871]},{"text":"Explode - A destructive effect that may occur \nwhen a Rig is destroyed, damaging nearby Rigs.","box":[0.51355,0.86207,0.86398,0.89205]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":117,"number":114,"label":"114","title":"Rules Glossary (continued)","width":2000,"height":2829,"blocks":[{"text":"Explosive X - A weapon perk causing secondary \ndamage to nearby units within X”.","box":[0.11905,0.08398,0.48084,0.11396]},{"text":"Fire Weapon - An action allowing a Rig to attack \nusing a ranged weapon.","box":[0.11905,0.12732,0.48561,0.15731]},{"text":"Flanking - A weapon perk that increases damage \nwhen attacking side (+2) or rear (+4) arcs.","box":[0.11905,0.17066,0.48531,0.20065]},{"text":"Front Arc - The primary facing direction of a \nRig. Most weapons can only fire into this arc.","box":[0.11905,0.21401,0.45726,0.24399]},{"text":"Heat - A resource generated by actions and \nweapons. Excessive heat risks catastrophic engine \neffects.","box":[0.11905,0.25735,0.48679,0.30426]},{"text":"Heat Threshold - The danger zone on the heat \ntrack where engine failures may occur, the first \nnumbered space (even a 0+).","box":[0.11905,0.31761,0.4672,0.36452]},{"text":"Heavy Cover - Cover that heavily obscures a Rig, \napplying -2 ACC to attacks.","box":[0.11905,0.37788,0.48585,0.40786]},{"text":"Hit Location - The component struck by an \nattack, determined by a D12 roll or Called Shot.","box":[0.11905,0.42122,0.47027,0.45121]},{"text":"Hot - A weapon perk that may generate \nadditional engine heat after attacking.","box":[0.11905,0.46456,0.41543,0.49455]},{"text":"Hull - The central body component of a Rig.","box":[0.11905,0.50791,0.44592,0.52097]},{"text":"Hull Weapon - A weapon mounted internally or \ncentrally on a Colossal Rig.","box":[0.11905,0.53433,0.4813,0.56431]},{"text":"Immobilised - A condition preventing a Rig \nfrom moving, though it may still pivot.","box":[0.11905,0.57767,0.45094,0.60766]},{"text":"Impact Location - The component struck when \nresolving attacks.","box":[0.11905,0.62101,0.47707,0.651]},{"text":"Impale - A weapon perk that applies the \nImmobilised condition on a critical hit.","box":[0.11905,0.66436,0.42084,0.69434]},{"text":"Improbable Result - A roll requiring 7+ on a D6. \nResolve by rolling 6s, then re-rolling them for 4+ \nsuccesses.","box":[0.11905,0.7077,0.48779,0.75461]},{"text":"Incendiary X - A weapon perk increasing the \ntarget Rig’s engine heat by X when hit.","box":[0.11905,0.76796,0.45907,0.79795]},{"text":"Initiative - Determines activation order each \nround, a contested roll with +1 for each Light Rig.","box":[0.11905,0.81131,0.48589,0.84129]},{"text":"Iron - The loadout capacity of a Rig used to equip \nweapons and equipment.","box":[0.11905,0.85465,0.48879,0.88464]},{"text":"Ironclad - A Rig pilot whose skill determines the \nRig’s Aim value.","box":[0.51355,0.08398,0.87889,0.11396]},{"text":"Light Cover - Partial cover applying -1 ACC to \nattacks.","box":[0.51355,0.12732,0.86511,0.15731]},{"text":"Line of Sight (LOS) - Determines whether one \nRig can see and target another.","box":[0.51355,0.17066,0.8645,0.20065]},{"text":"Maintenance Phase - The final phase of a round \nwhere heat, repairs, and end-of-round effects are \nresolved.","box":[0.51355,0.21401,0.87549,0.26091]},{"text":"Melee - A weapon perk indicating the weapon \ndoes not require reloading.","box":[0.51355,0.27427,0.8586,0.30426]},{"text":"Melee Attack - An attack made using melee \nweapons at close range.","box":[0.51355,0.31761,0.84075,0.3476]},{"text":"Natural Roll - A dice result unaffected by \nmodifiers, such as a natural 1 always failing.","box":[0.51355,0.36096,0.83587,0.39094]},{"text":"Objective - A marker or battlefield location used \nfor mission scoring.","box":[0.51355,0.4043,0.87701,0.43429]},{"text":"Penetrating - A weapon perk where hit rolls of \n5+ count as critical hits.","box":[0.51355,0.44764,0.86368,0.47763]},{"text":"Permanent Negative Trait - A lasting penalty \ngained when repairing catastrophically damaged \nor destroyed components during campaigns.","box":[0.51355,0.49099,0.87501,0.53789]},{"text":"Pivot - Rotating a Rig during movement.","box":[0.51355,0.55125,0.81558,0.56431]},{"text":"Precision - A weapon perk allowing Called Shots \nwithout suffering the -2 ACC penalty.","box":[0.51355,0.57767,0.8807,0.60766]},{"text":"Prepare - An action allowing a Rig to set a \nhidden reaction that may trigger during the \nopponent’s activation.","box":[0.51355,0.62101,0.83901,0.66792]},{"text":"Prepare Brace for Incoming Fire - A Prepare \naction granting +2 to Armour Rolls against the \nnext front or side facing attack.","box":[0.51355,0.68128,0.86315,0.72818]},{"text":"Prepare Evasive Manoeuvre - A Prepare action \nallowing a Rig to move when targeted by an \nattack.","box":[0.51355,0.74154,0.86978,0.78845]},{"text":"Prepare Return Fire - A Prepare action allowing \na Rig to retaliate after being attacked.","box":[0.51355,0.8018,0.87784,0.83179]},{"text":"Ram - An action allowing a Rig to crash into an \nenemy after moving at least 2”. Both Rigs suffer \nhits based on the attacker’s weight class.","box":[0.51355,0.84515,0.86998,0.89205]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":118,"number":115,"label":"115","title":"Rules Glossary (continued)","width":2000,"height":2829,"blocks":[{"text":"Rate of Fire (ROF) - The number of attack dice \nrolled when firing a weapon.","box":[0.11905,0.08398,0.47291,0.11396]},{"text":"Rear Arc - The vulnerable rear facing of a Rig. \nAttacks here gain additional damage (+4).","box":[0.11905,0.12732,0.46343,0.15731]},{"text":"Reload - An action required to fire ranged \nweapons again during the same activation.","box":[0.11905,0.17066,0.43512,0.20065]},{"text":"Repair - An action used to restore Structure \nPoints or remove conditions.","box":[0.11905,0.21401,0.44841,0.24399]},{"text":"Rig - A diesel-powered war machine piloted by \nan Ironclad.","box":[0.11905,0.25735,0.47129,0.28734]},{"text":"Rig Control Terminal - The primary game asset \nused to track a Rig’s stats, damage, heat, and \nloadout.","box":[0.11905,0.30069,0.47992,0.3476]},{"text":"Round - A complete cycle of Initiative, \nActivation, and Maintenance phases.","box":[0.11905,0.36096,0.40907,0.39094]},{"text":"Ruptured - A persistent condition causing \nongoing damage.","box":[0.11905,0.4043,0.43623,0.43429]},{"text":"Salvage - Resources recovered after engagements \nand used during campaigns.","box":[0.11905,0.44764,0.48419,0.47763]},{"text":"Shock - A weapon perk that applies the Shocked \ncondition on a critical hit.","box":[0.11905,0.49099,0.47962,0.52097]},{"text":"Shocked - A condition reducing a Rig’s ACC (-1) \nand SPD (-1).","box":[0.11905,0.53433,0.48522,0.56431]},{"text":"Side Arc - The side facing of a Rig. Attacks here \ngain additional damage (+2).","box":[0.11905,0.57767,0.47378,0.60766]},{"text":"Slowed - A condition reducing a Rig’s Speed.","box":[0.11905,0.62101,0.44982,0.63408]},{"text":"Smogfall - The industrial catastrophe that \npoisoned the skies and reshaped civilisation.","box":[0.11905,0.64744,0.44553,0.67742]},{"text":"Smoglands - The polluted wasteland where Of \nOil and Iron takes place.","box":[0.11905,0.69078,0.46622,0.72077]},{"text":"SPD (Speed) - The maximum movement \ndistance of a Rig, in inches.","box":[0.11905,0.73412,0.42686,0.76411]},{"text":"Squadron - A collection of Rigs controlled by a \nplayer.","box":[0.11905,0.77747,0.47203,0.80745]},{"text":"Staggering - A weapon perk that may pivot or \npush the target Rig after a successful hit.","box":[0.11905,0.82081,0.4636,0.8508]},{"text":"Stalled - A condition causing a Rig to lose 2 \nactions during its next activation.","box":[0.11905,0.86415,0.44667,0.89414]},{"text":"STR (Strength) - The power of a weapon’s attack.","box":[0.51355,0.08398,0.87592,0.09704]},{"text":"Structure Points - The durability value of a Rig \ncomponent.","box":[0.51355,0.1104,0.86594,0.14039]},{"text":"Sustained Fire - A weapon perk increasing \ndamage output through repeated hits.","box":[0.51355,0.15374,0.83535,0.18373]},{"text":"Volatile - A weapon perk increasing damage \nwhile above the Heat Threshold.","box":[0.51355,0.19709,0.84604,0.22707]},{"text":"Weapon Perk - A special rule attached to a \nweapon that alters its behaviour or effectiveness.","box":[0.51355,0.24043,0.86854,0.27042]},{"text":"Weapon Slot - A mounting point available for \nequipping weapons on a Rig.","box":[0.51355,0.28377,0.85749,0.31376]},{"text":"Weight Class - The category of Rig size: Light \n(40mm base), Medium (50mm base), Heavy \n(60mm base), or Colossal (80mm base).","box":[0.51355,0.32712,0.85424,0.37402]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":119,"number":null,"label":"Back matter","title":"FINAL TRANSMISSION","width":2000,"height":2829,"blocks":[{"text":"FINAL TRANSMISSION","box":[0.38639,0.12182,0.61358,0.1432]},{"text":"The engines will cool.The smoke will settle.","box":[0.32711,0.15945,0.67289,0.1737]},{"text":"The wrecks will be stripped down to bare frames and broken pistons.","box":[0.22422,0.1908,0.77578,0.20506]},{"text":"Oil will be siphoned from the fallen.","box":[0.35469,0.25352,0.6453,0.26777]},{"text":"Names will be carved into iron, or forgotten beneath it.","box":[0.2793,0.28488,0.72069,0.29913]},{"text":"There are no clean victories in the Smoglands. Only contracts fulfilled.","box":[0.21796,0.34759,0.78204,0.36185]},{"text":"Only survivors who live long enough to take the next one.","box":[0.26772,0.37895,0.73227,0.39321]},{"text":"Corporations will claim control. Rebels will claim freedom.","box":[0.26244,0.44167,0.73756,0.45592]},{"text":"And somewhere between the two, a Rig will ignite its engine for the first time… or its last.","box":[0.13962,0.47303,0.86037,0.48728]},{"text":"This book is not a manual.","box":[0.39398,0.53574,0.60601,0.55]},{"text":"It is a toolbox, a warning, and an invitation.","box":[0.32529,0.5671,0.6747,0.58135]},{"text":"Bend the rules when the story demands it. Write new contracts.","box":[0.24494,0.62982,0.75505,0.64407]},{"text":"Let Rigs earn names, reputations, and scars that outlive their pilots.","box":[0.23067,0.66117,0.76933,0.67543]},{"text":"When the battlefield falls silent, remember this:","box":[0.30963,0.72389,0.69036,0.73814]},{"text":"The war doesn’t end. It just changes hands.","box":[0.32941,0.75525,0.67058,0.7695]},{"text":"Warm up your engines.","box":[0.40584,0.81796,0.59416,0.83222]},{"text":"The next contract is already waiting.","box":[0.35485,0.84932,0.64514,0.86358]},{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":120,"number":null,"label":"Illustration","title":"Illustration","width":2000,"height":2829,"blocks":[{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]},{"index":121,"number":null,"label":"Back cover","title":"Illustration","width":2000,"height":2829,"blocks":[{"text":"Psychomystile\n© Scoutsifer Studio. All Rights Reserved","box":[0.03333,0.95055,0.27402,0.97708]}],"refs":[]}]};
